interface VerificationArgs {
  email: string;
  expirationTime: number;
}

export async function createVerification({
  email,
  expirationTime,
}: VerificationArgs): Promise<{ otp: string; linkToken: string }> {
  const otp = otpLib.totp.gen(email, { time: expirationTime });
  const linkToken = crypto.randomBytes(32).toString('hex');
  await prisma.verification.create({
    data: {
      verificationTarget: email,
      type: 'email_verification',
      otp,
      linkToken,
      expirationTime: Math.floor(Date.now() / 1000) + expirationTime,
    },
  });
  return { otp, linkToken };
}

export async function verifyOTP(email: string, otp: string): Promise<boolean> {
  const verification = await prisma.verification.findUnique({
    where: { verificationTarget_type: { verificationTarget: email, type: 'email_verification' } },
  });
  if (!verification) return false;
  const isValid = otpLib.totp.verify(otp, verification.secretKey, { time: verification.expirationTime });
  if (isValid) {
    // Handle post-verification process
  }
  return isValid;
}

export async function verifyLinkToken(linkToken: string): Promise<boolean> {
  const verification = await prisma.verification.findUnique({
    where: { linkToken },
  });
  if (!verification || Date.now() / 1000 > verification.expirationTime) return false;
  // Handle post-verification process
  return true;
}

