namespace RPC.Core.ContractIO;

public class ContractRpc
{
    private readonly IAccountProvider accountProvider;
    private readonly IWeb3 web3;
    private readonly IGasEstimator gasEstimator;
    private readonly IGasPricer gasPricer;
    private readonly ITransactionSigner transactionSigner;
    private readonly ITransactionSender transactionSender;

    public ContractRpc(
        IAccountProvider accountProvider,
        IWeb3 web3,
        IGasEstimator gasEstimator,
        IGasPricer gasPricer,
        ITransactionSigner transactionSigner,
        ITransactionSender transactionSender
    )
    {
        this.accountProvider = accountProvider;
        this.web3 = web3;
        this.gasEstimator = gasEstimator;
        this.gasPricer = gasPricer;
        this.transactionSigner = transactionSigner;
        this.transactionSender = transactionSender;
    }

    public virtual async Task<string> ExecuteActionAsync(RpcRequest request) =>
        await GetContractIO(request).RunContractActionAsync();

    private IContractIO GetContractIO(RpcRequest request) =>
        request.ActionType == ActionType.Read ?
        new ContractRpcReader(request, web3) : // assuming ContractRpcReader needs the web3
        new ContractRpcWriter(
            request,
            accountProvider,
            web3,
            gasEstimator,
            gasPricer,
            transactionSigner,
            transactionSender
        );
}

using RPC.Core.Types;
using RPC.Core.Models;
using RPC.Core.Providers;

namespace RPC.Core.ContractIO;

public class ContractRpc
{
    private readonly IMnemonicProvider mnemonicProvider;
    private readonly IServiceProvider serviceProvider;

    public ContractRpc(IMnemonicProvider mnemonicProvider, IServiceProvider serviceProvider)
    {
        this.mnemonicProvider = mnemonicProvider;
        this.serviceProvider = serviceProvider;
    }

    public virtual string ExecuteAction(RpcRequest request) =>
        GetContractIO(request).RunContractAction();

    private IContractIO GetContractIO(RpcRequest request) =>
        request.ActionType == ActionType.Read ?
        new ContractRpcReader(request) :
        CreateContractRpcWriter(request);

    private IContractIO CreateContractRpcWriter(RpcRequest request)
    {
        var accountProvider = (IAccountProvider)serviceProvider.GetService(typeof(IAccountProvider));
        var web3 = (IWeb3)serviceProvider.GetService(typeof(IWeb3));
        var gasEstimator = (IGasEstimator)serviceProvider.GetService(typeof(IGasEstimator));
        var gasPricer = (IGasPricer)serviceProvider.GetService(typeof(IGasPricer));
        var transactionSigner = (ITransactionSigner)serviceProvider.GetService(typeof(ITransactionSigner));
        var transactionSender = (ITransactionSender)serviceProvider.GetService(typeof(ITransactionSender));

        return new ContractRpcWriter(request, mnemonicProvider, accountProvider, web3, gasEstimator, gasPricer, transactionSigner, transactionSender);
    }
}

