// Main function to scrape all plugin data
async function scrapeAllPlugins() {
    // Click the "All" button
    let buttons = document.querySelectorAll('button');
    let allButton = Array.from(buttons).find(btn => btn.textContent.trim() === 'All');
    if (allButton) {
        allButton.click();
    }

    await sleep(2000);  // Wait for the page to load

    // Fetch the first batch to get the total count
    const firstBatch = await fetchPluginData(0, 8);
    const totalCount = firstBatch.count;

    let allPlugins = [...firstBatch.items];
    let offset = 8;  // We've already fetched the first 8

    while (offset < totalCount) {
        const batch = await fetchPluginData(offset, 8);
        allPlugins = [...allPlugins, ...batch.items];
        offset += 8;
        await sleep(1000);  // Wait for a second before fetching the next batch
    }

    return allPlugins;
}

