import passport, { Strategy } from 'passport';
import { Strategy as OAuth2Strategy } from 'passport-oauth2';
import { NextApiRequest, NextApiResponse } from 'next';
import crypto from 'crypto';

// ... (rest of the code, including the mock database and Passport strategy setup)

// Generate a state token
function generateStateToken(): string {
  return crypto.randomBytes(16).toString('hex');
}

export default (req: NextApiRequest, res: NextApiResponse) => {
  const state = generateStateToken();
  // Store the state token in the session or a server-side cache for later verification
  // For this demo, we'll just log it, but in a real application, you'd store it securely
  console.log(`Generated state token: ${state}`);

  passport.authenticate('oauth2' as Strategy, { state }, (err: any, user: any, info: any) => {
    if (err) {
      return res.status(500).json({ error: 'Authentication initiation failed' });
    }
    if (!user) {
      // If no user is returned, redirect to the OAuth provider
      return res.redirect(info.redirect);
    }
    // Handle any other cases if necessary
  })(req, res);
};

