type Result<T, E extends Error> = { kind: "success", value: T } | { kind: "failure", error: E };

function riskyFunction(): Result<number, Error> {
    try {
        // Some code that may throw an error
        let value = 42;
        return { kind: "success", value: value };
    } catch (error) {
        return { kind: "failure", error: error };
    }
}

function callingFunction() {
    let result = riskyFunction();
    if (result.kind === "failure") {
        console.error(result.error);
        return;
    }
    // Here, TypeScript knows result is { kind: "success", value: number }
    console.log(result.value);
}

