#include <iostream>
#include <vector>
#include <stdexcept>

class Node {
public:
    int value;
    Node* next;
    Node* prev;

    Node(int val): value(val), next(nullptr), prev(nullptr) {}
};

class Queue {
private:
    Node* head;
    Node* tail;
    std::vector<Node*> arr;

public:
    Queue(): head(nullptr), tail(nullptr) {}

    ~Queue() {
        while (head) {
            Node* temp = head;
            head = head->next;
            delete temp;
        }
    }

    void push(int value) {
        Node* newNode = new Node(value);

        if (!head) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            newNode->prev = tail;
            tail = newNode;
        }

        arr.push_back(newNode);
    }

    int pop() {
        if (!head) {
            throw std::out_of_range("Queue is empty");
        }

        Node* temp = head;
        int ret_val = head->value;

        if (head == tail) {
            head = tail = nullptr;
        } else {
            head = head->next;
            head->prev = nullptr;
        }

        arr.erase(arr.begin());
        delete temp;

        return ret_val;
    }

    int peek(int i) {
        if (i < 0 || i >= arr.size()) {
            throw std::out_of_range("Index out of range");
        }
        return arr[i]->value;
    }
};

int main() {
    Queue q;
    q.push(1);
    q.push(2);
    q.push(3);

    std::cout << q.peek(0) << std::endl;  // 1
    std::cout << q.peek(1) << std::endl;  // 2
    std::cout << q.peek(2) << std::endl;  // 3

    std::cout << q.pop() << std::endl;    // 1
    std::cout << q.peek(0) << std::endl;  // 2

    return 0;
}

import fs from 'fs-extra';
import path from 'path';

// Input and output directories
const inputDir = 'data';
const outputDir = 'src/questions';

// Read all files from the input directory
fs.readdir(inputDir, (err, files) => {
  if (err) {
    console.error(`Unable to read directory: ${err}`);
    return;
  }

  files.forEach(file => {
    // Only process .json files
    if (path.extname(file) !== '.json') {
      return;
    }

    // Read the file
    fs.readFile(path.join(inputDir, file), 'utf-8', (err, data) => {
      if (err) {
        console.error(`Unable to read file: ${file}`);
        return;
      }

      // Process the file (here we just parse and stringify to format)
      let jsonData;
      try {
        jsonData = JSON.parse(data);
      } catch (err) {
        console.error(`Unable to parse JSON file: ${file}`);
        return;
      }

      const formattedData = JSON.stringify(jsonData, null, 2);

      // Write the processed file to the output directory
      fs.writeFile(path.join(outputDir, file), formattedData, 'utf-8', err => {
        if (err) {
          console.error(`Unable to write file: ${file}`);
        } else {
          console.log(`Processed file: ${file}`);
        }
      });
    });
  });
});

