document.addEventListener('mouseup', function(event) {
    if (isDragging) {
        isDragging = false;

        // Determine the planchette's center coordinates
        let rect = planchette.getBoundingClientRect();
        let centerX = rect.left + (rect.width / 2);
        let centerY = rect.top + (rect.height / 2);

        // Temporarily hide the planchette to get the underlying element
        planchette.style.display = 'none';
        let targetElement = document.elementFromPoint(centerX, centerY);
        planchette.style.display = '';

        // Log the text content of the target element
        if (targetElement) {
            console.log("Stopped on: " + targetElement.textContent);
        }
    }
});

document.addEventListener('mousemove', function(event) {
    if (isDragging) {
        planchette.style.left = `${event.clientX - offsetX}px`;
        planchette.style.top = `${event.clientY - offsetY}px`;
    }
});

function moveTo(id) {
    let targetElement = document.getElementById(id);
    let rect = targetElement.getBoundingClientRect();

    // Get the center of the target element
    let targetX = rect.left + (rect.width / 2);
    let targetY = rect.top + (rect.height / 2);

    // Get the initial position of the planchette
    let planchetteRect = planchette.getBoundingClientRect();
    let startX = planchetteRect.left + (planchetteRect.width / 2);
    let startY = planchetteRect.top + (planchetteRect.height / 2);

    // Calculate distance to move per frame
    let dx = (targetX - startX) / 60;
    let dy = (targetY - startY) / 60;

    // Animate the movement
    let frames = 0;
    function animate() {
        if (frames < 60) {
            startX += dx;
            startY += dy;
            // Calculate the center of the planchette
            let planchetteCenterX = planchette.offsetWidth / 2;
            let planchetteCenterY = planchette.offsetHeight / 2;
            planchette.style.left = `${startX - planchetteCenterX}px`;
            planchette.style.top = `${startY - planchetteCenterY}px`;
            frames++;
            window.requestAnimationFrame(animate);
        }
    }
    animate();
}

