async function spellResponse(response) {
    // Remove punctuation from the response
    response = response.replace(/[^\w\s]|_/g, "").replace(/\s+/g, " ");
    output.textContent = "";

    // Split the response into individual words
    let responseElements = response.toLowerCase().split(' ');
    const words = ['yes', 'no', 'hello', 'goodbye'];

    // Check each word against the list of special words
    for (let i = 0; i < responseElements.length; i++) {
        let word = responseElements[i];
        if (words.includes(word)) {
            // If the word is in the list of special words, replace it with the special word
            responseElements[i] = word;
        } else {
            // If the word is not in the list of special words, split it into characters
            responseElements[i] = word.split('');
        }
    }

    // Flatten the array
    responseElements = [].concat.apply([], responseElements);

    // Move to each character or word in turn
    for (let i = 0; i < responseElements.length; i++) {
        let element = responseElements[i];
        if (element.trim() !== '') {
            await moveTo(element.trim());
            // Wait for 1 second before moving to the next character or word
            await new Promise(resolve => setTimeout(resolve, 1000));
        }
    }
}

