protocol Copyable {
    func copy() -> Self
}

class MyClass: Copyable {
    var value: Int

    init(value: Int) {
        self.value = value
    }

    func copy() -> Self {
        return type(of: self).init(value: self.value)
    }
}

protocol MyProtocol {
    associatedtype ShardType: AnyObject
    static var shardType: ShardType.Type { get }
    static func getInputTypesFunc() -> SHInputTypesProc
}

extension MyProtocol {
    static func getInputTypesFunc() -> SHInputTypesProc {
        return { bridgeInputTypes(Self.shardType, shard: $0) }
    }
}

class MyShard: MyProtocol {
    typealias ShardType = MyShard
    static var shardType: ShardType.Type { return ShardType.self }
}

class MyOtherShard: MyProtocol {
    typealias ShardType = MyOtherShard
    static var shardType: ShardType.Type { return ShardType.self }
}

protocol AbstractClass {
    func methodToOverride()
    func abstractMethod()
}

extension AbstractClass {
    func methodToOverride() {
        fatalError("This method should be overriden in a subclass")
    }

    func abstractMethod() {
        methodToOverride()
    }
}

class ConcreteClass: AbstractClass {
