void RemoveFunction(const std::function<void(Args...)>& functionToRemove)
{
    m_Functions.erase(std::remove_if(m_Functions.begin(), m_Functions.end(),
        [&](const std::function<void(Args...)>& function)
        {
            return function.target<void(Args...)>() == functionToRemove.target<void(Args...)>();
        }), m_Functions.end());
}

template<typename ...Args>
class Delegate
{
public:
    using MiniginDelegate = std::function<void(Args...)>;

private:
    struct FunctionWrapper
    {
        MiniginDelegate function;
        int identifier;
    };

public:
    Delegate() = default;
    ~Delegate() = default;
    Delegate(const Delegate& other) = delete;
    Delegate(Delegate&& other) noexcept = delete;
    Delegate& operator=(const Delegate& other) = delete;
    Delegate& operator=(Delegate&& other) noexcept = delete;

    void AddFunction(std::function<void(Args...)> function)
    {
        int nextIdentifier = GenerateNextIdentifier();
        m_Functions.emplace_back(FunctionWrapper{ std::move(function), nextIdentifier });
    }

    template<typename Lambda>
    void AddLambda(Lambda lambda)
    {
        int nextIdentifier = GenerateNextIdentifier();
        std::function<void(Args...)> function = lambda;
        m_Functions.emplace_back(FunctionWrapper{ std::move(function), nextIdentifier });
    }

    void RemoveFunction(int identifier)
    {
        m_Functions.erase(std::remove_if(m_Functions.begin(), m_Functions.end(),
            [identifier](const FunctionWrapper& wrapper)
            {
                return wrapper.identifier == identifier;
            }), m_Functions.end());
    }

    void Invoke(Args... args)
    {
        for (const FunctionWrapper& wrapper : m_Functions)
        {
            wrapper.function(args...);
        }
    }

    void Clear()
    {
        m_Functions.clear();
    }

private:
    int GenerateNextIdentifier()
    {
        static int nextIdentifier = 0;
        return ++nextIdentifier;
    }

    std::vector<FunctionWrapper> m_Functions;
};

template<typename ...Args>
class Delegate
{
public:
    using MiniginDelegate = std::function<void(Args...)>;
    using FunctionWrapper = std::weak_ptr<MiniginDelegate>;

    Delegate() = default;
    ~Delegate() = default;
    Delegate(const Delegate& other) = delete;
    Delegate(Delegate&& other) noexcept = delete;
    Delegate& operator=(const Delegate& other) = delete;
    Delegate& operator=(Delegate&& other) noexcept = delete;

    void AddFunction(std::function<void(Args...)> function)
    {
        auto wrapper = std::make_shared<MiniginDelegate>(std::move(function));
        m_Functions.push_back(wrapper);
    }

    void Invoke(Args... args)
    {
        for (const auto& wrapper : m_Functions)
        {
            if (auto function = wrapper.lock())
            {
                (*function)(args...);
            }
        }
    }

    void Clear()
    {
        m_Functions.clear();
    }

private:
    std::vector<FunctionWrapper> m_Functions;
};

template<typename ...Args>
class Delegate
{
public:
    using MiniginDelegate = std::function<void(Args...)>;

    Delegate() = default;
    ~Delegate() = default;
    Delegate(const Delegate& other) = delete;
    Delegate(Delegate&& other) noexcept = delete;
    Delegate& operator=(const Delegate& other) = delete;
    Delegate& operator=(Delegate&& other) noexcept = delete;

    void AddFunction(std::shared_ptr<MiniginDelegate> function)
    {
        m_Functions.push_back(function);
    }

    void Invoke(Args... args)
    {
        for (const auto& function : m_Functions)
        {
            if (function)
            {
                (*function)(args...);
            }
        }
    }

    void Clear()
    {
        m_Functions.clear();
    }

    void RemoveFunctionsForDeletedObject(const std::shared_ptr<void>& object)
    {
        m_Functions.erase(std::remove_if(m_Functions.begin(), m_Functions.end(),
            [&](const std::shared_ptr<MiniginDelegate>& function)
            {
                return function && function->target<void>() && function->target<void>()->template owner<void>() == object;
            }), m_Functions.end());
    }

private:
    std::vector<std::shared_ptr<MiniginDelegate>> m_Functions;
};

template<typename ...Args>
class Delegate
{
public:
    using MiniginDelegate = std::function<void(Args...)>;

    Delegate() = default;
    ~Delegate() = default;
    Delegate(const Delegate& other) = delete;
    Delegate(Delegate&& other) noexcept = delete;
    Delegate& operator=(const Delegate& other) = delete;
    Delegate& operator=(Delegate&& other) noexcept = delete;

    void AddFunction(const MiniginDelegate& function)
    {
        m_Functions.push_back(function);
    }

    void Invoke(Args... args)
    {
        for (const auto& function : m_Functions)
        {
            function(args...);
        }
    }

    void Clear()
    {
        m_Functions.clear();
    }

    void RemoveFunctionsForDeletedObject(const std::shared_ptr<void>& object)
    {
        m_Functions.erase(std::remove_if(m_Functions.begin(), m_Functions.end(),
            [&](const MiniginDelegate& function)
            {
                auto functionOwner = GetFunctionOwner(function);
                return functionOwner == object;
            }), m_Functions.end());
    }

private:
    std::vector<MiniginDelegate> m_Functions;

    template<typename Func>
    std::shared_ptr<void> GetFunctionOwner(const Func& function) const
    {
        if constexpr (std::is_member_function_pointer_v<Func>)
        {
            auto memberFuncPtr = static_cast<void(Func::*)() const>(&Func::operator());
            return std::any_cast<std::shared_ptr<void>>(*reinterpret_cast<std::shared_ptr<void>*>(memberFuncPtr));
        }
        else
        {
            return nullptr;
        }
    }
};

template<typename ...Args>
class Delegate
{
public:
    using MiniginDelegate = std::function<void(Args...)>;

    Delegate() = default;
    ~Delegate() = default;
    Delegate(const Delegate& other) = delete;
    Delegate(Delegate&& other) noexcept = delete;
    Delegate& operator=(const Delegate& other) = delete;
    Delegate& operator=(Delegate&& other) noexcept = delete;

    void AddFunction(std::shared_ptr<MiniginDelegate> function, const std::vector<std::weak_ptr<void>>& referencedObjects)
    {
        m_Functions.push_back(std::make_pair(std::move(function), referencedObjects));
    }

    void Invoke(Args... args)
    {
        for (const auto& pair : m_Functions)
        {
            const auto& function = pair.first;
            const auto& referencedObjects = pair.second;

            bool allObjectsExist = std::all_of(referencedObjects.begin(), referencedObjects.end(),
                [](const std::weak_ptr<void>& wp) { return !wp.expired(); });

            if (function && allObjectsExist)
            {
                (*function)(args...);
            }
        }
    }

    void Clear()
    {
        m_Functions.clear();
    }

private:
    std::vector<std::pair<std::shared_ptr<MiniginDelegate>, std::vector<std::weak_ptr<void>>>> m_Functions;
};

