import java.util.ArrayList;
import java.util.List;

public class LeadersInArray {
    public static List<Integer> findLeaders(int[] nums) {
        List<Integer> leaders = new ArrayList<>();
        int maxRight = Integer.MIN_VALUE;

        // Traverse the array from right to left
        for (int i = nums.length - 1; i >= 0; i--) {
            if (nums[i] > maxRight) {
                // Current element is greater than all elements to its right
                leaders.add(nums[i]);
                maxRight = nums[i];
            }
        }

        // Reverse the list to get the leaders in the original order
        List<Integer> reversedLeaders = new ArrayList<>();
        for (int i = leaders.size() - 1; i >= 0; i--) {
            reversedLeaders.add(leaders.get(i));
        }

        return reversedLeaders;
    }

    public static void main(String[] args) {
        int[] nums = {16, 17, 4, 3, 5, 2};

        List<Integer> leaders = findLeaders(nums);
        System.out.println("Leaders in the array: " + leaders);
    }
}

public class LexicographicallyFirstPalindromicString {
    public static String findFirstPalindromicString(String str) {
        char[] chars = str.toCharArray();

        // Make the string a palindrome
        for (int i = 0; i < chars.length / 2; i++) {
            if (chars[i] != 'a') {
                chars[i] = 'a';
                return String.valueOf(chars);
            }
        }

        // If the string consists of all 'a', change the last character to 'b'
        if (chars.length > 1) {
            chars[chars.length - 1] = 'b';
            return String.valueOf(chars);
        }

        // If the string has only one character, return an empty string
        return "";
    }

    public static void main(String[] args) {
        String str = "race";

        String firstPalindromicString = findFirstPalindromicString(str);
        if (!firstPalindromicString.isEmpty()) {
            System.out.println("Lexicographically first palindromic string: " + firstPalindromicString);
        } else {
            System.out.println("No palindromic string found.");
        }
    }
}

#!/usr/bin/env zx
// Copyright   : (c) Miao ZhiCheng, 2023
// License     : LGPL-3
// Maintainer  : zhicheng.miao@gmail.com
// Synopsis    : yolc, the LoliYul commandline compiler

import { mkdir, readlink, exec, $ } from 'zx';

let opt_verbose;
function when_verbose() {
  return opt_verbose !== undefined;
}

let is_nix_dist;
let dist_path;
let out_mode = 0;
const out_dir = `${$`pwd`}/build`;
const yol_modules = [];

function help() {
  console.log(`yolc, the LoliYul commandline transpiler.

Usage: yolc [options] yol_module_spec...

-m [output_mode] Valid output modes: show (default), plantuml
-h               Display this help and exit
-v               Output more information about what is going on

yol_module_spec: {package_path:}module_name{[symbol...,]}
  where 1) both package_path and symbol list is optional,
        2) default package_path is current working directory ($PWD),
        3) and default symbol is 'default'.
`);
}

function die(...args) {
  console.error(...args);
  process.exit(1);
}

function trace_run(...args) {
  if (when_verbose()) {
    console.log('+', ...args);
  }
  return $`"${args.join(' ')}"`;
}

async function main() {
  const PROGRAM_PATH = process.argv[1];

  // parse options
  const options = {
    m: null,
    h: false,
    v: false,
  };
  const args = process.argv.slice(2);
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg.startsWith('-')) {
      const option = arg.substring(1);
      if (!(option in options)) {
        help();
        process.exit(1);
      }
      if (option === 'm') {
        options[option] = args[i + 1];
        i++;
      } else {
        options[option] = true;
      }
    } else {
      yol_modules.push(arg);
    }
  }

  const { m: outputMode, h: helpOption, v: verboseOption } = options;

  if (helpOption) {
    help();
    process.exit(0);
  }

  opt_verbose = verboseOption;

  // detect distribution mode
  const programPath = await readlink(PROGRAM_PATH);
  is_nix_dist = programPath.startsWith('/nix/store');
  if (is_nix_dist) {
    const { path: nixDistPath } = await exec('nix metadata --json');
    dist_path = JSON.parse(nixDistPath);
  } else {
    dist_path = await readlink(`${programPath}/..`);
  }
  // TODO: support nix-distribution mode
  if (is_nix_dist) {
    die('Nix-distribution mode not supported');
  }

  if (when_verbose()) {
    console.log('Distribution path:', dist_path);
    console.log('Output mode:', outputMode);
    console.log('Output directory:', out_dir);
    console.log();
  }

  await mkdir('-p', out_dir);

  for (const moduleSpec of yol_modules) {
    await build_yol_module(moduleSpec);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

async function build_yol_module(moduleSpec) {
  if (when_verbose()) {
    console.log('=== Building yol module:', moduleSpec);
  }

  // parse `pkg_path` (default: current folder)
  let pkg_path, rest;
  [pkg_path, rest] = moduleSpec.split(':', 2);
  if (!rest) {
    rest = pkg_path;
    pkg_path = await $`pwd`;
  }
  pkg_path = await readlink(pkg_path);
  if (!(await $.test('-d', pkg_path))) {
    die('Package path not a directory:', pkg_path);
  }
  const cabal_path = (await $`ls ${pkg_path}/*.cabal`)[0];
  if (!cabal_path) {
    die('Does not look like a cabal package:', pkg_path);
  }
  const pkg_name = (await $`sed -nE -e 's|^name:\\s*(.+)\\s*$|\\1|p' < ${cabal_path}`)[0];
  if (!pkg_name) {
    die('Package name cannot be detected, is it a valid cabal file?');
  }

  // parse `mod_name`
  let mod_name, syms;
  [mod_name, syms] = (rest.match(/^([.a-zA-Z]+)(\[(.*)\])?$/) || []).slice(1);
  if (!mod_name) {
    die('Module name cannot be empty');
  }

  // parse `syms`
  syms = syms.replace(/\s*,\s*/g, ' ');
  if (!syms) {
    syms = 'default';
  }

  // prepare the build directory
  const yol_dir = `${out_dir}/${pkg_name}-${mod_name}.yol`;
  await mkdir('-p', yol_dir);

  if (when_verbose()) {
    console.log('Package path:', pkg_path);
    console.log('Cabal file:', cabal_path);
    console.log('Package name:', pkg_name);
    console.log('Module name:', mod_name);
    console.log('Symbols to be built:', syms);
    console.log('Yol module building directory:', yol_dir);
  }

  // prepare cabal build files and build
  await $`cat > ${yol_dir}/cabal.project <<EOF
packages:
  ${dist_path}/3rd-parties/linear-smc
  ${dist_path}/pkgs/loliyul
  ${cabal_path}
  ${yol_dir}/runyol.cabal
EOF`;

  await $`sed -e "s|__YOL_PKG_NAME__|${pkg_name}|g" < ${dist_path}/templates/runyol.cabal > ${yol_dir}/runyol.cabal`;

  const csyms = syms
    .split(' ')
    .map((sym) => `putStrLn((compilers !! ${out_mode}) "${sym}" ${sym});`)
    .join('');
  await $`sed -e "s|__YOL_MOD_NAME__|${mod_name}|g" -e "s|__COMPILE_SYMBOLS__|${csyms}|g" < ${dist_path}/templates/RunYol.hs > ${yol_dir}/RunYol.hs`;

  if (when_verbose()) {
    console.log();
    console.log('=== BEGIN cabal.project');
    await $`cat ${yol_dir}/cabal.project`;
    console.log('=== END cabal.project');
    console.log();
    console.log('=== BEGIN runyol.cabal');
    await $`cat ${yol_dir}/runyol.cabal`;
    console.log('=== END runyol.cabal');
    console.log();
    console.log('=== BEGIN RunYol.hs');
    await $`cat ${yol_dir}/RunYol.hs`;
    console.log('=== END RunYol.hs');
  }

  try {
    await exec(
      `cabal run runyol --project-file=${yol_dir}/cabal.project --builddir=${out_dir}/cabal`
    );
  } catch (err) {
    die('Failed to build yol module:', moduleSpec);
  }

  if (when_verbose()) {
    console.log('=== Done with yol module:', moduleSpec);
    console.log();
  }
}

#!/usr/bin/env raku
# Copyright   : (c) Miao ZhiCheng, 2023
# License     : LGPL-3
# Maintainer  : zhicheng.miao@gmail.com
# Synopsis    : yolc, the LoliYul commandline compiler

sub MAIN(*@args) {
    # Main Program, Utilities & Global Variables

    my $opt_verbose;
    sub when_verbose() { $opt_verbose.defined }

    my $is_nix_dist;
    my $dist_path;
    my $out_mode = 0;
    my $out_dir = "$*CWD/build";
    my @yol_modules;

    sub help() {
        say "yolc, the LoliYul commandline transpiler.";
        say "\nUsage: yolc [options] yol_module_spec...";
        say "\n-m [output_mode] Valid output modes: show (default), plantuml";
        say "-h               Display this help and exit";
        say "-v               Output more information about what is going on";
        say "\nyol_module_spec: {package_path:}module_name{[symbol...,]}";
        say "  where 1) both package_path and symbol list is optional,";
        say "        2) default package_path is current working directory ($*CWD),";
        say "        3) and default symbol is 'default'.";
    }

    sub die(*@msg) {
        put @msg;
        exit 1;
    }

    sub trace_run(*@args) {
        # not using 'shell' on purpose
        when_verbose && say "+ @args";
        run @args;
    }

    sub build_yol_module($module) {
        when_verbose && say "=== Building yol module: $module";

        # parse `pkg_path` (default: current folder)
        my ($pkg_path, $rest) = $module.split(':', 2);
        if !$rest {
            $rest = $pkg_path;
            $pkg_path = $*CWD;
        }
        $pkg_path = $pkg_path.IO.resolve;
        unless $pkg_path.d {
            die "Package path not a directory: $pkg_path";
        }

        my $cabal_path = $pkg_path.IO ~~ dir.child("*.cabal");
        unless $cabal_path {
            die "Does not look like a cabal package: $pkg_path";
        }
        my $pkg_name = $cabal_path.slurp.match(/^name:\s*(.+)\s*$/m)[0];
        unless $pkg_name {
            die "Package name cannot be detected, is it a valid cabal file?";
        }

        # parse `mod_name`
        my ($mod_name, $syms) = $rest.match(/^([.a-zA-Z]+)(?:\[(.*)\])?$/).List[0, 2];
        unless $mod_name {
            die "Module name cannot be empty";
        }

        # parse `syms`
        $syms //= "default";
        $syms .= subst(/\s*,\s*/, " ", :g);

        # prepare the build directory
        my $yol_dir = "{$out_dir}/$pkg_name-$mod_name.yol";
        $yol_dir.IO.mkdir;

        when_verbose && do {
            say "Package path: $pkg_path";
            say "Cabal file: $cabal_path";
            say "Package name: $pkg_name";
            say "Module name: $mod_name";
            say "Symbols to be built: $syms";
            say "Yol module building directory: $yol_dir";
        }

        # prepare cabal build files and build
        my $cabal_project = "{$yol_dir}/cabal.project";
        my $runyol_cabal = "{$yol_dir}/runyol.cabal";
        my $runyol_hs = "{$yol_dir}/RunYol.hs";

        $cabal_project.IO.spurt("packages:
  $dist_path/3rd-parties/linear-smc
  $dist_path/pkgs/loliyul
  $cabal_path
  $runyol_cabal");

        my $runyol_cabal_template = $dist_path.IO.child("templates/runyol.cabal");
        $runyol_cabal.IO.spurt($runyol_cabal_template.slurp.subst("__YOL_PKG_NAME__", $pkg_name));

        my $compilers = (0, 1);
        my $csyms = $syms.split(" ").map: {
            "putStrLn((compilers !! $out_mode) \"$_\" $_);"
        }.join(" ");

        my $runyol_hs_template = $dist_path.IO.child("templates/RunYol.hs");
        $runyol_hs.IO.spurt($runyol_hs_template.slurp
            .subst("__YOL_MOD_NAME__", $mod_name)
            .subst("__COMPILE_SYMBOLS__", $csyms));

        when_verbose && do {
            say "";
            say "=== BEGIN cabal.project";
            say $cabal_project.IO.slurp;
            say "=== END cabal.project";
            say "";
            say "=== BEGIN runyol.cabal";
            say $runyol_cabal.IO.slurp;
            say "=== END runyol.cabal";
            say "";
            say "=== BEGIN RunYol.hs";
            say $runyol_hs.IO.slurp;
            say "=== END RunYol.hs";
        }

        trace_run("cabal", "run", "runyol",
            "--project-file={$yol_dir}/cabal.project",
            "--builddir={$out_dir}/cabal")
            or die "Failed to build yol module: $module";

        when_verbose && do {
            say "=== Done with yol module: $module";
            say "";
        }
    }

    # parse options
    my $PROGRAM_PATH = $*PROGRAM-NAME.IO.path;
    my $args = @args;
    my $pos = 0;
    while $pos < $args.elems {
        given $args[$pos] {
            when "-m" {
                my $mode = $args[++$pos];
                given $mode {
                    when "plantuml" { $out_mode = 1; }
                    when "show"     { $out_mode = 0; }
                    default         { die "Unknown output mode"; }
                }
            }
            when "-v" { $opt_verbose = 1; }
            when "-h" { help(); exit 0; }
            default  { help(); exit 1; }
        }
        $pos++;
    }

    # detect distribution mode
    $is_nix_dist = $PROGRAM_PATH.IO ~~ /^\/nix\/store/;
    if $is_nix_dist {
        $dist_path = run("nix metadata --json").out.decode-json<.path>;
    }
    else {
        $dist_path = $PROGRAM_PATH.IO.parent.parent.resolve;
    }

    # TODO support nix-distribution mode
    $is_nix_dist && die "Nix-distribution mode not supported";

    when_verbose && do {
        say "Distribution path: $dist_path";
        say "Output mode: $out_mode";
        say "Output directory: $out_dir";
        say "";
    }

    $out_dir.IO.mkdir;

    for @args {
        build_yol_module($_);
    }
}

class TwentyNewsgroupsDataset(Dataset):
    def __init__(self,texts,targets, vectorizer):
        self.targets = targets
        self.data = texts # converts the sparse matrix to a dense one... I think.
        self.vectorizer = vectorizer

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        vector = torch.tensor(self.vectorizer.transform([self.data[idx]]).todense()) # torch.tensor() to convert the matrix into a torch tensor for training
        label = self.targets[idx]
        return vector, label

class TwentyNewsgroupsDataset(Dataset):
    def __init__(self, texts, targets, vectorizer):
        self.texts = texts
        self.targets = targets
        self.vectorizer = vectorizer

    def __len__(self):
        return len(self.texts)

    def __getitem__(self, idx):
        text = self.texts[idx]
        label = self.targets[idx]
        bow_vector = torch.tensor(self.vectorizer.transform([text]).toarray())
        return bow_vector, label

