test_dataset = TwentyNewsgroupsDataset(test_texts, test_labels, vectorizer)

struct ColliderPairHash
{
    std::size_t operator()(const std::pair<CollisionObject*, CollisionObject*>& pair) const
    {
        // Combine the hashes of the two colliders using a bitwise XOR
        std::size_t hash1 = std::hash<CollisionObject*>{}(pair.first);
        std::size_t hash2 = std::hash<CollisionObject*>{}(pair.second);
        return hash1 ^ hash2;
    }
};

