const getNewQuestion = () => {
  if (questions.length === 0) return null;

  // Only choose from unanswered or incorrectly answered questions
  const correct = new Set(JSON.parse(localStorage.getItem("correct") || "[]"));
  const options = questions.filter(q => !correct.has(q.question.split(".")[0]));

  return options[Math.floor(Math.random() * options.length)];
};

$("#wrong").click(function() {
  let incorrect = new Set(JSON.parse(localStorage.getItem("incorrect") || "[]"));
  incorrect.add(currentQuestion.question.split(".")[0]);
  localStorage.setItem("incorrect", JSON.stringify(Array.from(incorrect)));
  loadQuestion();
