});

$("#correct").click(function() {
  let correct = new Set(JSON.parse(localStorage.getItem("correct") || "[]"));
  let incorrect = new Set(JSON.parse(localStorage.getItem("incorrect") || "[]"));

  const questionNumber = currentQuestion.question.split(".")[0];

  correct.add(questionNumber);
  incorrect.delete(questionNumber);

