  localStorage.setItem("incorrect", JSON.stringify(Array.from(incorrect)));

  loadQuestion();
  updateScoreboard();
});

use std::fs;
use std::io::prelude::*;
use std::path::PathBuf;
use syn::{visit::Visit, Item};

struct Collector(Vec<String>);

impl<'ast> Visit<'ast> for Collector {
    fn visit_item(&mut self, item: &'ast Item) {
        self.0.push(format!("{}", item));
        syn::visit::visit_item(self, item);
    }
}

fn main() {
    let mut collector = Collector(Vec::new());

    let entries = fs::read_dir("./src").unwrap();

    for entry in entries {
        let entry = entry.unwrap();
        if entry.path().extension().unwrap() == "rs" {
            let content = fs::read_to_string(&entry.path()).unwrap();
            let ast = syn::parse_file(&content).unwrap();
            collector.visit_file(&ast);
        }
    }

    let output_file = PathBuf::from("output.rs");
    let mut file = fs::File::create(&output_file).unwrap();
    file.write_all(collector.0.join("\n").as_bytes()).unwrap();
}

function dump() external view returns (uint256[] memory) {
    uint256[] memory result = new uint256[](COUNT);
    uint256 index = 0;
    for (uint256 i = next[COUNT]; i != COUNT; i = next[COUNT]) {
        result[index] = i;
        index++;
    }
    return result;
}

function dump() external view returns (uint256[] memory) {
    // generated with ChatGPT, don't use...
    uint256[] memory result = new uint256[](index);  // Use `index` as the length of the result array
    uint256 currentIndex = 0;
    for (uint256 i = next[COUNT]; i != COUNT; i = next[COUNT]) {
        result[currentIndex++] = i;
    }
    return result;
}

import 'dart:typed_data';

class TiffImage {
  late ByteData _byteData;
  late int _width;
  late int _height;
  late int _bitsPerSample;
  late List<int> _data;

  void open(Uint8List fileData) {
    _byteData = ByteData.view(fileData.buffer);
    _readHeader();
    _readImageData();
  }

  void _readHeader() {
    final isLittleEndian = _byteData.getUint16(0, Endian.little) == 0x4949;

    final offset = _byteData.getUint32(4, isLittleEndian);

    final byteOrderBytes = _byteData.getUint16(offset, isLittleEndian);
    final isByteOrderValid =
        (isLittleEndian && byteOrderBytes == 0x4949) || (!isLittleEndian && byteOrderBytes == 0x4D4D);
    if (!isByteOrderValid) {
      throw Exception('Invalid byte order.');
    }

    final tagCount = _byteData.getUint16(offset + 2, isLittleEndian);

    for (var i = 0; i < tagCount; i++) {
      final tagOffset = offset + 8 + i * 12;
      final tag = _byteData.getUint16(tagOffset, isLittleEndian);

      if (tag == 0x0100) {
        _width = _readTagValue(tagOffset, isLittleEndian);
      } else if (tag == 0x0101) {
        _height = _readTagValue(tagOffset, isLittleEndian);
      } else if (tag == 0x0102) {
        _bitsPerSample = _readTagValue(tagOffset, isLittleEndian);
      } else if (tag == 0x0117) {
        final stripOffset = _readTagValue(tagOffset, isLittleEndian);
        _readImageData(stripOffset, isLittleEndian);
      }
    }
  }

  int _readTagValue(int tagOffset, bool isLittleEndian) {
    final tagType = _byteData.getUint16(tagOffset + 2, isLittleEndian);
    final tagCount = _byteData.getUint32(tagOffset + 4, isLittleEndian);
    final tagValueOffset = _byteData.getUint32(tagOffset + 8, isLittleEndian);

    if (tagType == 3 && tagCount == 1) {
      return _byteData.getUint16(tagValueOffset, isLittleEndian);
    } else if (tagType == 4 && tagCount == 1) {
      return _byteData.getUint32(tagValueOffset, isLittleEndian);
    } else {
      throw Exception('Unsupported tag value type.');
    }
  }

  void _readImageData(int stripOffset, bool isLittleEndian) {
    final bytesPerRow = (_width * _bitsPerSample) ~/ 8;
    final bytesPerPixel = _bitsPerSample ~/ 8;
    final imageSize = bytesPerRow * _height;
    _data = List<int>(imageSize);

    for (var i = 0; i < imageSize; i += bytesPerPixel) {
      final pixelOffset = stripOffset + i * bytesPerPixel;
      final pixelValue = _readPixelValue(pixelOffset, bytesPerPixel, isLittleEndian);
      _data[i] = pixelValue;
    }
  }

  int _readPixelValue(int pixelOffset, int bytesPerPixel, bool isLittleEndian) {
    if (bytesPerPixel == 1) {
      return _byteData.getUint8(pixelOffset);
    } else if (bytesPerPixel == 2) {
      return _byteData.getUint16(pixelOffset, isLittleEndian);
    } else {
      throw Exception('Unsupported bit depth.');
    }
  }

  int readPixel(int x, int y) {
    final bytesPerRow = (_width * _bitsPerSample) ~/ 8;
    final bytesPerPixel = _bitsPerSample ~/ 8;
    final pixelIndex = y * bytesPerRow + x * bytesPerPixel;

    if (pixelIndex >= 0 && pixelIndex < _data.length) {
      return _data[pixelIndex];
    } else {
      throw Exception('Invalid pixel coordinates.');
    }
  }
}

void main() {
  final fileData = Uint8List.fromList([
    // TIFF file data goes here
  ]);

  final image = TiffImage();
  image.open(fileData);

  final red = image.readPixel(0, 0);
  final green = image.readPixel(0, 1);
  final blue = image.readPixel(0, 2);

  print('Red: $red, Green: $green, Blue: $blue');
}

