import asyncio
import websockets
from threading import Thread

class Server:
    def __init__(self, on_message=None):
        self.server = None
        self.thread = None
        self.websocket = None
        self.on_message = on_message

    async def handler(self, websocket, path):
        self.websocket = websocket
        while True:
            try:
                message = await websocket.recv()
                if self.on_message:
                    self.on_message(message)
            except websockets.exceptions.ConnectionClosedOK:
                print("Connection closed normally.")
                break
            except websockets.exceptions.ConnectionClosedError:
                print("Connection closed with error.")
                break

    def start(self):
        self.thread = Thread(target=self.run)
        self.thread.start()

    def run(self):
        asyncio.run(self.start_server())

    async def start_server(self):
        async with websockets.serve(self.handler, 'localhost', 8765):
            await asyncio.Future()  # runs forever

    def send_message(self, message):
        if self.websocket:
            asyncio.run(self.websocket.send(message))

    def stop(self):
        if self.server:
            self.server.close()
            asyncio.run(self.server.wait_closed())

if __name__ == "__main__":
    def on_message(message):
        print(f"Server received: {message}")

    server = Server(on_message)
    server.start()

    try:
        while True:
            pass
    except KeyboardInterrupt:
        server.stop()

import asyncio
import websockets
from threading import Thread
import time

class Client:
    def __init__(self, on_message=None, max_retries=3, retry_interval=5):
        self.client = None
        self.thread = None
        self.websocket = None
        self.on_message = on_message
        self.max_retries = max_retries
        self.retry_interval = retry_interval

    async def handler(self):
        retry_count = 0
        while retry_count < self.max_retries:
            try:
                self.websocket = await websockets.connect('ws://localhost:8765')
                while True:
                    response = await self.websocket.recv()
                    if self.on_message:
                        self.on_message(response)
            except websockets.exceptions.ConnectionClosedOK:
                print("Connection closed normally.")
                self.websocket = None
            except websockets.exceptions.ConnectionClosedError:
                print("Connection closed with error.")
                self.websocket = None
            except OSError:
                print("Failed to connect. Retrying...")
                retry_count += 1
                time.sleep(self.retry_interval)

    def start(self):
        self.thread = Thread(target=self.run)
        self.thread.start()

    def run(self):
        asyncio.run(self.handler())

    def send_message(self, message):
        if self.websocket:
            asyncio.run(self.websocket.send(message))

    def stop(self):
        if self.client:
            self.client.close()
            asyncio.run(self.client.wait_closed())

if __name__ == "__main__":
    def on_message(message):
        print(f"Client received: {message}")

    client = Client(on_message)
    client.start()

    try:
        while True:
            message = input("Enter message to send: ")
            client.send_message(message)
    except KeyboardInterrupt:
        client.stop()

function example() {
  let x = 10; // Declare variable x with let inside the function

  if (true) {
    let y = 20; // Declare variable y with let inside the if block
    console.log(x); // Output: 10
    console.log(y); // Output: 20
  }

  console.log(x); // Output: 10
  console.log(y); // Error: y is not defined (not accessible outside the if block)
}

example();

function example() {
  let x = 10; // Declare variable x with let inside the function
  let y; // Declare variable y with let outside the if statement

  if (true) {
    y = 20; // Assign a value to y inside the if block
    console.log(x); // Output: 10
    console.log(y); // Output: 20
  }

  y = 30; // Assign a different value to y outside the if block

  console.log(x); // Output: 10
  console.log(y); // Output: 30 (new value assigned outside the if block)
}

example();

// Base contract
contract Base {
