        return "Base";
    }
}

// Derived contract
contract Derived is Base {
    function foo() public virtual override returns (string memory) {
        return "Derived";
    }
}

// Another derived contract
contract AnotherDerived is Base {
    function foo() public virtual override returns (string memory) {
        return "AnotherDerived";
    }
}

use std::ops::Deref;

struct Matrix {
    data: Vec<Vec<i32>>,
}

impl Deref for Matrix {
    type Target = Vec<Vec<i32>>;

    fn deref(&self) -> &Self::Target {
        &self.data
    }
}

fn main() {
    let matrix = Matrix {
        data: vec![
            vec![1, 2, 3],
            vec![4, 5, 6],
            vec![7, 8, 9],
        ],
    };

    print_matrix(&matrix);
    print_matrix(matrix.deref()); // Using deref explicitly

    let row_sum = matrix.iter().map(|row| row.iter().sum::<i32>()).collect::<Vec<i32>>();
    println!("Row sums: {:?}", row_sum);

    let flattened: Vec<i32> = matrix.into_iter().flatten().collect();
    println!("Flattened matrix: {:?}", flattened);
}

fn print_matrix(matrix: &Vec<Vec<i32>>) {
    for row in matrix {
        for val in row {
            print!("{} ", val);
        }
        println!();
    }
}

use std::ops::Deref;

struct Matrix {
    data: Vec<Vec<i32>>,
}

impl Deref for Matrix {
    type Target = Vec<Vec<i32>>;

    fn deref(&self) -> &Self::Target {
        &self.data
    }
}

impl IntoIterator for Matrix {
    type Item = i32;
    type IntoIter = MatrixIntoIterator;

    fn into_iter(self) -> Self::IntoIter {
        MatrixIntoIterator {
            matrix: self,
            row: 0,
            col: 0,
        }
    }
}

struct MatrixIntoIterator {
    matrix: Matrix,
    row: usize,
    col: usize,
}

impl Iterator for MatrixIntoIterator {
    type Item = i32;

    fn next(&mut self) -> Option<Self::Item> {
        if self.row < self.matrix.data.len() {
            let val = self.matrix.data[self.row][self.col];
            self.col += 1;
            if self.col >= self.matrix.data[self.row].len() {
                self.row += 1;
                self.col = 0;
            }
            Some(val)
        } else {
            None
        }
    }
}

fn main() {
    let matrix = Matrix {
        data: vec![
            vec![1, 2, 3],
            vec![4, 5, 6],
            vec![7, 8, 9],
        ],
    };

    print_matrix(&matrix);
    print_matrix(&*matrix); // Using deref explicitly

    let flattened: Vec<i32> = matrix.into_iter().collect();
    println!("Flattened matrix: {:?}", flattened);
}

fn print_matrix(matrix: &Vec<Vec<i32>>) {
    for row in matrix {
        for val in row {
            print!("{} ", val);
        }
        println!();
    }
}

