class MoviesPage extends StatelessWidget {
  const MoviesPage({Key? key});

  @override
  Widget build(BuildContext context) {
    final moviesProvider = context.watch<MoviesProvider>();
    final PriceFilterOption selectedFilterOption = moviesProvider.selectedPriceFilterOption;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Movies'),
        actions: [
          PopupMenuButton<SortOption>(
            onSelected: (SortOption selectedOption) {
              moviesProvider.sortMovies(selectedOption);
            },
            itemBuilder: (BuildContext context) => [
              const PopupMenuItem<SortOption>(
                value: SortOption.price,
                child: Text('Sort by Price'),
              ),
              const PopupMenuItem<SortOption>(
                value: SortOption.name,
                child: Text('Sort by Name'),
              ),
            ],
          ),
          PopupMenuButton<PriceFilterOption>(
            onSelected: (PriceFilterOption selectedOption) {
              moviesProvider.selectPriceFilterOption(selectedOption);
              if (selectedOption == PriceFilterOption.custom) {
                showDialog(
                  context: context,
                  builder: (BuildContext context) {
                    return PriceFilterDialog(
                      onFilterApplied: (double minPrice, double maxPrice) {
                        moviesProvider.filterByPrice(minPrice, maxPrice);
                      },
                    );
                  },
                );
              } else {
                moviesProvider.filterByPrice(null, null);
              }
            },
            itemBuilder: (BuildContext context) => [
              const PopupMenuItem<PriceFilterOption>(
                value: PriceFilterOption.all,
                child: Text('Show All Prices'),
              ),
              const PopupMenuItem<PriceFilterOption>(
                value: PriceFilterOption.custom,
                child: Text('Filter by Price'),
              ),
            ],
          ),
        ],
      ),
      body: Consumer<MoviesProvider>(
        builder: (context, provider, __) {
          if (provider.isLoading) {
            return const Center(
              child: CircularProgressIndicator(),
            );
          }

          if (provider.error.isNotEmpty) {
            return Center(
              child: Text(provider.error),
            );
          }

          final List<Movie> filteredMovies = provider.filterMoviesByPrice();

          return ListView.builder(
            itemCount: filteredMovies.length,
            itemBuilder: (_, index) => MovieListTile(
              movie: filteredMovies[index],
              onTap: () => context.go('/movies/${filteredMovies[index].id}'),
            ),
          );
        },
      ),
    );
  }
}

Movie findMovieByPrice(List<Movie> movies, bool findMinimum) {
  Movie initialMovie = movies.first;
  return movies.reduce((currentMovie, movie) {
    final shouldUpdate =
        findMinimum ? (movie.price < currentMovie.price) : (movie.price > currentMovie.price);
    return shouldUpdate ? movie : currentMovie;
  });
}

final minAvailable = findMovieByPrice(allMovies, true);
final maxAvailable = findMovieByPrice(allMovies, false);

