#pragma kernel BitonicSort

#define THREAD_NUM 512
#define SWAP(x, y) { float3 temp = x; x = y; y = temp; }

struct Data
{
    float3 value;
    float distance;
};

RWStructuredBuffer<Data> Buffer;

[numthreads(THREAD_NUM, 1, 1)]
void BitonicSort(uint3 id : SV_DispatchThreadID)
{
    uint idx = id.x;

    for (uint size = 2; size <= THREAD_NUM; size <<= 1)
    {
        uint dir = (idx & (size << 1)) != 0;
        for (uint stride = size >> 1; stride > 0; stride >>= 1)
        {
            GroupMemoryBarrierWithGroupSync();
            uint swapIdx = idx ^ stride;
            if ((idx & size) == 0 ^ dir)
            {
                if (Buffer[idx].distance < Buffer[swapIdx].distance)
                    SWAP(Buffer[idx], Buffer[swapIdx]);
            }
            else
            {
                if (Buffer[idx].distance > Buffer[swapIdx].distance)
                    SWAP(Buffer[idx], Buffer[swapIdx]);
            }
        }
    }
}

def _my_rule_impl(ctx):
    # The outputs of the dependency rule will be available in the depset 'ctx.files.deps'
    for dep in ctx.files.deps:
        ctx.actions.run(
            outputs = [ctx.outputs.out],
            inputs = depset([dep]),
            executable = ctx.executable._tool,
            arguments = [dep.path],
        )

my_rule = rule(
    implementation = _my_rule_impl,
    attrs = {
        "deps": attr.label_list(allow_files = True),
        "_tool": attr.label(default = "//path/to:tool", cfg = "host", executable = True),
        "out": attr.output(),
    },
)

# Define a common function
def _common_function(ctx, inputs, outputs):
    ctx.actions.run(
        inputs = inputs,
        outputs = outputs,
        executable = ctx.executable._tool,
        arguments = [inp.path for inp in inputs],
    )

# Use the common function in the rule implementation
def _my_rule_impl(ctx):
    _common_function(ctx, ctx.files.srcs, [ctx.outputs.out])

# Define your rule
my_rule = rule(
    implementation = _my_rule_impl,
    attrs = {
        "srcs": attr.label_list(allow_files = True),
        "_tool": attr.label(default = "//path/to:tool", cfg = "host", executable = True),
        "out": attr.output(),
    },
)

c_toolchain = rule(
    implementation = _c_toolchain_impl,
    attrs = {
        "compiler": attr.label(executable = True, cfg = "host"),
        "linker": attr.label(executable = True, cfg = "host"),
        "single_step_build_and_link": attr.bool(),
    },
)

// Adaptee - Incompatible interface
class FahrenheitSensor {
  getTemperature() {
    const temperatureF = Math.random() * 100;
    return temperatureF.toFixed(2);
  }
}

// Adapter - Adapts FahrenheitSensor to CelsiusSensor interface
class TemperatureAdapter {
  constructor(fahrenheitSensor) {
    this.fahrenheitSensor = fahrenheitSensor;
  }

  getTemperature() {
    const temperatureF = this.fahrenheitSensor.getTemperature();
    const temperatureC = (temperatureF - 32) * (5 / 9);
    return temperatureC.toFixed(2);
  }
}

// Usage
const fahrenheitSensor = new FahrenheitSensor();
const temperatureAdapter = new TemperatureAdapter(fahrenheitSensor);

console.log("Temperature in Celsius: " + temperatureAdapter.getTemperature());

// Subject - Maintains a list of observers and notifies them of state changes
class NewsAgency {
  constructor() {
    this.observers = [];
    this.news = null;
  }

  addObserver(observer) {
    this.observers.push(observer);
  }

  removeObserver(observer) {
    this.observers = this.observers.filter((obs) => obs !== observer);
  }

  setNews(news) {
    this.news = news;
    this.notifyObservers();
  }

  notifyObservers() {
    this.observers.forEach((observer) => observer.update(this.news));
  }
}

// Observer - Defines an update method to be called by the subject
class NewsChannel {
  constructor(name) {
    this.name = name;
  }

  update(news) {
    console.log(`${this.name} received news: ${news}`);
  }
}

// Usage
const newsAgency = new NewsAgency();

const channel1 = new NewsChannel("Channel 1");
const channel2 = new NewsChannel("Channel 2");
const channel3 = new NewsChannel("Channel 3");

newsAgency.addObserver(channel1);
newsAgency.addObserver(channel2);
newsAgency.addObserver(channel3);

newsAgency.setNews("Breaking news: Observer pattern example!");

newsAgency.removeObserver(channel2);

newsAgency.setNews("New news: Observer pattern in action!");

// Component - The original object or interface
class Coffee {
  getDescription() {
    return "Coffee";
  }

  getCost() {
    return 2.0;
  }
}

// Decorator - Adds extra behavior to the component
class MilkDecorator {
  constructor(coffee) {
    this.coffee = coffee;
  }

  getDescription() {
    return this.coffee.getDescription() + ", Milk";
  }

  getCost() {
    return this.coffee.getCost() + 0.5;
  }
}

// Decorator - Adds extra behavior to the component
class CaramelDecorator {
  constructor(coffee) {
    this.coffee = coffee;
  }

  getDescription() {
    return this.coffee.getDescription() + ", Caramel";
  }

  getCost() {
    return this.coffee.getCost() + 0.75;
  }
}

// Usage
const coffee = new Coffee();
const coffeeWithMilk = new MilkDecorator(coffee);
const coffeeWithMilkAndCaramel = new CaramelDecorator(coffeeWithMilk);

console.log(coffeeWithMilkAndCaramel.getDescription()); // Output: Coffee, Milk, Caramel
console.log(coffeeWithMilkAndCaramel.getCost()); // Output: 3.25

public class DefaultValueExample {
    static int intValue;
    static float floatValue;
    static double doubleValue;
    static char charValue;
    static boolean boolValue;
    static MyClass myClassValue;

    public static void main(String[] args) {
        System.out.println("int: " + intValue);             // Output: int: 0
        System.out.println("float: " + floatValue);         // Output: float: 0.0
        System.out.println("double: " + doubleValue);       // Output: double: 0.0
        System.out.println("char: " + charValue);           // Output: char:
        System.out.println("boolean: " + boolValue);        // Output: boolean: false
        System.out.println("class: " + myClassValue);       // Output: class: null
    }

    static class MyClass {
        // Class definition, not instantiated in this example
    }
}

public class MathOperations {
    // Method to add two integers
    public int add(int a, int b) {
        return a + b;
    }

    // Method to add three integers
    public int add(int a, int b, int c) {
        return a + b + c;
    }

    // Method to add two doubles
    public double add(double a, double b) {
        return a + b;
    }

    public static void main(String[] args) {
        MathOperations math = new MathOperations();

        int result1 = math.add(5, 10); // Calls the int add(int a, int b) method
        int result2 = math.add(5, 10, 15); // Calls the int add(int a, int b, int c) method
        double result3 = math.add(2.5, 3.7); // Calls the double add(double a, double b) method

        System.out.println("Result1: " + result1);
        System.out.println("Result2: " + result2);
        System.out.println("Result3: " + result3);
    }
}

