companion object {
    private const val ARG_TASK = "task"
    private const val ARG_COLOR = "color"

    fun newInstance(task: Task, color: Int): AddUpdateTaskFragment {
        val fragment = AddUpdateTaskFragment()
        val args = Bundle().apply {
            putParcelable(ARG_TASK, task)
            putInt(ARG_COLOR, color)
        }
        fragment.arguments = args
        return fragment
    }
}

override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View? {
    // Inflate the layout for this fragment
    val view = inflater.inflate(R.layout.fragment_add_update_task, container, false)

    // Retrieve the task and color arguments
    val task = arguments?.getParcelable<Task>(ARG_TASK)
    val color = arguments?.getInt(ARG_COLOR)

    // Apply the color to the desired view
    view.setBackgroundColor(color ?: Color.TRANSPARENT)

    // Set up the RecyclerView
    val recyclerView = view.findViewById<RecyclerView>(R.id.recyclerview)
    val adapter = TaskAdapter()
    recyclerView.adapter = adapter
    recyclerView.layoutManager = LinearLayoutManager(requireContext())

    // Set up swipe-to-delete functionality
    val itemTouchHelper = ItemTouchHelper(setupSwipeToDeleteCallback(adapter))
    itemTouchHelper.attachToRecyclerView(recyclerView)

    // Get the ViewModel and observe the tasks
    val taskViewModel = ViewModelProvider(this).get(TaskViewModel::class.java)
    taskViewModel.allTasks.observe(viewLifecycleOwner, { tasks ->
        tasks?.let { adapter.setTasks(it) }
    })

    return view
}

class AddUpdateTaskFragment : Fragment() {
    // Declare the taskViewModel as a val
    private val taskViewModel: TaskViewModel by lazy {
        ViewModelProvider(this, factory).get(TaskViewModel::class.java)
    }

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View? {
        // ...

        // Get the ViewModel and observe the tasks
        taskViewModel.allTasks.observe(viewLifecycleOwner, { tasks ->
            tasks?.let { adapter.setTasks(it) }
        })

        return view
    }

    // ...
}

inner class TaskViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView), View.OnClickListener {
    // ...
    init {
        itemView.setOnClickListener(this)
    }

    override fun onClick(view: View) {
        val position = adapterPosition
        if (position != RecyclerView.NO_POSITION) {
            val task = tasks[position]
            val fragment = AddUpdateTaskFragment.newInstance(task)
            val fragmentManager = (itemView.context as AppCompatActivity).supportFragmentManager
            fragmentManager.beginTransaction()
                .replace(R.id.container, fragment)
                .addToBackStack(null)
                .commit()
        }
    }
}

