@Entity(tableName = "tasks")
data class Task(
    @PrimaryKey(autoGenerate = true)
    var id: Int = 0,

    var title: String,

    var description: String,

    var isCompleted: Boolean = false
) : Parcelable {
    constructor(parcel: Parcel) : this(
        parcel.readInt(),
        parcel.readString() ?: "",
        parcel.readString() ?: "",
        parcel.readByte() != 0.toByte()
    )

    override fun writeToParcel(parcel: Parcel, flags: Int) {
        parcel.writeInt(id)
        parcel.writeString(title)
        parcel.writeString(description)
        parcel.writeByte(if (isCompleted) 1 else 0)
    }

    override fun describeContents(): Int {
        return 0
    }

    companion object CREATOR : Parcelable.Creator<Task> {
        override fun createFromParcel(parcel: Parcel): Task {
            return Task(parcel)
        }

        override fun newArray(size: Int): Array<Task?> {
            return arrayOfNulls(size)
        }
    }
}

override fun onCreateView(
    inflater: LayoutInflater, container: ViewGroup?,
    savedInstanceState: Bundle?
): View? {
    val view = inflater.inflate(R.layout.fragment_add_update_task, container, false)

    editTaskTitle = view.findViewById(R.id.edit_task_title)
    editTaskDescription = view.findViewById(R.id.edit_task_description)
    checkTaskCompletion = view.findViewById(R.id.check_task_completion)
    val button = view.findViewById<Button>(R.id.button_save)

    val task = arguments?.getParcelable<Task>(ARG_TASK)
    if (task != null) {
        editTaskTitle.setText(task.title)
        editTaskDescription.setText(task.description)
        checkTaskCompletion.isChecked = task.isCompleted
    }

    val taskDao = AppDatabase.getDatabase(requireContext()).taskDao()
    val taskRepository = TaskRepository(taskDao)
    val factory = TaskViewModelFactory(taskRepository)
    val taskViewModel = ViewModelProvider(this, factory).get(TaskViewModel::class.java)

    button.setOnClickListener {
        val title = editTaskTitle.text.toString()
        val description = editTaskDescription.text.toString()
        val isCompleted = checkTaskCompletion.isChecked
        val updatedTask = Task(title = title, description = description, isCompleted = isCompleted)

        val existingTask = arguments?.getParcelable<Task>(ARG_TASK)
        if (existingTask != null) {
            updatedTask.id = existingTask.id // Retain the existing task's ID
            taskViewModel.update(updatedTask) // Update the task
        } else {
            taskViewModel.insert(updatedTask) // Insert a new task
        }

        requireActivity().supportFragmentManager.popBackStack()
    }

    return view
}

