module your_module_tb;

  // Inputs
  reg vg;
  reg [7:0] vc;
  reg [7:0] iL;

  // Instantiate the module under test
  your_module dut (
    .vg(vg),
    .vc(vc),
    .iL(iL)
  );

  // Clock
  reg clk;
  always #5 clk = ~clk;  // Toggle every 5 time units

  // Test stimulus
  initial begin
    clk = 0;  // Initialize clock

    // Apply test vectors
    vg = 12;
    repeat(10) begin
      #10;  // Wait for 10 time units

      // Randomize vc in the range 5-6
      vc = $urandom_range(5, 6);

      // Randomize iL in the range 0.4-0.7
      iL = $urandom_range(40, 70) / 100;
    end

    $finish;  // End the simulation
  end

  // Display output
  always @(posedge clk)
    $display("vg = %0d, vc = %0d, iL = %0.2f", vg, vc, iL);

endmodule

module FCS_MPC (
  input wire [7:0] iL,
  input wire [7:0] vc,
  input wire [7:0] Vg,
  output reg u
);

  reg [63:0] temp;

  function [63:0] abs(input [63:0] x);
    if (x >= 0) begin
      abs = x;
    end else begin
      abs = -x;
    end
  endfunction

  always @(iL or vc or Vg) begin
    temp = (32'b00000111100111010101111010011001 * iL + 32'b00000111100001111010110101111110 * vc - 32'b001010000000000000000000000000000);
    u = (abs(temp + 32'b00000000000000000001110000000111 * Vg) <= abs(temp)) ? 1'b1 : 1'b0;
  end

endmodule

module FCS_MPC_tb;

  // Parameters
  parameter CLK_PERIOD = 10;

  // Inputs
  reg [7:0] iL;
  reg [7:0] vc;
  reg [7:0] vg;

  // Outputs
  wire u;

  // Instantiate the module under test
  FCS_MPC dut (
    .iL(iL),
    .vc(vc),
    .Vg(vg),
    .u(u)
  );

  // Clock
  reg clk;
  always #((CLK_PERIOD / 2)) clk = ~clk;

  // Test stimulus
  initial begin
    $display("vg\tvc\tiL\tu");
    $monitor("%b\t%b\t%b\t%b", vg, vc, iL, u);

    clk = 0;
    iL = 0;
    vc = 0;

    // Apply test vectors
    repeat(10) begin
      #CLK_PERIOD;
      vg = 12;
      vc = $random % 2 + 5;  // Randomize vc in the range 5-6
      iL = ($random % 4 + 4) / 10.0;  // Randomize iL in the range 0.4-0.7
    end

    $finish;
  end

endmodule

module FCS_MPC_tb;

  // Parameters
  parameter CLK_PERIOD = 10;

  // Inputs
  reg [7:0] iL;
  reg [7:0] vc;
  reg [7:0] vg;

  // Outputs
  wire u;

  // Instantiate the module under test
  FCS_MPC dut (
    .iL(iL),
    .vc(vc),
    .Vg(vg),
    .u(u)
  );

  // Clock
  reg clk;
  always #((CLK_PERIOD / 2)) clk = ~clk;

  // Test stimulus
  initial begin
    $display("vg\tvc\tiL\tu");
    $monitor("%b\t%b\t%b\t%b", vg, vc, iL, u);

    clk = 0;
    iL = 1;
    vc = 1;

    // Apply test vectors
    repeat(10) begin
      #CLK_PERIOD;
      vg = 12;
      vc = vc + 1;  // Increment vc
      if (vc > 6) vc = 1;  // Wraparound vc in the range 1-6
      iL = iL + 1;  // Increment iL
      if (iL > 7) iL = 1;  // Wraparound iL in the range 0.1-0.7
    end

    $finish;
  end

endmodule

