query = from u in User,
        select: %{u | builds: fragment("array_agg(?)", u.builds.id)}

user_with_builds = Repo.one(query)

build_ids_subquery =
  from b in Build,
    group_by: b.user_id,
    select: %{user_id: b.user_id, build_ids: fragment("array_agg(?)", b.id)}

query =
  from u in User,
    join: sq in subquery(build_ids_subquery),
    on: u.id == sq.user_id,
    left_join: fb in FeaturedBuild,
    on: fb.user_id == u.id,
    select: %{u | builds: sq.build_ids, featured_build_id: fb.build_id}

user_with_builds = Repo.all(query)

