package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/jinzhu/gorm"
	_ "github.com/jinzhu/gorm/dialects/sqlite"
)

type Todo struct {
	gorm.Model
	Task   string
	Status string
}

var db *gorm.DB
var err error

func main() {
	db, err = gorm.Open("sqlite3", "todos.db")
	if err != nil {
		panic("Failed to connect database")
	}
	defer db.Close()

	db.AutoMigrate(&Todo{})

	displayMenu()
}

func displayMenu() {
	reader := bufio.NewReader(os.Stdin)
	var choice int
	fmt.Println("1. Create Todo")
	fmt.Println("2. Read Todos")
	fmt.Println("3. Update Todo")
	fmt.Println("4. Delete Todo")
	fmt.Println("5. Exit")

	fmt.Print("Enter choice: ")
	input, _ := reader.ReadString('\n')
	choice, err = strconv.Atoi(strings.TrimSpace(input))
	if err != nil {
		fmt.Println("Invalid input. Please enter a number between 1-5.")
		displayMenu()
	}

	switch choice {
	case 1:
		createTodo()
	case 2:
		readTodos()
	case 3:
		updateTodo()
	case 4:
		deleteTodo()
	case 5:
		os.Exit(0)
	default:
		fmt.Println("Invalid choice. Please choose between 1-5.")
		displayMenu()
	}
	displayMenu()
}

func createTodo() {
	reader := bufio.NewReader(os.Stdin)
	var task string
	fmt.Print("Enter task: ")
	task, _ = reader.ReadString('\n')
	task = strings.TrimSpace(task)

	todo := Todo{Task: task, Status: "incomplete"}
	db.Create(&todo)
}

func readTodos() {
	var todos []Todo
	db.Find(&todos)
	for _, todo := range todos {
		fmt.Printf("%d | %s | %s\n", todo.ID, todo.Task, todo.Status)
	}
}

func updateTodo() {
	reader := bufio.NewReader(os.Stdin)
	var id int
	var task, status string

	fmt.Print("Enter todo ID to update: ")
	input, _ := reader.ReadString('\n')
	id, err = strconv.Atoi(strings.TrimSpace(input))
	if err != nil {
		fmt.Println("Invalid input. Please enter a valid ID.")
		displayMenu()
	}

	todo := Todo{}
	db.First(&todo, id)

	fmt.Print("Enter updated task (blank to skip): ")
	task, _ = reader.ReadString('\n')
	task = strings.TrimSpace(task)

	fmt.Print("Enter updated status (blank to skip): ")
	status, _ = reader.ReadString('\n')
	status = strings.TrimSpace(status)

	if task != "" {
		todo.Task = task
	}

	if status != "" {
		todo.Status = status
	}

	db.Save(&todo)
}

func deleteTodo() {
	reader := bufio.NewReader(os.Stdin)
	var id int

	fmt.Print("Enter todo ID to delete: ")
	input, _ := reader.ReadString('\n')
	id, err = strconv.Atoi(strings.TrimSpace(input))
	if err != nil {
		fmt.Println("Invalid input. Please enter a valid ID.")
		displayMenu()
	}

	todo := Todo{}
	db.First(&todo, id)

	db.Delete(&todo)
}

import itertools

def get_closest_point(self, x, y):
    def distance_squared(point):
        px, py = point
        return (px - x) ** 2 + (py - y) ** 2

    if not self.point_positions:
        return None, False

    closest_point = min(self.point_positions, key=distance_squared)
    min_distance = distance_squared(closest_point)

    if min_distance < 25:
        closest_index = self.point_positions.index(closest_point)
        return closest_index, True
    else:
        return None, False

