const express = require('express');
const { createProxyMiddleware } = require('http-proxy-middleware');

const app = express();

// Create a proxy middleware
const proxyMiddleware = createProxyMiddleware({
  target: '', // Leave the target empty for now
  changeOrigin: true,
});

// Apply the proxy middleware to all requests
app.use('/', (req, res, next) => {
  // Extract the target URL from the requested path
  const targetUrl = req.originalUrl.slice(1); // Remove the leading slash

  // Set the target dynamically
  proxyMiddleware.target = `http://${targetUrl}`;

  // Continue to the proxy middleware
  next();
}, proxyMiddleware);

// Start the server
const port = 3000;
app.listen(port, () => {
  console.log(`Reverse proxy server listening on port ${port}`);
});

