// index.js (Version 1.5)
const express = require('express');
const { createProxyMiddleware } = require('http-proxy-middleware');
const url = require('url');

const app = express();

// Custom middleware to handle reverse proxy
app.use((req, res, next) => {
  const targetUrl = req.originalUrl.slice(1); // Remove the leading slash

  // Create a proxy middleware with the dynamically determined target
  const proxyMiddleware = createProxyMiddleware({
    target: `http://${targetUrl}`,
    changeOrigin: true,
    prependPath: false,
    ignorePath: true,
    onProxyRes: (proxyRes, req, res) => {
      if (proxyRes.headers.location) {
        const originalUrl = req.protocol + '://' + req.get('host') + req.originalUrl;
        proxyRes.headers.location = proxyRes.headers.location.replace(targetUrl, originalUrl);
      }
    },
    router: (req) => {
      const parsedUrl = url.parse(req.url);
      return parsedUrl.path;
    },
  });

  // Proxy the request
  proxyMiddleware(req, res, next);
});

// Start the server
const port = 3000;
const codeVersion = '1.5';
app.listen(port, () => {
  console.log(`Reverse proxy server (Version ${codeVersion}) listening on port ${port}`);
});

