const express = require('express');
const http = require('http');
const https = require('https');

const app = express();

// Custom middleware to handle reverse proxy
app.all('/:targetUrl/*', (req, res) => {
  const { targetUrl } = req.params;
  const target = (targetUrl.startsWith('https://') ? https : http);

  const proxyReq = target.request(req.url.replace(`/${targetUrl}`, ''), (proxyRes) => {
    res.writeHead(proxyRes.statusCode, proxyRes.headers);
    proxyRes.pipe(res);
  });

  req.pipe(proxyReq);
});

