const express = require('express');
const app = express();
const axios = require('axios');
const cheerio = require('cheerio');

const codeVersion = '4.7';

app.all('*', async (req, res) => {
  console.log('Code Version:', codeVersion);

  // Proxy logic to fetch and return main body of the article from targetUrl
  const targetUrl = req.url.slice(1); // Remove the leading slash (/) from the URL

  try {
    const response = await axios.get(targetUrl);
    const html = response.data;
    const $ = cheerio.load(html);

    // Extract the main body of the article based on content length and position
    const mainContent = $('body')
      .find('*')
      .filter((index, element) => {
        const $element = $(element);
        const content = $element.text().trim();
        const isExcludedTag = ['script', 'style', 'svg'].includes($element.prop('tagName').toLowerCase());
        const isShortContent = content.length < 20;
        const isNotInMainSection = $element.parents('main').length === 0;
        const isNotInArticleSection = $element.parents('article').length === 0;

        return !isExcludedTag && !isShortContent && (isNotInMainSection || isNotInArticleSection);
      })
      .map((index, element) => $(element).html())
      .get()
      .join('<br><br>');

    res.send(mainContent);
  } catch (error) {
    console.error('Error proxying:', error);
    res.status(500).send('Error proxying request');
  }
});

