        p {
          margin-top: 0;
          margin-bottom: 1em;
        }

        a {
          color: #06c;
          text-decoration: underline;
        }

        .hidden-sentence {
          display: none;
        }

        .pill {
          display: inline-block;
          padding: 0.3em 0.6em;
          background-color: #333;
          color: #fff;
          font-size: 0.8em;
          line-height: 1;
          border-radius: 3px;
          cursor: pointer;
          transition: background-color 0.15s ease-in-out;
        }

        .pill:hover {
          background-color: #06c;
        }

        .toggle-dark-mode {
          position: absolute;
          top: 1em;
          right: 1em;
          background-color: ${req.query.dark ? '#045192' : '#eaeaea'};
          color: ${req.query.dark ? '#fff' : '#222'};
          border: none;
          padding: 0.5em;
          border-radius: 4px;
          cursor: pointer;
          transition: background-color 0.15s ease-in-out;
