        function toggleSentence(element) {
          const hiddenSentence = element.previousElementSibling;
          hiddenSentence.style.display = hiddenSentence.style.display === 'none' ? 'inline' : 'none';
        }

        function toggleDarkMode() {
          const urlParams = new URLSearchParams(window.location.search);
          const currentMode = urlParams.get('dark');
          const darkModeEnabled = currentMode !== 'true';
