const chai = require('chai');
const chaiHttp = require('chai-http');
const app = require('./index.js');

chai.use(chaiHttp);
const expect = chai.expect;

describe('Dark Mode Toggle', function() {
  it('should toggle dark mode on button click', function(done) {
    chai
      .request(app)
      .get('/www.example.com/path') // Update the path after the root URL
      .end(function(err, res) {
        expect(err).to.be.null;
        expect(res).to.have.status(200);
        expect(res).to.be.html;

        // Initial state: Light mode
        expect(res.text).to.include('background-color: white');
        expect(res.text).to.include('color: black');

        // Click the dark mode button
        chai
          .request(app)
          .get('/toggleDarkMode')
          .end(function(err, res) {
            expect(err).to.be.null;
            expect(res).to.have.status(200);
            expect(res).to.be.html;

            // Dark mode enabled
            expect(res.text).to.include('background-color: black');
            expect(res.text).to.include('color: white');

            // Click the dark mode button again
            chai
              .request(app)
              .get('/toggleDarkMode')
              .end(function(err, res) {
                expect(err).to.be.null;
                expect(res).to.have.status(200);
                expect(res).to.be.html;

                // Dark mode disabled
                expect(res.text).to.include('background-color: white');
                expect(res.text).to.include('color: black');

                done();
              });
          });
      });
  });
});

const chai = require('chai');
const chaiHttp = require('chai-http');
const app = require('./index.js');
const cheerio = require('cheerio');

chai.use(chaiHttp);
const expect = chai.expect;

describe('Dark Mode Toggle', function() {
  it('should toggle dark mode on button click', function(done) {
    chai
      .request(app)
      .get('/http://www.example.com') // Update the path after the root URL
      .end(function(err, res) {
        expect(err).to.be.null;
        expect(res).to.have.status(200);
        expect(res).to.be.html;

        const $ = cheerio.load(res.text);

        // Initial state: Light mode
        const initialBackgroundColor = $('body').css('background-color');
        const initialTextColor = $('body').css('color');
        expect(initialBackgroundColor).to.equal('rgb(255, 255, 255)');
        expect(initialTextColor).to.equal('rgb(0, 0, 0)');

        // Click the dark mode button
        chai
          .request(app)
          .get('/toggleDarkMode')
          .end(function(err, res) {
            expect(err).to.be.null;
            expect(res).to.have.status(200);
            expect(res).to.be.html;

            const $ = cheerio.load(res.text);

            // Dark mode enabled
            const darkBackgroundColor = $('body').css('background-color');
            const darkTextColor = $('body').css('color');
            expect(darkBackgroundColor).to.equal('rgb(0, 0, 0)');
            expect(darkTextColor).to.equal('rgb(255, 255, 255)');

            // Click the dark mode button again
            chai
              .request(app)
              .get('/toggleDarkMode')
              .end(function(err, res) {
                expect(err).to.be.null;
                expect(res).to.have.status(200);
                expect(res).to.be.html;

                const $ = cheerio.load(res.text);

                // Dark mode disabled
                const disabledBackgroundColor = $('body').css('background-color');
                const disabledTextColor = $('body').css('color');
                expect(disabledBackgroundColor).to.equal('rgb(255, 255, 255)');
                expect(disabledTextColor).to.equal('rgb(0, 0, 0)');

                done();
              });
          });
      });
  });
});

