function deleteItem(json, key) {
  if (!json.hasOwnProperty(key)) {
    console.log("The key does not exist in the JSON object.");
    return json;
  }

  delete json[key];
  return json;
}

function deleteItem(json, key, value) {
  if (!Array.isArray(json)) {
    console.log("The JSON object is not an array.");
    return json;
  }

  json.forEach((item) => {
    if (item.hasOwnProperty(key) && item[key] === value) {
      delete item[key];
    }
  });

  return json;
}

const express = require('express');
const path = require('path');
const fs = require('fs');

const app = express();
const dataFilePath = path.join(__dirname, 'data.json');

app.delete('/items/:id', (req, res) => {
  const itemId = req.params.id;

  // Read the JSON file
  fs.readFile(dataFilePath, 'utf8', (err, data) => {
    if (err) {
      console.error('Error reading the file:', err);
      return res.status(500).json({ error: 'Internal Server Error' });
    }

    let jsonData;

    try {
      jsonData = JSON.parse(data);
    } catch (parseErr) {
      console.error('Error parsing JSON:', parseErr);
      return res.status(500).json({ error: 'Internal Server Error' });
    }

    // Find the index of the item with the given ID
    const itemIndex = jsonData.findIndex(item => item.id === itemId);

    if (itemIndex === -1) {
      return res.status(404).json({ error: 'Item not found' });
    }

    // Remove the item from the array
    jsonData.splice(itemIndex, 1);

    // Write the updated JSON data back to the file
    fs.writeFile(dataFilePath, JSON.stringify(jsonData, null, 2), 'utf8', err => {
      if (err) {
        console.error('Error writing to file:', err);
        return res.status(500).json({ error: 'Internal Server Error' });
      }

      res.json({ message: 'Item deleted successfully' });
    });
  });
});

