data class CollisionResult(val intersects: Boolean, val penetrationDepth: Float = 0.0f, val penetrationNormal: Vector3? = null, val contactPoint: Vector3? = null)

fun collisionDetectionCapsuleTriangle(base: Vector3, tip: Vector3, radius: Float, p0: Vector3, p1: Vector3, p2: Vector3, N: Vector3): CollisionResult {
    val CapsuleNormal = (tip - base).normalize()
    val LineEndOffset = CapsuleNormal * radius
    val A = base + LineEndOffset
    val B = tip - LineEndOffset

    val t = N.dot((p0 - base) / N.dot(CapsuleNormal).absoluteValue)
    val line_plane_intersection = base + CapsuleNormal * t

    // Assuming ClosestPointOnLineSegment is a function that gives the closest point on the line segment AB to the given point
    var reference_point = ClosestPointOnLineSegment(A, B, line_plane_intersection)

    val c0 = (line_plane_intersection - p0).cross(p1 - p0)
    val c1 = (line_plane_intersection - p1).cross(p2 - p1)
    val c2 = (line_plane_intersection - p2).cross(p0 - p2)
    val inside = c0.dot(N) <= 0 && c1.dot(N) <= 0 && c2.dot(N) <= 0

    var best_dist = Float.MAX_VALUE

    if (!inside) {
        val point1 = ClosestPointOnLineSegment(p0, p1, line_plane_intersection)
        val v1 = line_plane_intersection - point1
        val distsq1 = v1.dot(v1)
        if (distsq1 < best_dist) {
            reference_point = point1
            best_dist = distsq1
        }

        val point2 = ClosestPointOnLineSegment(p1, p2, line_plane_intersection)
        val v2 = line_plane_intersection - point2
        val distsq2 = v2.dot(v2)
        if (distsq2 < best_dist) {
            reference_point = point2
            best_dist = distsq2
        }

        val point3 = ClosestPointOnLineSegment(p2, p0, line_plane_intersection)
        val v3 = line_plane_intersection - point3
        val distsq3 = v3.dot(v3)
        if (distsq3 < best_dist) {
            reference_point = point3
            best_dist = distsq3
        }
    }

    // Assuming a collision occurred if the best distance is less than the radius of the capsule
    val intersects = best_dist <= radius * radius

    return CollisionResult(intersects, sqrt(best_dist) - radius, if (intersects) (CapsuleNormal * -1) else null, if (intersects) reference_point else null)
}

// Get the canvas and context
var canvas = document.getElementById('gameCanvas');
var ctx = canvas.getContext('2d');

// Game variables
var ball = { x: 50, y: 50, radius: 10 };
var hoop = { x: 750, y: 100, width: 50, height: 10 };
var score = 0;
var timeLeft = 60; // 60 seconds

// Game loop
function gameLoop() {
    // Update game state
    update();

    // Draw game state
    draw();

    // Call the next game loop
    requestAnimationFrame(gameLoop);
}

// Update game state
function update() {
    // Decrease time left
    timeLeft -= 1 / 60; // decrease by one second every 60 frames

    // Check for collision between ball and hoop
    if (ball.x > hoop.x && ball.x < hoop.x + hoop.width &&
        ball.y > hoop.y && ball.y < hoop.y + hoop.height) {
        // Increase score and reset ball position
        score++;
        ball.x = 50;
        ball.y = 50;
    }
}

// Draw game state
function draw() {
    // Clear the canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw the ball
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2, false);
    ctx.fillStyle = 'orange';
    ctx.fill();
    ctx.closePath();

    // Draw the hoop
    ctx.beginPath();
    ctx.rect(hoop.x, hoop.y, hoop.width, hoop.height);
    ctx.fillStyle = 'red';
    ctx.fill();
    ctx.closePath();

    // Draw the score and time left
    ctx.font = '24px Arial';
    ctx.fillStyle = 'black';
    ctx.fillText('Score: ' + score, 20, 40);
    ctx.fillText('Time: ' + Math.ceil(timeLeft), 20, 80);
}

// Handle user input
canvas.addEventListener('click', function(event) {
    // Get the mouse position
    var rect = canvas.getBoundingClientRect();
    var mouseX = event.clientX - rect.left;
    var mouseY = event.clientY - rect.top;

    // Set the ball's position to the mouse position
    ball.x = mouseX;
    ball.y = mouseY;
});

// Start the game loop
gameLoop();

// Update game state
function update() {
    // Apply gravity to the ball's velocity
    ball.vy += gravity;

    // Update ball position based on velocity
    ball.x += ball.vx;
    ball.y += ball.vy;

    // Stop the ball when it hits the bottom of the canvas
    if (ball.y + ball.radius > canvas.height) {
        ball.y = canvas.height - ball.radius;
        ball.vy = 0;
    }

    // Decrease time left
    timeLeft -= 1 / 60; // decrease by one second every 60 frames

    // Check for collision between ball and hoop
    if (ball.x > hoop.x && ball.x < hoop.x + hoop.width &&
        ball.y > hoop.y && ball.y < hoop.y + hoop.height) {
        // Increase score and reset ball position and velocity
        score++;
        ball.x = 50;
        ball.y = 500;
        ball.vx = 0;
        ball.vy = 0;
    }
}

// Get the canvas and context
var canvas = document.getElementById('gameCanvas');
var ctx = canvas.getContext('2d');

// Game variables
var ball = { x: canvas.width / 2, y: canvas.height - 50, radius: 10, vx: 0, vy: 0 };
var hoop = { x: canvas.width / 2 - 25, y: canvas.height / 2, width: 50, height: 10 };
var gravity = 0.5;
var damping = 0.99; // air resistance
var score = 0;
var timeLeft = 60; // 60 seconds
var gameOver = false;

// Game loop
function gameLoop() {
    // Update game state
    update();

    // Draw game state
    draw();

    // Call the next game loop
    if (!gameOver) {
        requestAnimationFrame(gameLoop);
    }
}

// Update game state
function update() {
    // Apply gravity to the ball's velocity
    ball.vy += gravity;

    // Apply damping to the ball's velocity
    ball.vx *= damping;
    ball.vy *= damping;

    // Update ball position based on velocity
    ball.x += ball.vx;
    ball.y += ball.vy;

    // Stop the ball when it hits the bottom of the canvas
    if (ball.y + ball.radius > canvas.height) {
        ball.y = canvas.height - ball.radius;
        ball.vy = 0;
    }

    // Decrease time left
    timeLeft -= 1 / 60; // decrease by one second every 60 frames

    // Check for game over
    if (timeLeft <= 0) {
        gameOver = true;
    }

    // Check for collision between ball and hoop
    if (ball.x > hoop.x && ball.x < hoop.x + hoop.width &&
        ball.y > hoop.y && ball.y < hoop.y + hoop.height &&
        ball.vy > 0) { // only count if the ball is moving downward
        // Increase score by 2 and reset ball position and velocity
        score += 2;
        ball.x = canvas.width / 2;
        ball.y = canvas.height - 50;
        ball.vx = 0;
        ball.vy = 0;
    }
}

// Draw game state
function draw() {
    // Clear the canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw the ball
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2, false);
    ctx.fillStyle = 'orange';
    ctx.fill();
    ctx.closePath();

    // Draw the hoop
    ctx.beginPath();
    ctx.rect(hoop.x, hoop.y, hoop.width, hoop.height);
    ctx.fillStyle = 'red';
    ctx.fill();
    ctx.closePath();

    // Draw the score and time left
    ctx.font = '24px Arial';
    ctx.fillStyle = 'black';
    ctx.fillText('Score: ' + score, 20, 40);
    ctx.fillText('Time: ' + Math.ceil(timeLeft), 20, 80);

    // Draw game over
    if (gameOver) {
