// Game variables
var ball = { x: canvas.width / 2, y: canvas.height - 50, radius: 10, vx: 0, vy: 0 };
var hoop = { x: canvas.width / 2 - 25, y: canvas.height / 2, width: 50, height: 10, vx: 2 };
var gravity = 0.5;
var damping = 0.99; // air resistance
var bounce = -0.7; // bounce factor
var score = 0;
var timeLeft = 60; // 60 seconds
var gameOver = false;
var pauseTime = 5; // time to pause the hoop at the start of the game

// Game loop
function gameLoop() {
    // Update game state
    update();

    // Draw game state
    draw();

    // Call the next game loop
    if (!gameOver) {
        requestAnimationFrame(gameLoop);
    }
}

// Update game state
function update() {
    // Apply gravity to the ball's velocity
    ball.vy += gravity;

    // Apply damping to the ball's velocity
    ball.vx *= damping;
    ball.vy *= damping;

    // Update ball position based on velocity
    ball.x += ball.vx;
    ball.y += ball.vy;

    // Bounce the ball when it hits the bottom of the canvas
    if (ball.y + ball.radius > canvas.height) {
        ball.y = canvas.height - ball.radius;
        ball.vy *= bounce;
    }

    // Update hoop position based on velocity
    if (pauseTime <= 0) {
        hoop.x += hoop.vx;

        // Reverse hoop direction when it hits the edge of the canvas
        if (hoop.x < 0 || hoop.x + hoop.width > canvas.width) {
            hoop.vx = -hoop.vx;
        }
    } else {
        pauseTime -= 1 / 60;
    }

    // Decrease time left
    timeLeft -= 1 / 60; // decrease by one second every 60 frames

    // Check for game over
    if (timeLeft <= 0) {
        gameOver = true;
    }

    // Check for collision between ball and hoop
    if (ball.x > hoop.x && ball.x < hoop.x + hoop.width &&
        ball.y > hoop.y && ball.y < hoop.y + hoop.height &&
        ball.vy > 0) { // only count if the ball is moving downward
        // Increase score by 2 and reset ball position and velocity
        score += 2;
        ball.x = canvas.width / 2;
        ball.y = canvas.height - 50;
        ball.vx = 0;
        ball.vy = 0;
    }
}

// Draw game state
function draw() {
    // Clear the canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw the ball
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2, false);
    ctx.fillStyle = 'orange';
    ctx.fill();
    ctx.closePath();

    // Draw the hoop
    ctx.beginPath();
    ctx.rect(hoop.x, hoop.y, hoop.width, hoop.height);
    ctx.fillStyle = 'red';
    ctx.fill();
    ctx.closePath();

    // Draw the score and time left
    ctx.font = '24px Arial';
    ctx.fillStyle = 'black';
    ctx.fillText('Score: ' + score, 20, 40);
    ctx.fillText('Time: ' + Math.ceil(timeLeft), 20, 80);

    // Draw game over
    if (gameOver) {
        ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2);
    }
}

