var ctx = canvas.getContext('2d');

// Game variables
var ball = { x: canvas.width / 2, y: canvas.height - 30, radius: 30, vx: 0, vy: 0, isDragging: false, dragStart: {x: 0, y: 0} };
var hoop = { x: canvas.width / 2 - 100, y: canvas.height / 2 - 112.5, width: 200, height: 225, vx: 0.5 }; // updated hoop dimensions
var gravity = 0.5;
var damping = 0.99; // air resistance
var bounce = -0.7; // bounce factor
var score = 0;
var timeLeft = 60; // 60 seconds
var gameOver = false;
var pauseTime = 5; // time to pause the hoop at the start of the game

// Load images
var ballImage = new Image();
ballImage.src = 'ball.png'; // replace with the URL of your ball image

var hoopImage = new Image();
hoopImage.src = 'hoop.png'; // replace with the URL of your hoop image

var backgroundImage = new Image();
backgroundImage.src = 'background.png'; // replace with the URL of your background image

// Game loop
function gameLoop() {
    // Update game state
    update();

    // Draw game state
    draw();

    // Call the next game loop
    if (!gameOver) {
        requestAnimationFrame(gameLoop);
    }
}

// Update game state
function update() {
    // Apply gravity to the ball's velocity
    ball.vy += gravity;

    // Apply damping to the ball's velocity
    ball.vx *= damping;
    ball.vy *= damping;

    // Update ball position based on velocity
    ball.x += ball.vx;
    ball.y += ball.vy;

    // Bounce the ball when it hits the bottom of the canvas
    if (ball.y + ball.radius > canvas.height) {
        ball.y = canvas.height - ball.radius;
        ball.vy *= bounce;
    }

    // Bounce the ball when it hits the sides of the canvas
    if (ball.x - ball.radius < 0) {
        ball.x = ball.radius;
        ball.vx *= bounce;
    } else if (ball.x + ball.radius > canvas.width) {
        ball.x = canvas.width - ball.radius;
        ball.vx *= bounce;
    }

    // Update hoop position based on velocity
    if (pauseTime <= 0) {
        hoop.x += hoop.vx;

        // Reverse hoop direction when it hits the edge of the canvas
        if (hoop.x < 0 || hoop.x + hoop.width > canvas.width) {
            hoop.vx = -hoop.vx;
        }
    } else {
        pauseTime -= 1 / 60;
    }

    // Decrease time left
    timeLeft -= 1 / 60; // decrease by one second every 60 frames

    // Check for game over
    if (timeLeft <= 0) {
        gameOver = true;
    }

    // Check for collision between ball and hoop
    if (ball.x > hoop.x && ball.x < hoop.x + hoop.width &&
        ball.y > hoop.y && ball.y < hoop.y + hoop.height &&
        ball.vy > 0) {// only count if the ball is moving downward
        // Increase score by 2
        score += 2;
    }
}

// Draw game state
function draw() {
    // Clear the canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw the background
    ctx.drawImage(backgroundImage, 0, 0, canvas.width, canvas.height);

    // Draw the hoop
    ctx.drawImage(hoopImage, hoop.x, hoop.y, hoop.width, hoop.height);

    // Draw the ball
    ctx.drawImage(ballImage, ball.x - ball.radius, ball.y - ball.radius, ball.radius * 2, ball.radius * 2);

    // Draw the score and time left
    ctx.font = '24px Arial';
    ctx.fillStyle = 'black';
    ctx.fillText('Score: ' + score, 20, 40);
    ctx.fillText('Time: ' + Math.ceil(timeLeft), 20, 80);

    // Draw game over
    if (gameOver) {
        ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2);
    }
}

// Handle user input
canvas.addEventListener('mousedown', function(event) {
    // Get the mouse position
    var rect = canvas.getBoundingClientRect();
    var mouseX = event.clientX - rect.left;
    var mouseY = event.clientY - rect.top;

    // Check if the mouse is inside the ball
    var dx = mouseX - ball.x;
    var dy = mouseY - ball.y;
    var distance = Math.sqrt(dx * dx + dy * dy);
    if (distance < ball.radius) {
        ball.isDragging = true;
        ball.dragStart.x = mouseX;
        ball.dragStart.y = mouseY;
    }
});

canvas.addEventListener('mouseup', function(event) {
    if (ball.isDragging) {
        // Get the mouse position
        var rect = canvas.getBoundingClientRect();
        var mouseX = event.clientX - rect.left;
        var mouseY = event.clientY - rect.top;

        // Calculate the distance and direction from the ball to the mouse release point
        var dx = mouseX - ball.dragStart.x;
        var dy = mouseY - ball.dragStart.y;
        var distance = Math.sqrt(dx * dx + dy * dy);

        // Set the ball's velocity based on the distance and direction
        ball.vx = dx / distance * 20; // increased velocity
        ball.vy = dy / distance * 20; // increased velocity

        ball.isDragging = false;
    }
});

// Start the game loop
gameLoop();

