// Update game state
function update() {
    // Apply gravity to the ball's velocity
    ball.vy += gravity;

    // Apply damping to the ball's velocity
    ball.vx *= damping;
    ball.vy *= damping;

    // Update ball position based on velocity
    ball.x += ball.vx;
    ball.y += ball.vy;

    // Bounce the ball when it hits the bottom of the canvas
    if (ball.y + ball.radius > canvas.height) {
        ball.y = canvas.height - ball.radius;
        ball.vy *= bounce;
    }

    // Bounce the ball when it hits the sides of the canvas
    if (ball.x - ball.radius < 0) {
        ball.x = ball.radius;
        ball.vx *= bounce;
    } else if (ball.x + ball.radius > canvas.width) {
        ball.x = canvas.width - ball.radius;
        ball.vx *= bounce;
    }

    // Update hoop position based on velocity
    if (pauseTime <= 0) {
        hoop.x += hoop.vx;

        // Reverse hoop direction when it hits the edge of the canvas
        if (hoop.x < 0 || hoop.x + hoop.width > canvas.width) {
            hoop.vx = -hoop.vx;
        }
    } else {
        pauseTime -= 1 / 60;
    }

    // Decrease time left
    timeLeft -= 1 / 60; // decrease by one second every 60 frames

    // Check for game over
    if (timeLeft <= 0) {
        gameOver = true;
    }

    // Check for collision between ball and hoop
    if (ball.x > hoop.x && ball.x < hoop.x + hoop.width &&
        ball.y > hoop.y && ball.y < hoop.y + hoop.height &&
        ball.vy > 0) { // only count if the ball is moving downward
        // Increase score by 2 if the ball hasn't scored yet
        if (!ball.scored) {
            score += 2;
            ball.scored = true;
        }
    } else {
        ball.scored = false;
    }
}

// Draw game state
function draw() {
    // Clear the canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw the background
    ctx.drawImage(backgroundImage, 0, 0, canvas.width, canvas.height);

    // Draw the hoop
    ctx.drawImage(hoopImage, hoop.x, hoop.y, hoop.width, hoop.height);

    // Draw the ball
    ctx.drawImage(ballImage, ball.x - ball.radius, ball.y - ball.radius, ball.radius * 2, ball.radius * 2);

    // Draw the score and time left
    ctx.font = '24px Arial';
    ctx.fillStyle = 'black';
    ctx.fillText('Score: ' + score, 20, 40);
    ctx.fillText('Time: ' + Math.ceil(timeLeft), 20, 80);

    // Draw game over
    if (gameOver) {
        ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2);
        ctx.fillText('Click NEW GAME to play again', canvas.width / 2, canvas.height / 2 + 30);
    }
}

