    // Bounce the ball when it hits the sides of the canvas
    if (ball.x - ball.radius < 0) {
        ball.x = ball.radius;
        ball.vx *= bounce;
    } else if (ball.x + ball.radius > canvas.width) {
        ball.x = canvas.width - ball.radius;
        ball.vx *= bounce;
    }

    // Update hoop position based on velocity
    if (pauseTime <= 0) {
        hoop.x += hoop.vx;

        // Reverse hoop direction when it hits the edge of the canvas
        if (hoop.x < 0 || hoop.x + hoop.width > canvas.width) {
            hoop.vx = -hoop.vx;
        }
    } else {
        pauseTime -= 1 / 60;
    }

    // Decrease time left
    timeLeft-= 1 / 60; // decrease by one second every 60 frames

    // Check for game over
    if (timeLeft <= 0) {
        gameOver = true;
    }

    // Check for collision between ball and hoop
    if (ball.x > hoop.x && ball.x < hoop.x + hoop.width &&
        ball.y > hoop.y && ball.y < hoop.y + hoop.height &&
        ball.vy > 0) { // only count if the ball is moving downward
        // Increase score by 2 if the ball hasn't scored yet
        if (!ball.scored) {
            score += 2;
            ball.scored = true;
        }
    } else {
        ball.scored = false;
    }
}

// Draw game state
function draw() {
    // Clear the canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw the background
    ctx.drawImage(backgroundImage, 0, 0, canvas.width, canvas.height);

    // Draw the hoop
    ctx.drawImage(hoopImage, hoop.x, hoop.y, hoop.width, hoop.height);

    // Draw the ball
    ctx.drawImage(ballImage, ball.x - ball.radius, ball.y - ball.radius, ball.radius * 2, ball.radius * 2);

    // Draw the score and time left
    ctx.font = '24px Arial Black'; // updated font
    ctx.fillStyle = 'black';
    ctx.textAlign = 'center'; // set text alignment to center
    ctx.fillText('Score: ' + score, canvas.width / 2, 40);
    ctx.fillText('Time: ' + Math.ceil(timeLeft), canvas.width / 2, 80);

    // Draw countdown
    if (pauseTime > 5) {
        ctx.font = '48px Arial Black'; // updated font
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = 'white';
        ctx.fillText(countdown[countdownIndex], canvas.width / 2, canvas.height / 2);
    } else if (pauseTime > 2) {
        countdownIndex = 1;
        ctx.fillText(countdown[countdownIndex], canvas.width / 2, canvas.height / 2);
    } else if (pauseTime > 0) {
        countdownIndex = 2;
        ctx.fillText(countdown[countdownIndex], canvas.width / 2, canvas.height / 2);
    }

    // Draw game over
    if (gameOver) {
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.font = '48px Arial Black'; // updated font
        ctx.fillStyle = 'white';
        ctx.textAlign = 'center';
        ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2);

        ctx.font = '24px Arial Black'; // updated font
        ctx.fillText('Click NEW GAME to play again', canvas.width / 2, canvas.height / 2 + 30);
    }
}

// Handle user input
canvas.addEventListener('mousedown', function(event) {
    // Get the mouse position
    var rect = canvas.getBoundingClientRect();
    var mouseX = event.clientX - rect.left;
    var mouseY = event.clientY - rect.top;

    // Check if the mouse is inside the ball
    var dx = mouseX - ball.x;
    var dy = mouseY - ball.y;
    var distance = Math.sqrt(dx * dx + dy * dy);
    if (distance < ball.radius) {
        ball.isDragging = true;
        ball.dragStart.x = mouseX;
        ball.dragStart.y = mouseY;
    }

    // Check if the user clicked on the NEW GAME button
    if (gameOver && mouseY > canvas.height / 2 && mouseY < canvas.height / 2 + 40) {
        // Reset game variables
        ball = { x: canvas.width / 2, y: canvas.height - 30, radius: 30, vx: 0, vy: 0, isDragging: false, dragStart: {x: 0, y: 0}, scored: false };
        hoop = { x: canvas.width / 2 - 100, y: canvas.height / 2 - 112.5, width: 200, height: 225, vx: 0.5 }; // updated hoop dimensions
        score = 0;
        timeLeft = 60; // 60 seconds
        gameOver = false;
        pauseTime = 8; // time to pause the hoop at the start of the game
        countdownIndex = 0; // reset countdown index

        // Start the game loop
        gameLoop();
    }
});

canvas.addEventListener('mouseup', function(event) {
    if (ball.isDragging) {
        // Get the mouse position
        var rect = canvas.getBoundingClientRect();
        var mouseX = event.clientX - rect.left;
        var mouseY = event.clientY - rect.top;

        // Calculate the distance and direction from the ball to the mouse release point
        var dx = mouseX - ball.dragStart.x;
        var dy = mouseY - ball.dragStart.y;
        var distance = Math.sqrt(dx * dx + dy * dy);

        // Set the ball's velocity based on the distance and direction
        ball.vx = dx / distance * 20; // increased velocity
        ball.vy = dy / distance * 20; // increased velocity

        ball.isDragging = false;
    }
});

