// Get the canvas and context
var canvas = document.getElementById('gameCanvas');
var ctx = canvas.getContext('2d');

// Game variables
var ball = { x: canvas.width / 2, y: canvas.height - 30, radius: 30, vx: 0, vy: 0, isDragging: false, dragStart: {x: 0, y: 0}, scored: false, scoreTime: 0 };
var hoop = { x: canvas.width / 2 - 100, y: canvas.height / 2 - 112.5, width: 200, height: 225, vx: 0.5 }; // updated hoop dimensions
var gravity = 0.5;
var damping = 0.99; // air resistance
var bounce = -0.7; // bounce factor
var score = 0;
var timeLeft = 60; // 60 seconds
var gameOver = false;
var pauseTime = 11; // time to pause the hoop at the start of the game
var countdown = ["READY", "SET", "GO!"]; // countdown before the game starts
var countdownIndex = 0;

// Load images
var ballImage = new Image();
ballImage.src = 'ball.png'; // replace with the URL of your ball image

var hoopImage = new Image();
hoopImage.src = 'hoop.png'; // replace with the URL of your hoop image

var backgroundImage = new Image();
backgroundImage.src = 'background.png'; // replace with the URL of your background image

var greatShotImage = new Image();
greatShotImage.src = 'great_shot.png'; // load the "great shot" image

// Game loop
function gameLoop() {
    // Update game state
    update();

    // Draw game state
    draw();

    // Call the next game loop
    if (!gameOver) {
        requestAnimationFrame(gameLoop);
    }
}

// Update game state
function update() {
    // Apply gravity to the ball's velocity
    ball.vy += gravity;

    // Apply damping to the ball's velocity
    ball.vx *= damping;
    ball.vy *= damping;

    // Update ball position based on velocity
    ball.x += ball.vx;
    ball.y += ball.vy;

    // Bounce the ball when it hits the bottom of the canvas
    if (ball.y + ball.radius > canvas.height) {
        ball.y = canvas.height - ball.radius;
        ball.vy *= bounce;
    }

    // Bounce the ball when it hits the sides of the canvas
    if (ball.x - ball.radius < 0) {
        ball.x = ball.radius;
        ball.vx *= bounce;
    } else if (ball.x + ball.radius > canvas.width) {
        ball.x = canvas.width - ball.radius;
        ball.vx *= bounce;
    }

    // Update hoop position based on velocity
    if (pauseTime <= 0) {
        hoop.x += hoop.vx;

        // Reverse hoop direction when it hits the edge of the canvas
        if (hoop.x < 0 || hoop.x + hoop.width > canvas.width) {
            hoop.vx = -hoop.vx;
        }
    } else {
        pauseTime -= 1 / 60;
    }

    // Decrease time left
    if (pauseTime <= 2) {
        timeLeft -= 1 / 60; // decrease by one second every 60 frames
    }

    // Check for game over
    if (timeLeft<= 0) {
        gameOver = true;
    }

    // Check for collision between ball and hoop
    if (ball.x > hoop.x && ball.x < hoop.x + hoop.width &&
        ball.y > hoop.y && ball.y < hoop.y + hoop.height &&
        ball.vy > 0) { // only count if the ball is moving downward
        // Increase score by 2 if the ball hasn't scored yet
        if (!ball.scored) {
            score += 2;
            ball.scored = true;
            ball.scoreTime = 1; // set the score time to 1 second
        }
    } else {
        ball.scored = false;
    }

    // Decrease score time
    if (ball.scoreTime > 0) {
        ball.scoreTime -= 1 / 60; // decrease by one second every 60 frames
    }
}

// Draw game state
function draw() {
    // Clear the canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw the background
    ctx.drawImage(backgroundImage, 0, 0, canvas.width, canvas.height);

    // Draw the hoop
    ctx.drawImage(hoopImage, hoop.x, hoop.y, hoop.width, hoop.height);

    // Draw the ball
    ctx.drawImage(ballImage, ball.x - ball.radius, ball.y - ball.radius, ball.radius * 2, ball.radius * 2);

    // Draw the score and time left
    ctx.font = '24px Arial Black'; // updated font
    ctx.fillStyle = 'black';
    ctx.textAlign = 'center'; // set text alignment to center
    ctx.fillText('Score: ' + score, canvas.width / 2, 40);
    ctx.fillText('Time: ' + Math.ceil(timeLeft), canvas.width / 2, 80);

    // Draw "great shot" image when a shot is made
    if (ball.scoreTime > 0) {
        ctx.drawImage(greatShotImage, hoop.x + hoop.width / 2 - greatShotImage.width / 2, hoop.y - greatShotImage.height);
    }

    // Draw countdown
    if (pauseTime > 8) {
        ctx.font = '48px Arial Black'; // updated font
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = 'white';
        ctx.fillText(countdown[0], canvas.width / 2, canvas.height / 2);
    } else if (pauseTime > 5) {
        ctx.font = '48px Arial Black'; // updated font
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = 'white';
        ctx.fillText(countdown[1], canvas.width / 2, canvas.height / 2);
    } else if (pauseTime > 2) {
        ctx.font = '48px Arial Black'; // updated font
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = 'white';
        ctx.fillText(countdown[2], canvas.width / 2, canvas.height / 2);
    }

    // Draw game over
    if (gameOver) {
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.font= '48px Arial Black'; // updated font
        ctx.fillStyle = 'white';
        ctx.textAlign = 'center';
        ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2);

        ctx.font = '24px Arial Black'; // updated font
        ctx.fillText('Click NEW GAME to play again', canvas.width / 2, canvas.height / 2 + 30);
    }
}

