        ctx.font = '48px Arial Black'; // updated font
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = 'white';
        ctx.fillText(countdown[2], canvas.width / 2, canvas.height / 2);
    }

    // Draw game over
    if (gameOver) {
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.font = '48px Arial Black'; // updated font
```javascript
        ctx.fillStyle = 'white';
        ctx.textAlign = 'center';
        ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2);

        ctx.font = '24px Arial Black'; // updated font
        ctx.fillText('Click NEW GAME to play again', canvas.width / 2, canvas.height / 2 + 30);
    }
}

// Handle user input
canvas.addEventListener('mousedown', function(event) {
    // Get the mouse position
    var rect = canvas.getBoundingClientRect();
    var mouseX = event.clientX - rect.left;
    var mouseY = event.clientY - rect.top;

    // Check if the mouse is inside the ball
    var dx = mouseX - ball.x;
    var dy = mouseY - ball.y;
    var distance = Math.sqrt(dx * dx + dy * dy);
    if (distance < ball.radius) {
        ball.isDragging = true;
        ball.dragStart.x = mouseX;
        ball.dragStart.y = mouseY;
    }

    // Check if the user clicked on the NEW GAME button
    if (gameOver && mouseY > canvas.height / 2 && mouseY < canvas.height / 2 + 40) {
        // Reset game variables
        ball = { x: canvas.width / 2, y: canvas.height - 30, radius: 30, vx: 0, vy: 0, isDragging: false, dragStart: {x: 0, y: 0}, scored: false, scoreTime: 0 };
        hoop = { x: canvas.width / 2 - 100, y: canvas.height / 2 - 112.5, width: 200, height: 225, vx: 0.5 }; // updated hoop dimensions
        score = 0;
        timeLeft = 60; // 60 seconds
        gameOver = false;
        pauseTime = 11; // time to pause the hoop at the start of the game
        countdownIndex = 0; // reset countdown index

        // Start the game loop
        gameLoop();
    }
});

canvas.addEventListener('mouseup', function(event) {
    if (ball.isDragging) {
        // Get the mouse position
        var rect = canvas.getBoundingClientRect();
        var mouseX = event.clientX - rect.left;
        var mouseY = event.clientY - rect.top;

        // Calculate the distance and direction from the ball to the mouse release point
        var dx = mouseX - ball.dragStart.x;
        var dy = mouseY - ball.dragStart.y;
        var distance = Math.sqrt(dx * dx + dy * dy);

        // Set the ball's velocity based on the distance and direction
        ball.vx = dx / distance * 20; // increased velocity
        ball.vy = dy / distance * 20; // increased velocity

        ball.isDragging = false;
    }
});

// Start the game loop
gameLoop();

