    public ItemData item;

    private Image itemIcon;

    private void Awake()
    {
        // Try to find an existing Image component on the slot object
        itemIcon = GetComponentInChildren<Image>();

        // If an Image component doesn't exist, create one
        if (itemIcon == null)
        {
            itemIcon = gameObject.AddComponent<Image>();
        }
    }

    public void SetItem(ItemData newItem)
    {
        item = newItem;

        if (item != null)
        {
            itemIcon.sprite = item.icon;
            itemIcon.enabled = true;
        }
        else
        {
            itemIcon.sprite = null;
            itemIcon.enabled = false;
        }
    }
}

public class SmallInventory : MonoBehaviour
{
    public GameObject slotPrefab;
    public int slotAmount;
    private SmallInventorySlot[] slots;

    private void Start()
    {
        slots = new SmallInventorySlot[slotAmount];
        for (int i = 0; i < slotAmount; i++)
        {
            GameObject slot = Instantiate(slotPrefab, transform);
            slots[i] = slot.GetComponent<SmallInventorySlot>();
        }
    }

    public void AddItem(item itemToAdd)
    {
        if (itemToAdd != null)
        {
            for (int i = 0; i < slots.Length; i++)
            {
                if (slots[i].item == null)
                {
                    slots[i].item = itemToAdd;
                    slots[i].itemIcon.sprite = itemToAdd.icon;
                    slots[i].gameObject.SetActive(true);
                    break;
                }
            }
        }
    }
}

public bool AddItem(Item itemToAdd)
{
    for (int i = 0; i < slots.Length; i++)
    {
        if (slots[i].item == null)
        {
            if (itemToAdd.icon != null && slots[i].itemIcon != null)
            {
                slots[i].item = itemToAdd;
                slots[i].itemIcon.sprite = itemToAdd.icon;
                slots[i].itemIcon.enabled = true;
                return true;
            }
            else
            {
                Debug.LogError("Item icon or inventory slot icon is null.");
                return false;
            }
        }
    }
    return false;
}

public bool AddItem(ItemData itemToAdd)
{
    for (int i = 0; i < slots.Length; i++)
    {
        if (slots[i].item == null)
        {
            slots[i].item = itemToAdd;
            slots[i].itemIcon.sprite = itemToAdd.icon;
            return true;
        }
    }
    return false;
}

