    // Instantiate a new item game object
    GameObject newItemGO = Instantiate(itemPrefab, Vector3.zero, Quaternion.identity);
    newItemGO.transform.SetParent(inventoryPanel.transform); // Set the new item's parent to the inventory panel

    // Get the Item component on the new item game object
