private void OnTriggerEnter2D(Collider2D other)
{
    if (other.CompareTag("Player"))
    {
        // Create a copy of the item game object
        GameObject itemCopy = Instantiate(gameObject);

        // Add the item to the inventory
        InventoryManager.instance.AddItem(itemCopy);

        // Destroy the original item game object
        Destroy(gameObject);
    }
}

public class SmallInventorySlot : MonoBehaviour
{
    public Image itemIcon;
    public ItemData currentItem;

    public void SetItem(ItemData itemData)
    {
        // Instantiate item prefab
        GameObject newItemObj = Instantiate(itemData.prefab);

        // Get Item component from new item object
        Item newItem = newItemObj.GetComponent<Item>();

        // Set item data on new item
        newItem.itemData = itemData;

        // Set new item as current item
        currentItem = newItemData;

        // Set item icon
        itemIcon.sprite = itemData.icon;
    }

    public bool IsEmpty()
    {
        return currentItem == null;
    }
}

public class SmallInventorySlot : MonoBehaviour
{
    public ItemData itemData;
    public Image itemIcon;

    private GameObject currentItem;

    public void AddItem()
    {
        // Create a new item GameObject and set its itemData
        GameObject newItemObject = Instantiate(itemData.prefab, transform.position, transform.rotation);
        Item newItem = newItemObject.GetComponent<Item>();
        newItem.itemData = itemData;

        // Set the currentItem field to the new item GameObject
        currentItem = newItemObject;

        // Set the itemIcon to show the new item's icon
        itemIcon.sprite = itemData.icon;
    }
}

public void AddItem(GameObject itemPrefab)
{
    foreach (SmallInventorySlot slot in slots)
    {
        if (slot.IsEmpty())
        {
            GameObject newItem = Instantiate(itemPrefab, slot.transform);
            slot.SetItem(newItem.GetComponent<Item>());
            break;
        }
    }
}

public void SetItem(Item item)
{
    if (item == null)
    {
        itemIcon.sprite = null;
        itemIcon.enabled = false;
        currentItem = null;
        return;
    }

    itemIcon.sprite = item.icon;
    itemIcon.enabled = true;
    currentItem = item;

    // set the tooltip text to show the item's name and description
    tooltip.SetText(item.GetItemName() + "\n" + item.GetItemDescription());
}

