    if (itemData == null) // Check if there's an item assigned to this slot
    {
        Debug.LogWarning("No item assigned to this slot.");
        return;
    }

    // Create a new instance of the item prefab
    GameObject newItemObject = Instantiate(itemData.itemPrefab, position, Quaternion.identity);

    // Set the item data on the new item
    Item newItem = newItemObject.GetComponent<Item>();
    if (newItem != null)
    {
        newItem.SetItemData(itemData);
    }
    else
    {
        Debug.LogWarning("No item component found on the new item object.");
    }
}

