private void MoveShadowToSelectedSlot()
{
    if (selectedSlot != null)
    {
        // If a slot is selected, move the shadow to its position
        shadowRect.anchoredPosition = selectedSlot.RectTransform.anchoredPosition;
        if (selectedSlot.HasItem)
        {
            shadowImage.color = shadowColor;
        }
        else
        {
            shadowImage.color = shadowColorEmpty;
        }
    }
    else if (slots.Count > 0)
    {
        // If no slot is selected but there are slots in the inventory, move the shadow to the position of the first slot
        shadowRect.anchoredPosition = slots[0].RectTransform.anchoredPosition;
        shadowImage.color = shadowColorEmpty;
    }
}

