using UnityEngine;
using UnityEngine.EventSystems;

public class InventorySlot : MonoBehaviour, IDropHandler
{
    // Reference to the InventoryManager or other relevant script
    public InventoryManager inventoryManager;

    // Implement the OnDrop method from IDropHandler interface
    public void OnDrop(PointerEventData eventData)
    {
        // Check if there is an item being dragged
        if (eventData.pointerDrag != null)
        {
            // Get the dragged item's ItemData component
            ItemData draggedItemData = eventData.pointerDrag.GetComponent<ItemData>();

            // Check if the dragged item has an ItemData component
            if (draggedItemData != null)
            {
                // Call the AddItem method in the InventoryManager and pass the dragged item's ItemData
                inventoryManager.AddItem(draggedItemData.item);
            }
        }
    }
}

// Implement the OnEndDrag method from IEndDragHandler interface
public void OnEndDrag(PointerEventData eventData)
{
    // Check if there is an item in the inventory slot
    if (inventoryManager.GetItemInSlot(this) != null)
    {
        // Set the item back to its original parent (the inventory slot)
        eventData.pointerDrag.transform.SetParent(transform);
        eventData.pointerDrag.transform.position = transform.position;

        // Get the ItemBehavior script attached to the dragged item
        ItemBehavior itemBehavior = eventData.pointerDrag.GetComponent<ItemBehavior>();

        // Call the Use() function on the ItemBehavior script
        if (itemBehavior != null)
        {
            itemBehavior.Use();
        }
    }
}

