public class DraggedItem : MonoBehaviour, IDragHandler, IEndDragHandler
{
    // Reference to the RectTransform of the dragged item
    private RectTransform rectTransform;

    void Start()
    {
        // Get the RectTransform component on the dragged item
        rectTransform = GetComponent<RectTransform>();
    }

    public void OnDrag(PointerEventData eventData)
    {
        // Update the position of the dragged item to match the pointer's position
        rectTransform.position = eventData.position;
    }

    public void OnEndDrag(PointerEventData eventData)
    {
        // Reset the sorting order of the dragged item to its original value
        rectTransform.SetParent(null);
        rectTransform.SetSiblingIndex(eventData.pointerEnter.transform.GetSiblingIndex());
        rectTransform.SetParent(eventData.pointerEnter.transform);
    }
}

