public class DraggableItem : MonoBehaviour, IBeginDragHandler, IDragHandler, IEndDragHandler
{
    private Transform savedParent;

    public void OnBeginDrag(PointerEventData eventData)
    {
        // Store the parent of the dragged item object
        savedParent = transform.parent;

        // Detach the dragged item object from its parent
        transform.SetParent(null);
    }

    public void OnDrag(PointerEventData eventData)
    {
        // Perform the drag operation as usual
        transform.position = eventData.position;
    }

    public void OnEndDrag(PointerEventData eventData)
    {
        // Re-assign the dragged item object back to its original parent
        transform.SetParent(savedParent);

        // Reset the position and any other properties of the dragged item object
        transform.position = savedParent.position;
    }
}

