public void MoveToSibling(Transform targetSibling)
{
    // Get the parent of the target sibling
    Transform parent = targetSibling.parent;

    // Set the current transform's parent to the parent of the target sibling
    transform.SetParent(parent);

    // Set the current transform's sibling index to be immediately after the target sibling
    transform.SetSiblingIndex(targetSibling.GetSiblingIndex() + 1);
}

public void MoveToSibling(Transform targetSibling)
{
    // Get the parent of the target sibling
    Transform parent = targetSibling.parent;

    // Get the current RectTransform component
    RectTransform rectTransform = transform as RectTransform;

    // Store the current position and anchor values
    Vector3 position = rectTransform.position;
    Vector2 anchorMin = rectTransform.anchorMin;
    Vector2 anchorMax = rectTransform.anchorMax;

    // Set the current transform's parent to the parent of the target sibling
    transform.SetParent(parent);

    // Set the current transform's sibling index to be immediately after the target sibling
    transform.SetSiblingIndex(targetSibling.GetSiblingIndex() + 1);

    // Reset the RectTransform component's position and anchor values
    rectTransform.position = position;
    rectTransform.anchorMin = anchorMin;
    rectTransform.anchorMax = anchorMax;
}

