{
    if (eventData.button == PointerEventData.InputButton.Left)
    {
        // Check if the mouse is over an InventorySlot
        RaycastHit2D hit = Physics2D.Raycast(Camera.main.ScreenToWorldPoint(eventData.position), Vector2.zero);
        if (hit.collider != null && hit.collider.CompareTag("InventorySlot"))
        {
            // Get a reference to the InventorySlot and add the item to it
            InventorySlot inventorySlot = hit.collider.GetComponent<InventorySlot>();
            if (inventorySlot != null)
            {
                inventorySlot.AddItem(item);
            }
        }

        transform.position = originalPosition;
    }
}

