private bool isChestInventoryOpen = false; // Boolean flag to track if the chest inventory is open

void Update()
{
    // Check if the "i" key is pressed and the chest inventory is not open
    if (Input.GetKeyDown(KeyCode.I) && !isChestInventoryOpen)
    {
        // Open the player's inventory
        OpenPlayerInventory();
    }

    // Check if the "e" key is pressed and the chest inventory is open
    if (Input.GetKeyDown(KeyCode.E) && isChestInventoryOpen)
    {
        // Open the chest inventory
        OpenChestInventory();
    }
}

void OpenPlayerInventory()
{
    // Logic to open the player's inventory

    // Set isChestInventoryOpen to false, since the chest inventory is not open
    isChestInventoryOpen = false;
}

void OpenChestInventory()
{
    // Logic to open the chest inventory

    // Set isChestInventoryOpen to true, since the chest inventory is open
    isChestInventoryOpen = true;
}

if (Input.GetKeyDown("e"))
{
    if (isInventoryOpen)
    {
        // If the inventory is open, close it and the chest.
        isInventoryOpen = false;
        inventoryPanel.SetActive(false);
        isChestOpen = false;
    }
    else if (!isChestOpen)
    {
        // If the chest is not open and the inventory is closed, open the chest and inventory.
        isInventoryOpen = true;
        inventoryPanel.SetActive(true);
        isChestOpen = true;
        Vector2 newPosition = new Vector2(inventoryPanel.transform.position.x + 400f, inventoryPanel.transform.position.y);
        inventoryPanel.transform.position = newPosition;
    }
}

