class MainWindow : public QMainWindow
{
    Q_OBJECT

public:
    explicit MainWindow(QWidget *parent = nullptr);
    ~MainWindow();

private slots:
    void addECGData(int data);
    void addHeartRateData(unsigned int data);

private:
    QCustomPlot *ecgPlot;
    QCustomPlot *heartRatePlot;

    QVector<double> ecgData;
    QVector<double> heartRateData;

    QVector<double> ecgTime;
    QVector<double> heartRateTime;

    double startTime;

    SerialPortReader *serialReader;
};

#endif // MAINWINDOW_H

void MainWindow::addECGData(int data)
{
    double key = QDateTime::currentDateTime().toMSecsSinceEpoch() / 1000.0 - startTime;

    // Reset the plot if we've reached the end of the window
    if (key > 1) {
        key = 0;
        startTime = QDateTime::currentDateTime().toMSecsSinceEpoch() / 1000.0;
        ecgTime.clear();
        ecgData.clear();
    }

    ecgData.append(data);
    ecgTime.append(key);

    ecgPlot->graph(0)->setData(ecgTime, ecgData);
    ecgPlot->replot();
}

MainWindow::MainWindow(QWidget *parent) :
    QMainWindow(parent),
    ecgPlot(new QCustomPlot(this)),
    heartRatePlot(new QCustomPlot(this)),
    startTime(QDateTime::currentDateTime().toMSecsSinceEpoch() / 1000.0),
    serialReader(new SerialPortReader(this))
{
    QVBoxLayout *layout = new QVBoxLayout;
    layout->addWidget(ecgPlot);
    layout->addWidget(heartRatePlot);

    QWidget *mainWidget = new QWidget(this);
    mainWidget->setLayout(layout);

    setCentralWidget(mainWidget);

    ecgPlot->addGraph();
    ecgPlot->xAxis->setRange(0, 10);
    ecgPlot->yAxis->setRange(-600, 600);

    heartRatePlot->addGraph();
    heartRatePlot->xAxis->setRange(0, 10);
    heartRatePlot->yAxis->setRange(0, 200); // Assuming the heart rate will be between 0 and 200 bpm

    connect(serialReader, &SerialPortReader::newECGData, this, &MainWindow::addECGData);
    connect(serialReader, &SerialPortReader::newHeartRateData, this, &MainWindow::addHeartRateData);

    serialReader->start();
}

void MainWindow::addHeartRateData(unsigned int data)
{
    double key = QDateTime::currentDateTime().toMSecsSinceEpoch() / 1000.0 - startTime;

    heartRateData.append(data);
    heartRateTime.append(key);

    // If this is the first data point, save its time
    if (heartRateTime.size() == 1) {
        firstHeartRateTime = key;
    }

    // Remove data that's more than 10 seconds old
    while (!heartRateTime.isEmpty() && key - heartRateTime.first() > 10) {
        heartRateTime.removeFirst();
        heartRateData.removeFirst();
    }

    // Adjust the x-axis range to make the data scroll 10 seconds after the first data point
    if (key - firstHeartRateTime > 10 && key > heartRatePlot->xAxis->range().upper) {
        heartRatePlot->xAxis->setRange(key - 10, key);
    }

    heartRatePlot->graph(0)->setData(heartRateTime, heartRateData);

    // Auto-adjust the y-axis
    heartRatePlot->yAxis->rescale();

    heartRatePlot->replot();
}

void MainWindow::addHeartRateData(unsigned int data)
{
    double key = QDateTime::currentDateTime().toMSecsSinceEpoch() / 1000.0 - startTime;

    heartRateData.append(data);
    heartRateTime.append(key);

    heartRatePlot->graph(0)->setData(heartRateTime, heartRateData);

    // Auto-adjust both the x-axis and the y-axis
    heartRatePlot->xAxis->rescale();
    heartRatePlot->yAxis->rescale();

    heartRatePlot->replot();
}

MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent),
      serialReader(new SerialPortReader),
      startTime(QDateTime::currentDateTime().toMSecsSinceEpoch() / 1000.0),
      ecgPlot(new QCustomPlot),
      heartRatePlot(new QCustomPlot),
      latestHeartRateLabel(new QLabel(this))
{
    // Set up the layouts, plots and connections...

    // Place the label. Adjust the position and size as needed.
    latestHeartRateLabel->setGeometry(QRect(50, 50, 200, 50));
}

void MainWindow::addHeartRateData(unsigned int data)
{
    double key = QDateTime::currentDateTime().toMSecsSinceEpoch() / 1000.0 - startTime;

    heartRateData.append(data);
    heartRateTime.append(key);

    heartRatePlot->graph(0)->setData(heartRateTime, heartRateData);
    heartRatePlot->xAxis->setRange(*std::min_element(heartRateTime.constBegin(), heartRateTime.constEnd()), 
                                   *std::max_element(heartRateTime.constBegin(), heartRateTime.constEnd()) + 1);
    heartRatePlot->yAxis->setRange(*std::min_element(heartRateData.constBegin(), heartRateData.constEnd()) - 1,
                                   *std::max_element(heartRateData.constBegin(), heartRateData.constEnd()) + 1);

    // Update the label
    heartRateLabel->position->setType(QCPItemPosition::ptPlotCoords); 
    heartRateLabel->position->setCoords(key, data); // Using key and data here
    heartRateLabel->setText(QString::number(data));
    heartRateLabel->setFont(QFont(font().family(), 8));
    heartRateLabel->setColor(Qt::black);
    heartRateLabel->setPadding(QMargins(1, 1, 1, 1));

    heartRatePlot->replot();
}

