module vga_controller (
    input pixel_clk, 
    input async_reset,
    output n_blank, 
    output n_sync, 
    output reg h_sync, 
    output reg v_sync, 
    output display_enable,
    output reg [31:0] row, 
    output reg [31:0] column
);

// Parameters for 640x480 @60Hz
parameter h_visible = 640, v_visible = 480,
          h_sync_p = 16, v_sync_p = 2,
          h_back_porch = 48, v_back_porch = 33,
          h_front_porch = 96, v_front_porch = 10,
          h_total = h_visible + h_sync_p + h_back_porch + h_front_porch,
          v_total = v_visible + v_sync_p + v_back_porch + v_front_porch;

reg [31:0] h_counter = 0, v_counter = 0;

// Reset functionality
always @(posedge pixel_clk or negedge async_reset)
    if (!async_reset) begin
        h_counter <= 0;
        v_counter <= 0;
    end else begin
        h_counter <= (h_counter + 1) % h_total;
        if (h_counter == h_total - 1)
            v_counter <= (v_counter + 1) % v_total;
    end

// Sync signals
assign h_sync = (h_counter < h_visible + h_sync_p);
assign v_sync = (v_counter < v_visible + v_sync_p);

// Blank and sync signals
assign n_blank = (h_counter < h_visible) && (v_counter < v_visible);
assign n_sync = h_sync && v_sync;

// Display enable signal
assign display_enable = n_blank && !n_sync;

// Column and row
assign column = (display_enable) ? h_counter : 32'b0;
assign row = (display_enable) ? v_counter : 32'b0;

endmodule

module Wishbone_VGA_controller (
  input wire clk,    // Clock
  input wire rst,    // Reset
  // Wishbone slave interface
  input wire cyc,    // Cycle valid
  input wire stb,    // Strobe
  input wire we,     // Write enable
  input wire [1:0] adr, // Address
  input wire [31:0] dat,  // Data input
  output reg ack,   // Acknowledge
  output reg [31:0] dout, // Data output
  // VGA signals
  output wire display_enable,
  output wire h_sync,
  output wire v_sync
);

  // VGA controller parameters
  parameter h_total = 800, v_total = 525,
            h_sync = 96, v_sync = 2,
            h_start = 144, v_start = 34,
            h_end = 784, v_end = 514;

  reg [9:0] h_count, v_count;

  assign display_enable = (h_count >= h_start) && (h_count < h_end) &&
                          (v_count >= v_start) && (v_count < v_end);
  assign h_sync = (h_count < h_sync);
  assign v_sync = (v_count < v_sync);

  // Counters
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      h_count <= 0;
      v_count <= 0;
    end else begin
      if (h_count == h_total - 1) begin
        h_count <= 0;
        if (v_count == v_total - 1)
          v_count <= 0;
        else
          v_count <= v_count + 1;
      end else
        h_count <= h_count + 1;
    end
  end

  // Wishbone interface
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      ack <= 0;
      dout <= 0;
    end else if (cyc && stb) begin
      ack <= 1;
      if (we) begin // Write cycle
        case (adr)
          2'b00: dout <= {28'd0, display_enable, h_sync, v_sync};
          // .. add cases for other addresses ..
        endcase
      end else begin // Read cycle
        dout <= 32'h0000_0000; // Default read value
      end
    end else begin
      ack <= 0;
    end
  end
endmodule

module Wishbone_VGA_controller (
  input wire clk,    // Clock
  input wire rst,    // Reset
  // Wishbone slave interface
  input wire cyc,    // Cycle valid
  input wire stb,    // Strobe
  input wire we,     // Write enable
  input wire [1:0] adr, // Address
  input wire [31:0] dat,  // Data input
  output reg ack,   // Acknowledge
  output reg [31:0] dout, // Data output
  // VGA signals
  output wire display_enable,
  output wire h_sync_o,
  output wire v_sync_o
);

  // VGA controller parameters
  parameter h_total = 800, v_total = 525,
            h_sync = 96, v_sync = 2,
            h_start = 144, v_start = 34,
            h_end = 784, v_end = 514;

  reg [9:0] h_count, v_count;

  assign display_enable = (h_count >= h_start) && (h_count < h_end) &&
                          (v_count >= v_start) && (v_count < v_end);
  assign h_sync_o = (h_count < h_sync);
  assign v_sync_o = (v_count < v_sync);

  // Counters
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      h_count <= 0;
      v_count <= 0;
    end else begin
      if (h_count == h_total - 1) begin
        h_count <= 0;
        if (v_count == v_total - 1)
          v_count <= 0;
        else
          v_count <= v_count + 1;
      end else
        h_count <= h_count + 1;
    end
  end

  // Wishbone interface
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      ack <= 0;
      dout <= 0;
    end else if (cyc && stb) begin
      ack <= 1;
      if (we) begin // Write cycle
        case (adr)
          2'b00: dout <= {28'd0, display_enable, h_sync_o, v_sync_o};
          // .. add cases for other addresses ..
        endcase
      end else begin // Read cycle
        dout <= 32'h0000_0000; // Default read value
      end
    end else begin
      ack <= 0;
    end
  end
endmodule

module user_project_wrapper #(
    parameter HARDWARE_VERSION = 1,
    parameter USERID = 16'h0001 // << Change this to your ID
) (
    // ... (rest of module declaration as before)

    // User GPIO Signals
    input wire [37:0] gpio_i,
    output wire [37:0] gpio_o,
    output wire [37:0] gpio_en_o,

    // ... (rest of module declaration as before)
);

    // Instantiate VGA Controller
    Wishbone_VGA_controller vga_ctrl (
        .clk(wb_clk_i),
        .rst(wb_rst_i),
        .cyc(wb_cyc_i),
        .stb(wb_stb_i),
        .we(wb_we_i),
        .adr(wb_adr_i[1:0]),
        .dat(wb_dat_i),
        .ack(wb_ack_o),
        .dout(wb_dat_o),
        .vga_out(gpio_o[11:0]) // Connect 12-bit VGA output to GPIO[11:0]
    );

    assign gpio_en_o[11:0] = 12'b1111_1111_1111; // Enable output on GPIO pins 0-11
    assign gpio_o[37:12] = 26'b0; // Other GPIO pins are unused

endmodule

module AI_Vga(
    // ...
    // The rest of the module declaration
    // ...

    // Change the bit width of the row and column ports to 12 bits
    output reg [11:0] row, 
    output reg [11:0] column
);

    // ...

    // When assigning values to row and column, only use the 12 least significant bits
    always @(posedge pixel_clk)
        column <= (display_enable) ? h_counter[11:0] : 12'b0;

    always @(posedge pixel_clk)
        row <= (display_enable) ? v_counter[11:0] : 12'b0;

endmodule

module Wishbone_VGA_controller (
    // Wishbone bus inputs
    input  wire clk,
    input  wire rst,
    input  wire cyc,
    input  wire stb,
    input  wire we,     // Write Enable
    input  wire [1:0] adr,
    input  wire [31:0] dat,
    // Wishbone bus outputs
    output reg [31:0] dout,
    output reg ack
);

    // VGA controller outputs
    wire n_blank;
    wire n_sync;
    wire h_sync;
    wire v_sync;
    wire display_enable;
    wire [11:0] row;
    wire [11:0] column;

    // Instantiate VGA controller
    AI_Vga vga_controller (
        .pixel_clk(clk),
        .async_reset(!rst),
        .n_blank(n_blank),
        .n_sync(n_sync),
        .h_sync(h_sync),
        .v_sync(v_sync),
        .display_enable(display_enable),
        .row(row),
        .column(column)
    );

    // Wishbone bus operation
    always @(posedge clk) begin
        if (rst) begin
            ack <= 0;
            dout <= 0;
        end
        else if (cyc && stb) begin
            if (adr == 0) begin
                // Combine the VGA controller signals into one 32-bit output
                dout <= {n_blank, n_sync, h_sync, v_sync, display_enable, 27'b0};
            end
            else if (adr == 1) begin
                // Output the row and column values
                dout <= {row, column, 10'b0};
            end
            ack <= 1;
        end
        else begin
            ack <= 0;
        end
    end

endmodule

`timescale 1ns / 1ps

module testbench;

    // Declare wires and registers
    reg clk;
    reg rst;
    reg cyc;
    reg stb;
    reg we;
    reg [1:0] adr;
    reg [31:0] dat;
    wire [31:0] dout;
    wire ack;

    // Instantiate the DUT
    Wishbone_VGA_controller DUT (
        .clk(clk),
        .rst(rst),
        .cyc(cyc),
        .stb(stb),
        .we(we),
        .adr(adr),
        .dat(dat),
        .dout(dout),
        .ack(ack)
    );

    // Clock generation
    always begin
        #5 clk = ~clk;
    end

    // Stimulus process
    initial begin
        // Initialize inputs
        clk = 0;
        rst = 1;
        cyc = 0;
        stb = 0;
        we = 0;
        adr = 0;
        dat = 0;

        // Reset
        #10;
        rst = 0;
        #10;
        rst = 1;
        #10;

        // Write operation
        cyc = 1;
        stb = 1;
        we = 1;
        adr = 0;
        dat = 32'hDEADBEEF;
        #10;

        // Read operation
        we = 0;
        #10;

        // End of test
        $finish;
    end

endmodule

