class CountryAutoCompleteAdapter(
    context: Context,
    currencyMap: Map<String, String>
) : ArrayAdapter<String>(context, android.R.layout.simple_dropdown_item_1line) {

class CountryAutoCompleteAdapter(
    context: Context,
    currencyMap: Map<String, String>
) : ArrayAdapter<String>(context, android.R.layout.simple_dropdown_item_1line) {

    private val originalList: List<String> = currencyMap.keys.toList()

    private val filterableList: List<String> = currencyMap.values.toList()

    private val filter: Filter = object : Filter() {
        override fun performFiltering(constraint: CharSequence?): FilterResults {
            val results = FilterResults()
            val filteredList = mutableListOf<String>()

            if (constraint.isNullOrEmpty()) {
                filteredList.addAll(originalList)
            } else {
                val filterPattern = constraint.toString().toLowerCase(Locale.ROOT).trim()

                for (currency in originalList) {
                    if (currency.toLowerCase(Locale.ROOT).startsWith(filterPattern)) {
                        filteredList.add(currency)
                    }
                }
            }

            results.values = filteredList
            results.count = filteredList.size
            return results
        }

        override fun publishResults(constraint: CharSequence?, results: FilterResults?) {
            clear()
            if (results != null && results.count > 0) {
                addAll(results.values as List<String>)
            }
            notifyDataSetChanged()
        }
    }

    override fun getFilter(): Filter {
        return filter
    }
}

