test('Signup and Login flow', async ({ page }) => {
  // Mocking signup API request
  await page.route('/auth/signup', async (route) => {
    await route.fulfill({
      status: 201,
      body: JSON.stringify({}),
    })
  })

  // Mocking signin API request
  await page.route('/auth/signin', async (route) => {
    await route.fulfill({
      status: 200,
      body: JSON.stringify({
        access_token: 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJlbWFpbCI6InRlc3RAZ21haWwuY29tIiwic3ViIjo0LCJpYXQiOjE2NTk5MDQyMTUsImV4cCI6MTY2MDUwOTAxNX0.DyUCCsIGxIl8i_sGFCa3uQcyEDb9dChjbl40h3JWJNc',
      }),
    })
  })

  // Test for signup
  await page.goto('/signup')
  await page.fill('input[data-testid="email-input"]', 'test@gmail.com')
  await page.fill('input[data-testid="password-input"]', 'password123')
  await page.click('button[data-testid="signup-button"]')

  // Checking redirection to signin page after successful signup
  expect(page.url()).toBe('/signin')

  // Test for signin
  await page.fill('input[data-testid="email-input"]', 'test@gmail.com')
  await page.fill('input[data-testid="password-input"]', 'password123')
  await page.click('button[data-testid="signin-button"]')

  // Checking redirection to todo page after successful signin
  expect(page.url()).toBe('/todo')

  // Checking if token is stored in local storage after successful signin
  const jwt = await page.evaluate(() => localStorage.getItem('jwt'))
  expect(jwt).toBe('eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJlbWFpbCI6InRlc3RAZ21haWwuY29tIiwic3ViIjo0LCJpYXQiOjE2NTk5MDQyMTUsImV4cCI6MTY2MDUwOTAxNX0.DyUCCsIGxIl8i_sGFCa3uQcyEDb9dChjbl40h3JWJNc')

  // Test for redirection if JWT token is present
  // If user tries to access /signin or /signup, they should be redirected to /todo
  await page.goto('/signin')
  expect(page.url()).toBe('/todo')

  await page.goto('/signup')
  expect(page.url()).toBe('/todo')

  // Test for redirection if JWT token is absent
  // If user tries to access /todo, they should be redirected to /signin
  await page.evaluate(() => localStorage.removeItem('jwt'))
  await page.goto('/todo')
  expect(page.url()).toBe('/signin')
})

async function postData(url: string, data: any) {
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        // Add any other headers you need
      },
      body: JSON.stringify(data),
    });

    if (!response.ok) {
      throw new Error('Request failed');
    }

    const responseData = await response.json();
    // Process the response data
    console.log(responseData);
  } catch (error) {
    // Handle errors
    console.error('Error:', error);
  }
}

