player = 'O'
bot ='X'

def playerMove():
    position=int(input('Enter position for O:'))
    insertLetter(player, position)
    return

def compMove():
    bestScore=-1000
    bestMove=0
    for key in board.keys():
        if (board[key]==' '):
            board[key]=bot
            score = minimax(board, 0, False)
            board[key] = ' '
            if (score > bestScore):
                bestScore = score
                bestMove = key
    insertLetter(bot, bestMove)
    return

def minimax(board, depth, isMaximizing):
    if (chkMarkForWin(bot)):
        return 1
    elif (chkMarkForWin(player)):
        return -1
    elif (chkDraw()):
        return 0
    if isMaximizing:
        bestScore = -1000
        for key in board.keys():
            if board[key]==' ':
                board[key]=bot
                score = minimax(board, 0, False)
                board[key]= ' '
                if (score>bestScore):
                    bestScore = score
        return bestScore
    else:
        bestScore = 1000
        for key in board.keys():
            if board[key]==' ':
                board[key]=player
                score = minimax(board, 0, True)
                board[key]= ' '
                if (score<bestScore):
                    bestScore = score
        return bestScore

while not chkForWin():
    compMove()
    playerMove()

