export default function App({ Component, pageProps }: AppProps) {
  const [loginStatus, setLoginStatus] = useState(false);
  const [authToken, setAuthToken] = useState("");

  const handleLoginStatus = (isLoggedIn: boolean) => {
    setLoginStatus(isLoggedIn);
  };

  function getCookie(name:string) {
    const value = `; ${document.cookie}`;
    const parts = value.split(`; ${name}=`);
    if(parts.length === 2)
      return parts[1].split(';').shift();
  }

  useEffect(() => {
    const authToken = getCookie('auth-token');
    console.log('authToken from cookie:', authToken); // log the authToken retrieved from cookie
    if (authToken) {
      setAuthToken(authToken);
      setLoginStatus(true);
    } else {
      setLoginStatus(false);
    }
  }, []);

  useEffect(() => {
    console.log('authToken changed:', authToken); // log the authToken when it changes
  }, [authToken]);

  useEffect(() => {
    console.log('loginStatus changed:', loginStatus); // log the loginStatus when it changes
  }, [loginStatus]);

  return (

    <div>
      <TopNavbar handleLoginStatus={handleLoginStatus} isLoggedIn = {loginStatus}/>
      {loginStatus && (
        <div style = {{ display: "block" }}>
          <LeftMenu />
        </div>
      )}
      {loginStatus && (
        <div style = {{marginLeft: "15%"}}>
          <Component handleLoginStatus={handleLoginStatus} authToken={authToken} {...pageProps} />
        </div>
      )}
      {!loginStatus && (
        <div style = {{marginLeft: "0"}}>
          <Component handleLoginStatus={handleLoginStatus} authToken={authToken} {...pageProps} />
        </div>
      )}
    </div>

  );
}

