            }),
            credentials: 'include'
        });

        // Check that the cookie was set correctly
        const cookie = response.headers.get('set-cookie');
        console.log(cookie);

        // Make another request and include the cookie in the headers
        const profileResponse = await fetch('http://localhost:4000/profile', {
            method: 'GET',
            headers: {
                'Cookie': cookie
            },
            credentials: 'include'
        });
        const data = await profileResponse.json();
        console.log(data);

        return response;
    }
    catch (error) {
        console.error(error);
        return false;
    }
};

