async function handleLogin(event: FormEvent<HTMLFormElement>) {
  event.preventDefault();
  const formData = new FormData(event.target as HTMLFormElement);

  try {
    setIsLoading(true);
    const response = await loginUser(
      formData.get("emailInput")?.toString().trim() ?? "",
      formData.get("passwordInput")?.toString().trim() ?? ""
    );
    if (response.ok) {
      // Set the "auth-token" cookie if login is successful
      const authToken = await response.text();
      setCookie("auth-token", authToken);
      handleLoginStatus(true);
    } else {
      throw new Error("Invalid email or password");
    }
  } catch (error) {
    if (error instanceof Error) {
      setError(error.message);
    }
  } finally {
    setIsLoading(false);
  }
}

import { useEffect, useState } from "react";
import TopNavbar from "../components/TopNavbar";
import LeftMenu from "../components/LeftMenu";
import type { AppProps } from "next/app";
import { useRouter } from "next/router";
import { parseCookies } from "../utils/cookieUtils";

export default function App({ Component, pageProps }: AppProps) {
  const router = useRouter();
  const [loginStatus, setLoginStatus] = useState(false);
  const [authToken, setAuthToken] = useState("");

  const handleLoginStatus = (isLoggedIn: boolean) => {
    setLoginStatus(isLoggedIn);
  };

  useEffect(() => {
    const cookies = parseCookies();
    const authTokenFromCookie = cookies["auth-token"];
    if (authTokenFromCookie) {
      setAuthToken(authTokenFromCookie);
      setLoginStatus(true);
    } else {
      router.push("/login");
    }
  }, []);

  return (
    <div>
      <TopNavbar handleLoginStatus={handleLoginStatus} isLoggedIn={loginStatus} />
      {loginStatus && (
        <div style={{ display: "block" }}>
          <LeftMenu />
        </div>
      )}
      {loginStatus && (
        <div style={{ marginLeft: "15%" }}>
          <Component handleLoginStatus={handleLoginStatus} authToken={authToken} {...pageProps} />
        </div>
      )}
    </div>
  );
}

import { Form, Button, Spinner } from "react-bootstrap";
import { useState } from "react";
import { useRouter } from "next/router";
import { loginUser } from "../api/loginUser";
import styles from "../styles/Login.module.css";
import { setCookie } from "../utils/cookieUtils";

type loginProps = {
  handleLoginStatus: (status: boolean) => void;
};

function LoginPage({ handleLoginStatus }: loginProps) {
  const router = useRouter();
  const [error, setError] = useState("");
  const [isLoading, setIsLoading] = useState(false);

  async function handleLogin(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const formData = new FormData(event.target as HTMLFormElement);

    try {
      setIsLoading(true);
      const response = await loginUser(
        formData.get("emailInput")?.toString().trim() ?? "",
        formData.get("passwordInput")?.toString().trim() ?? ""
      );

      if (response.ok) {
        const { authToken } = await response.json();
        setCookie("auth-token", authToken, 7); // set cookie for 7 days
        handleLoginStatus(true);
      } else {
        throw new Error("Invalid email or password");
      }
    } catch (error) {
      if (error instanceof Error) {
        setError(error.message);
      }
    } finally {
      setIsLoading(false);
    }
  }

  return (
    <div className={styles.loginDiv}>
      <h1> Welcome back! </h1>
      <Form onSubmit={handleLogin}>
        <Form.Group className={styles.formInput} controlId="formLoginEmail">
          <Form.Label> EMAIL </Form.Label>
          <Form.Control
            type="email"
            name="emailInput"
            placeholder="example@gmail.com"
            required
          />
        </Form.Group>

        <Form.Group
          className={styles.formInput}
          controlId="formLoginPassword"
        >
          <Form.Label> PASSWORD </Form.Label>
          <Form.Control
            type="password"
            name="passwordInput"
            placeholder="surely not 1234"
            required
          />
        </Form.Group>

        {isLoading ? (
          <Button variant="secondary" disabled>
            <Spinner animation="border" size="sm" />
          </Button>
        ) : (
          <Button
            variant="secondary"
            type="submit"
            className={styles.loginSubmitButton}
          >
            Log In
          </Button>
        )}
        {error && <p className={styles.error}>{error}</p>}
      </Form>
    </div>
  );
}

export default LoginPage;

