using UnityEngine;

public class ProjectileShooter : MonoBehaviour
{
    public GameObject projectilePrefab;
    public Transform projectileSpawnPoint;
    public float shootForce = 10f;
    public float shootRate = 0.5f;

    private float nextShootTime;
    private ObjectPool projectilePool;

    private void Start()
    {
        // Create the object pool for projectiles
        projectilePool = new ObjectPool(projectilePrefab);
    }

    private void Update()
    {
        if (Input.GetKeyDown(KeyCode.Space) && Time.time >= nextShootTime)
        {
            // Shoot a projectile
            ShootProjectile();
            nextShootTime = Time.time + shootRate;
        }
    }

    private void ShootProjectile()
    {
        // Get a projectile from the object pool
        GameObject projectile = projectilePool.GetObjectFromPool();

        // Set the position and rotation of the projectile
        projectile.transform.position = projectileSpawnPoint.position;
        projectile.transform.rotation = projectileSpawnPoint.rotation;

        // Activate the projectile
        projectile.SetActive(true);

        // Apply force to the projectile
        Rigidbody rb = projectile.GetComponent<Rigidbody>();
        rb.velocity = projectileSpawnPoint.forward * shootForce;
    }
}

using System.Collections.Generic;
using UnityEngine;

public class ObjectPool
{
    private GameObject prefab;
    private List<GameObject> objectPool;

    public ObjectPool(GameObject prefab)
    {
        this.prefab = prefab;
        objectPool = new List<GameObject>();
    }

    public GameObject GetObjectFromPool()
    {
        // Find inactive object in the pool
        GameObject obj = objectPool.Find(o => !o.activeSelf);

        if (obj == null)
        {
            // If no inactive object found, create a new one
            obj = CreateNewObject();
        }

        return obj;
    }

    private GameObject CreateNewObject()
    {
        // Instantiate a new object from the prefab
        GameObject newObj = Object.Instantiate(prefab);

        // Add it to the object pool
        objectPool.Add(newObj);

        // Deactivate the object initially
        newObj.SetActive(false);

        return newObj;
    }
}

using System.Collections.Generic;
using UnityEngine;

public class ObjectPool
{
    private GameObject prefab;
    private Transform parentTransform;
    private List<GameObject> objectPool;

    public ObjectPool(GameObject prefab, int initialPoolSize, Transform parentTransform)
    {
        this.prefab = prefab;
        this.parentTransform = parentTransform;
        objectPool = new List<GameObject>(initialPoolSize);

        // Create and add objects to the pool
        for (int i = 0; i < initialPoolSize; i++)
        {
            CreateNewObject();
        }
    }

    public GameObject GetObjectFromPool()
    {
        // Find inactive object in the pool
        GameObject obj = objectPool.Find(o => !o.activeSelf);

        if (obj == null)
        {
            // If no inactive object found, create a new one
            obj = CreateNewObject();
        }

        return obj;
    }

    private GameObject CreateNewObject()
    {
        // Instantiate a new object from the prefab
        GameObject newObj = Object.Instantiate(prefab, parentTransform);

        // Add it to the object pool
        objectPool.Add(newObj);

        // Deactivate the object initially
        newObj.SetActive(false);

        return newObj;
    }
}

