function calculateStats() {
    const currentTime = new Date().getTime();
    let statsHTML = '';

    for (const char in charStats) {
        const stats = charStats[char];
        const wpm = stats.totalCorrect / ((currentTime - stats.timestamps[0]) / (60 * 1000)) * 5;
        const accuracy = (stats.totalCorrect / stats.totalTyped) * 100;
        const adjustedWpm = (accuracy / 100) * wpm;

        const greenComponent = Math.min(255, Math.round(adjustedWpm * 5)).toString(16);
        const color = '#00' + greenComponent + '00';

        statsHTML += `<div style="color: ${color}">${char}: WPM = ${adjustedWpm.toFixed(2)}, Accuracy = ${accuracy.toFixed(2)}%</div>`;
    }

    const statsDiv: HTMLElement = document.getElementById('stats')!;
    statsDiv.innerHTML = statsHTML;
}

