public class AttackBehavior : MonoBehaviour
{
    public float attackDamage = 10f;
    public float attackCooldown = 2f;
    public float attackRange = 2f;
    public float coneAngle = 60f;

    private Transform playerTransform;
    private bool canAttack = true;

    private void Start()
    {
        // Find the player reference
        playerTransform = GameObject.FindGameObjectWithTag("Player").transform;
    }

    private void Update()
    {
        // Check if the Evil Spirit is within attack range and can attack
        if (CanAttack() && IsPlayerInRange())
        {
            // Perform the attack
            Attack();
        }
    }

    private bool CanAttack()
    {
        // Check if the Evil Spirit is currently able to attack based on cooldown
        return canAttack;
    }

    private bool IsPlayerInRange()
    {
        // Check if the player is within attack range and within the cone angle
        float distanceToPlayer = Vector3.Distance(transform.position, playerTransform.position);
        if (distanceToPlayer <= attackRange)
        {
            Vector3 directionToPlayer = (playerTransform.position - transform.position).normalized;
            float angleToPlayer = Vector3.Angle(transform.forward, directionToPlayer);
            if (angleToPlayer <= coneAngle / 2f)
            {
                return true;
            }
        }

        return false;
    }

    private void Attack()
    {
        // Apply damage to the player or trigger any desired attack behavior
        // ...

        // Set attack on cooldown
        canAttack = false;
        Invoke(nameof(ResetAttackCooldown), attackCooldown);
    }

    private void ResetAttackCooldown()
    {
        // Reset attack cooldown
        canAttack = true;
    }
}

using UnityEngine;

public class EnemyController : MonoBehaviour
{
    private ChaseBehavior chaseBehavior;
    private AttackBehavior attackBehavior;

    public float outOfSightDuration = 3f;
    private float timeSincePlayerOutOfSight = 0f;
    private bool isChasing = false;

    private void Start()
    {
        // Get references to the ChaseBehavior and AttackBehavior components
        chaseBehavior = GetComponent<ChaseBehavior>();
        attackBehavior = GetComponent<AttackBehavior>();
    }

    private void Update()
    {
        // Check if the player is within sight range and activate chase behavior
        if (chaseBehavior.IsPlayerInSight())
        {
            chaseBehavior.ChasePlayer();
            timeSincePlayerOutOfSight = 0f;
            isChasing = true;
        }

        // Update the timer if the enemy is currently chasing
        if (isChasing)
        {
            timeSincePlayerOutOfSight += Time.deltaTime;

            // Check if the player has been out of sight for the specified duration
            if (timeSincePlayerOutOfSight >= outOfSightDuration)
            {
                // Deactivate chase behavior
                chaseBehavior.StopChasing();
                isChasing = false;
            }
        }

        // Check if the player is within attack range and activate attack behavior
        if (attackBehavior.CanAttack() && attackBehavior.IsPlayerInRange())
        {
            attackBehavior.Attack();
        }
    }
}

using UnityEngine;
using UnityEngine.AI;

public class PatrolBehavior : MonoBehaviour
{
    public Transform[] patrolPoints;
    public float patrolSpeed = 2f;

    private NavMeshAgent agent;
    private int currentPatrolIndex = 0;

    private void Start()
    {
        agent = GetComponent<NavMeshAgent>();
        SetDestinationToNextPatrolPoint();
    }

    private void Update()
    {
        if (!agent.pathPending && agent.remainingDistance < 0.1f)
        {
            SetDestinationToNextPatrolPoint();
        }
    }

    private void SetDestinationToNextPatrolPoint()
    {
        if (patrolPoints.Length == 0)
        {
            Debug.LogWarning("No patrol points assigned to the PatrolBehavior!");
            return;
        }

        agent.destination = patrolPoints[currentPatrolIndex].position;
        currentPatrolIndex = (currentPatrolIndex + 1) % patrolPoints.Length;
        agent.speed = patrolSpeed;
    }

    public void StartPatrolling()
    {
        agent.enabled = true;
        SetDestinationToNextPatrolPoint();
    }

    public void StopPatrolling()
    {
        agent.enabled = false;
    }
}

using UnityEngine;

public class WorldGenerator : MonoBehaviour
{
    public int worldSize = 100;
    public float scale = 0.1f;
    public float heightMultiplier = 10f;
    public int octaves = 4;
    public float persistence = 0.5f;
    public float lacunarity = 2f;

    public GameObject[] objectPrefabs;
    public int maxObjects = 1000;

    private void Start()
    {
        GenerateTerrain();
        GenerateObjects();
    }

    private void GenerateTerrain()
    {
        Terrain terrain = GetComponent<Terrain>();
        TerrainData terrainData = new TerrainData();

        terrainData.heightmapResolution = worldSize + 1;
        terrainData.size = new Vector3(worldSize, 100, worldSize);
        terrain.terrainData = terrainData;

        float[,] heightmap = new float[worldSize, worldSize];

        for (int x = 0; x < worldSize; x++)
        {
            for (int z = 0; z < worldSize; z++)
            {
                float height = CalculateHeight(x, z);
                heightmap[x, z] = height;
            }
        }

        terrainData.SetHeights(0, 0, heightmap);
    }

    private float CalculateHeight(int x, int z)
    {
        float height = 0f;
        float amplitude = 1f;
        float frequency = 1f;

        for (int i = 0; i < octaves; i++)
        {
            float perlinX = (float)x * scale * frequency;
            float perlinZ = (float)z * scale * frequency;
            float noiseValue = Mathf.PerlinNoise(perlinX, perlinZ) * 2f - 1f;

            height += noiseValue * amplitude;

            amplitude *= persistence;
            frequency *= lacunarity;
        }

        return height * heightMultiplier;
    }

    private void GenerateObjects()
    {
        for (int i = 0; i < maxObjects; i++)
        {
            Vector3 randomPosition = GetRandomPosition();
            int randomIndex = Random.Range(0, objectPrefabs.Length);
            GameObject prefab = objectPrefabs[randomIndex];

            Instantiate(prefab, randomPosition, Quaternion.identity);
        }
    }

    private Vector3 GetRandomPosition()
    {
        float x = Random.Range(0f, worldSize);
        float z = Random.Range(0f, worldSize);
        float y = Terrain.activeTerrain.SampleHeight(new Vector3(x, 0f, z));

        return new Vector3(x, y, z);
    }
}

using UnityEngine;

public class WorldGenerator : MonoBehaviour
{
    public int worldSize = 10;
    public float tileSize = 1f;
    public GameObject groundTilePrefab;

    private void Start()
    {
        GenerateWorld();
    }

    private void GenerateWorld()
    {
        Vector3 startingPosition = new Vector3(-(worldSize - 1) * tileSize * 0.5f, 0f, -(worldSize - 1) * tileSize * 0.5f);

        for (int x = 0; x < worldSize; x++)
        {
            for (int z = 0; z < worldSize; z++)
            {
                Vector3 tilePosition = startingPosition + new Vector3(x * tileSize, 0f, z * tileSize);
                Instantiate(groundTilePrefab, tilePosition, Quaternion.identity);
            }
        }
    }
}

