package main

import (
	"fmt"
	"strings"

	"github.com/texttheater/golang-levenshtein/levenshtein"
)

// Node represents a node in the trie
type Node struct {
	children map[rune]*Node
	isWord   bool
}

// Trie represents the trie data structure
type Trie struct {
	root *Node
}

// NewTrie initializes a new Trie
func NewTrie() *Trie {
	return &Trie{
		root: &Node{
			children: make(map[rune]*Node),
		},
	}
}

// Insert adds a word to the trie
func (t *Trie) Insert(word string) {
	word = strings.ToLower(word)
	current := t.root
	for _, char := range word {
		if node, ok := current.children[char]; ok {
			current = node
		} else {
			newNode := &Node{
				children: make(map[rune]*Node),
			}
			current.children[char] = newNode
			current = newNode
		}
	}
	current.isWord = true
}

// AutoComplete provides auto-complete suggestions for the given prefix
func (t *Trie) AutoComplete(prefix string) []string {
	prefix = strings.ToLower(prefix)
	current := t.root
	for _, char := range prefix {
		if node, ok := current.children[char]; ok {
			current = node
		} else {
			return nil
		}
	}

	var suggestions []string
	t.collectSuggestions(current, prefix, &suggestions)
	return suggestions
}

// collectSuggestions collects all the words in the trie under the given node
func (t *Trie) collectSuggestions(node *Node, prefix string, suggestions *[]string) {
	if node.isWord {
		*suggestions = append(*suggestions, prefix)
	}

	for char, child := range node.children {
		t.collectSuggestions(child, prefix+string(char), suggestions)
	}
}

// SpellCheck checks the spelling of a word and suggests possible corrections
func (t *Trie) SpellCheck(word string) string {
	word = strings.ToLower(word)

	if t.search(word) {
		return word // The word is already in the dictionary
	}

	// Calculate the Levenshtein distance between the misspelled word and every word in the trie
	minDistance := len(word)
	correction := word

	t.collectCorrections(t.root, word, "", &minDistance, &correction)

	return correction
}

// search checks if a word exists in the trie
func (t *Trie) search(word string) bool {
	current := t.root
	for _, char := range word {
		if node, ok := current.children[char]; ok {
			current = node
		} else {
			return false
		}
	}
	return current.isWord
}

// collectCorrections collects possible corrections for the given word
func (t *Trie) collectCorrections(node *Node, word, prefix string, minDistance *int, correction *string) {
	if node.isWord {
		distance := levenshtein.DistanceForStrings([]rune(word), []rune(prefix+word), levenshtein.DefaultOptions)
		if distance < *minDistance {
			*minDistance = distance
			*correction = prefix + word
		}
	}

	for char, child := range node.children {
		if len(prefix) <= *minDistance {
			t.collectCorrections(child, word, prefix+string(char), minDistance, correction)
		}
	}
}

func main() {
	// Create a new trie
	trie := NewTrie()

	// Insert words into the trie
	words := []string{"apple", "application", "apply", "book", "banana"}
	for _, word := range words {
		trie.Insert(word)
	}

	// Spell check a word and get possible corrections
	misspelledWord := "aple"
	correction := trie.SpellCheck(misspelledWord)
	fmt.Printf("Original word: %s\n", misspelledWord)
	fmt.Printf("Suggested correction: %s\n", correction)

	// Auto-complete suggestions for a given prefix
	prefix := "app"
	suggestions := trie.AutoComplete(prefix)
	fmt.Printf("Auto-complete suggestions for '%s': %v\n", prefix, suggestions)
}

