const handler = new Cesium.ScreenSpaceEventHandler(viewer.canvas);
handler.setInputAction(function(movement) {
  const ray = viewer.camera.getPickRay(movement.position);
  const worldPosition = viewer.scene.globe.pick(ray, viewer.scene);

  if(Cesium.defined(worldPosition)) {
    const cartographicPosition = Cesium.Cartographic.fromCartesian(worldPosition);
    const longitude = Cesium.Math.toDegrees(cartographicPosition.longitude);
    const latitude = Cesium.Math.toDegrees(cartographicPosition.latitude);

    viewer.camera.flyTo({
      destination: Cesium.Cartesian3.fromDegrees(longitude, latitude, 10000),
      duration: 2,
    });
  }
}, Cesium.ScreenSpaceEventType.LEFT_DOUBLE_CLICK);

let rotateInterval;
let speed = 0.01;

document.addEventListener('keydown', function(event) {
  if (rotateInterval) { // If a rotation is already ongoing, ignore further keydown events
    return;
  }

  switch(event.key) {
    case 'ArrowDown':  // Swapped 'ArrowUp' with 'ArrowDown'
      rotateInterval = setInterval(function() {
        speed = Math.min(speed + 0.001, 0.1); // Increment speed, with max limit
        viewer.camera.rotateUp(Cesium.Math.toRadians(speed));
      }, 20);
      break;
    case 'ArrowUp':  // Swapped 'ArrowDown' with 'ArrowUp'
      rotateInterval = setInterval(function() {
        speed = Math.min(speed + 0.001, 0.1); // Increment speed, with max limit
        viewer.camera.rotateDown(Cesium.Math.toRadians(speed));
      }, 20);
      break;
    case 'ArrowRight':
      rotateInterval = setInterval(function() {
        speed = Math.min(speed + 0.001, 0.1); // Increment speed, with max limit
        viewer.camera.rotateRight(Cesium.Math.toRadians(speed));
      }, 20);
      break;
    case 'ArrowLeft':
      rotateInterval = setInterval(function() {
        speed = Math.min(speed + 0.001, 0.1); // Increment speed, with max limit
        viewer.camera.rotateLeft(Cesium.Math.toRadians(speed));
      }, 20);
      break;
  }
});

document.addEventListener('keyup', function(event) {
  clearInterval(rotateInterval);
  rotateInterval = undefined;
  speed = 0.01;  // Reset the speed
});

