      }

      if (keys.ArrowRight) {
        viewer.camera.rotateRight(Cesium.Math.toRadians(horizontalSpeed));
      }

      if (keys.ArrowLeft) {
        viewer.camera.rotateLeft(Cesium.Math.toRadians(horizontalSpeed));
      }
    }, 20);
  }
});

