import platform
import os
import winreg

def is_browser_installed(browser_name: str) -> bool:
    system_name = platform.system()

    if system_name == "Windows":
        if browser_name == "chrome":
            try:
                reg_path = r"SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\chrome.exe"
                with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, reg_path, 0, winreg.KEY_READ) as key:
                    value, _ = winreg.QueryValueEx(key, None)
                    return os.path.exists(value)
            except WindowsError:
                return False

        elif browser_name == "firefox":
            try:
                reg_path = r"SOFTWARE\Mozilla\Mozilla Firefox"
                with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, reg_path, 0, winreg.KEY_READ) as key:
                    subkey_count = winreg.QueryInfoKey(key)[0]
                    for i in range(subkey_count):
                        subkey_name = winreg.EnumKey(key, i)
                        subkey_path = os.path.join(reg_path, subkey_name, "Main")
                        with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, subkey_path, 0, winreg.KEY_READ) as subkey:
                            value, _ = winreg.QueryValueEx(subkey, "PathToExe")
                            if os.path.exists(value):
                                return True
                    return False
            except WindowsError:
                return False

        else:
            return False

    elif system_name == "Darwin" or system_name == "Linux":
        # ...existing code for macOS and Linux...
        return False

    else:
        return False

#include <omp.h>

double dot_product(double* a, double* b, int size) {
    double result = 0.0;
    #pragma omp parallel for reduction(+:result)
    for(int i = 0; i < size; i++) {
        result += a[i] * b[i];
    }
    return result;
}

#include <arm_neon.h>

double dot_product(float* a, float* b, int size) {
    float32x4_t a_vec, b_vec, result_vec = vdupq_n_f32(0.0f);
    float result_array[4];
    double result = 0.0;

    for(int i = 0; i < size; i += 4) {
        a_vec = vld1q_f32(a + i);
        b_vec = vld1q_f32(b + i);
        result_vec = vmlaq_f32(result_vec, a_vec, b_vec);
    }

    vst1q_f32(result_array, result_vec);
    for(int i = 0; i < 4; i++) {
        result += result_array[i];
    }

    return result;
}

#include <arm_neon.h>
#include <omp.h>

double dot_product(float* a, float* b, int size) {
    float result_array[4];
    double result = 0.0;

    #pragma omp parallel
    {
        float32x4_t a_vec, b_vec, result_vec = vdupq_n_f32(0.0f);

        #pragma omp for
        for(int i = 0; i < size; i += 4) {
            a_vec = vld1q_f32(a + i);
            b_vec = vld1q_f32(b + i);
            result_vec = vmlaq_f32(result_vec, a_vec, b_vec);
        }

        vst1q_f32(result_array, result_vec);

        #pragma omp atomic
        for(int i = 0; i < 4; i++) {
            result += result_array[i];
        }
    }

    return result;
}

from abc import ABC, abstractmethod
import redis
import openai
import numpy as np
from redis.commands.search.query import Query
from redis.commands.search.field import VectorField, TextField
from redis.commands.search.indexDefinition import IndexDefinition, IndexType

class EmbeddingModel(ABC):
    @abstractmethod
    def create_embedding(self, text: str):
        pass

class OpenAIEmbeddingModel(EmbeddingModel):
    def create_embedding(self, text: str):
        embedding = openai.Embedding.create(input=text, model="text-embedding-ada-002")
        vector = embedding["data"][0]["embedding"]
        vector = np.array(vector).astype(np.float32).tobytes()
        return vector

class EmbeddingStorage(ABC):
    @abstractmethod
    def store(self, key: str, vector):
        pass

    @abstractmethod
    def retrieve(self, key: str):
        pass

    @abstractmethod
    def search(self, vector, top_k=5):
        pass

class RedisEmbeddingStorage(EmbeddingStorage):
    def __init__(self, host='localhost', port=6379, db=0):
        self.r = redis.Redis(host=host, port=port, db=db, encoding='utf-8', decode_responses=True)
        self.SCHEMA = [
            TextField("url"),
            VectorField("embedding", "HNSW", {"TYPE": "FLOAT32", "DIM": 1536, "DISTANCE_METRIC": "COSINE"}),
        ]
        try:
            self.r.ft("posts").create_index(fields=self.SCHEMA, definition=IndexDefinition(prefix=["post:"], index_type=IndexType.HASH))
        except Exception as e:
            print("Index already exists")

    def store(self, key: str, vector):
        post_hash = {
            "url": key,
            "embedding": vector
        }
        self.r.hset(name=f"post:{key}", mapping=post_hash)

    def retrieve(self, key: str):
        return self.r.hget(name=f"post:{key}", key="embedding")

    def search(self, vector, top_k=5):
        base_query = f"*=>[KNN {top_k} @embedding $vector AS vector_score]"
        query = Query(base_query).return_fields("url", "vector_score").sort_by("vector_score").dialect(2)
        try:
            results = self.r.ft("posts").search(query, query_params={"vector": vector})
        except Exception as e:
            print("Error calling Redis search: ", e)
            return None
        return results

