async function callOpenAIChatAPI(userInput, apiKey, userJoined = false) {
    const apiURL = "https://api.openai.com/v1/chat/completions";

    if (!userJoined) {
        messages.push({ "role": "user", "content": `${nextPersona}: ${userInput}` });
    }

    messages.push({ "role": "system", "content": `You are a helpful assistant that speaks like ${nextPersona === persona1.value ? persona2.value : persona1.value}.` });
    messages.push({ "role": "user", "content": "" });

    const requestBody = {
        "model": "gpt-3.5-turbo",
        "messages": messages,
        "max_tokens": 150,
        "temperature": 0.7,
        "n": 1,
        "stop": null,
    };

    const response = await fetch(apiURL, {
        method: "POST",
        headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${apiKey}`,
        },
        body: JSON.stringify(requestBody),
    });

    if (!response.ok) {
        throw new Error("An error occurred while processing the API request.");
    }

    const responseData = await response.json();
    const responseMessage = responseData.choices[0].message.content.trim();

    messages.push({ "role": "user", "content": `${nextPersona}: ${responseMessage}` });

    return responseMessage;
}

