import React, { useEffect, useState } from 'react';
import styled from 'styled-components';

const SlidingBarContainer = styled.div`
  width: 100%;
  height: 20px;
  background-color: #e0e0e0;
  overflow: hidden;
`;

interface SlidingBarProps {
  width: number;
}

const SlidingBar = styled.div<SlidingBarProps>`
  height: 100%;
  background-color: #4285f4;
  transition: width 0.5s ease-in-out;
  width: ${(props) => props.width}%;
`;

interface Props {
  percentage: number;
}

const SlidingBarComponent: React.FC<Props> = ({ percentage }) => {
  const [slideWidth, setSlideWidth] = useState(0);

  useEffect(() => {
    setSlideWidth(percentage);
  }, [percentage]);

  return (
    <SlidingBarContainer>
      <SlidingBar width={slideWidth} />
    </SlidingBarContainer>
  );
};

export default SlidingBarComponent;

