import React, { useEffect, useState } from 'react';
import styled from 'styled-components';

interface SlidingBarContainerProps {
  color: string;
}

const SlidingBarContainer = styled.div<SlidingBarContainerProps>`
  width: 100%;
  height: 20px;
  background-color: #e0e0e0;
  overflow: hidden;
`;

interface SlidingBarProps {
  width: number;
  color: string;
}

const SlidingBar = styled.div<SlidingBarProps>`
  height: 100%;
  background-color: ${(props) => props.color};
  transition: width 0.5s ease-in-out;
  width: ${(props) => props.width}%;
  position: relative;
`;

const BarText = styled.span`
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  color: #ffffff;
  font-weight: bold;
`;

interface Props {
  percentage: number;
  color: string;
  text: string;
}

const SlidingBarComponent: React.FC<Props> = ({ percentage, color, text }) => {
  const [slideWidth, setSlideWidth] = useState(0);

  useEffect(() => {
    setSlideWidth(percentage);
  }, [percentage]);

  return (
    <SlidingBarContainer color={color}>
      <SlidingBar width={slideWidth} color={color}>
        <BarText>{text}</BarText>
      </SlidingBar>
    </SlidingBarContainer>
  );
};

export default SlidingBarComponent;

