  .document('blogs/{wildcard}')
  .onCreate((snapshot, context) => {
    const blogData = snapshot.data();
    const scheduledDate = blogData.scheduledDate.toDate(); // Convert scheduledDate to a JavaScript Date object
    const currentDate = new Date();

    if (currentDate >= scheduledDate) {
      return snapshot.ref.update({ isVisible: true }); // Update the document visibility field to true
    }

    return null; // No update required if the scheduled date is in the future
  });

async function mainLoop(model) {
    const predictions = await model.estimateHands(video);
    const directionVector = await detectFingerDirection(predictions);

    if (directionVector && predictions.length > 0) {
        const indexFingerTip = predictions[0].landmarks[8];
        const x = indexFingerTip[0];
        const y = indexFingerTip[1];

        if (directionVector.y < 0) {
            // Finger is pointing upwards, start drawing
            drawing = true;
            draw(x, y);
        } else {
            // Finger is not pointing upwards, stop drawing
            drawing = false;
            ctx.beginPath();
        }
    }

    requestAnimationFrame(() => mainLoop(model));
}

