import AVFoundation

func generatePCMBuffer() -> AVAudioPCMBuffer? {
    // 設定聲音參數
    let sampleRate = 44100.0 // 44.1kHz 采樣率
    let duration = 1.0 // 1秒長度
    let frequency = 1000.0 // 1kHz 頻率
    let amplitude: Float = 0.5 // 振幅，這決定了聲音的音量

    let totalSamples = Int(duration * sampleRate)

    // 創建AVAudioFormat，使用指定的格式參數
    let format = AVAudioFormat(commonFormat: .pcmFormatInt16, sampleRate: sampleRate, channels: 2, interleaved: true)

    // 創建AVAudioPCMBuffer
    guard let buffer = AVAudioPCMBuffer(pcmFormat: format, frameCapacity: AVAudioFrameCount(totalSamples)) else {
        return nil
    }

    // 計算sin函數的值並填充音頻數據到buffer
    let channelCount = Int(format.channelCount)
    let int16max = Int16.max
    let channelData = buffer.int16ChannelData

    for sample in 0..<totalSamples {
        let time = Double(sample) / sampleRate
        let value = Int16(amplitude * Float(int16max) * sin(2 * .pi * frequency * time))

        for channel in 0..<channelCount {
            channelData[Int(channel)][sample] = value
        }
    }

    buffer.frameLength = AVAudioFrameCount(totalSamples)
    return buffer
}

function minifyJavaScript(jsCode) {
  // Remove comments (single-line and multi-line)
  jsCode = jsCode.replace(/\/\/.*|\/\*[\s\S]*?\*\//g, "");

  // Remove line breaks and multiple whitespaces
  jsCode = jsCode.replace(/\s+/g, " ");

  // Remove whitespace around symbols
  jsCode = jsCode.replace(/\s*([{}()[\].,;:+-*/%&|^!=<>?~]|==|===|!=|!==|\+=|-=|\*=|\/=|%==|&&|\|\||<<|>>|>>>)\s*/g, "$1");

  // Shorten variable and function names (optional)
  // For simplicity, this example uses single-letter names
  jsCode = jsCode.replace(/\b\w+\b/g, match => {
    const firstLetter = match.charAt(0);
    return /^[A-Za-z]$/.test(firstLetter) ? firstLetter : match;
  });

  return jsCode;
}

