let tableOfContents = [];
let currentLine = 0;

async function generateContent(role, prompt) {
    const response = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: headers,
        body: JSON.stringify({
            model: 'gpt-3.5-turbo',
            messages: [{
                role: 'system',
                content: role
            }, {
                role: 'user',
                content: prompt
            }]
        })
    });
    const data = await response.json();
    return data.choices[0].message.content;
}

async function generateContents() {
    const gptRole = document.getElementById('gpt-role').value;
    const concept = document.getElementById('concept').value;
    const genre = document.getElementById('genre').value;
    const keywords = document.getElementById('keywords').value.split(',');

    const prompt = `Based on the ${genre} concept: "${concept}" with keywords: ${keywords.join(', ')}, generate a table of contents.`;

    const contents = await generateContent(gptRole, prompt);
    document.getElementById('contents').value = contents;
    // Split the table of contents into lines
    tableOfContents = contents.split('\n').filter(line => line.trim() !== '');
}

async function generateChapter() {
    if (currentLine >= tableOfContents.length) {
        console.log("All chapters generated");
        return;
    }

    const gptRole = document.getElementById('gpt-role').value;
    const genre = document.getElementById('genre').value;
    const keywords = document.getElementById('keywords').value.split(',');

    const prompt = `Based on the ${genre} chapter title: "${tableOfContents[currentLine]}" with keywords: ${keywords.join(', ')}, generate the chapter content.`;

    const chapter = await generateContent(gptRole, prompt);
    const chapterDiv = document.getElementById('chapters');
    chapterDiv.innerHTML += `<h2>${tableOfContents[currentLine]}</h2><p>${chapter}</p>`;
    currentLine++;

    // If "Auto Generate Chapters" is checked, automatically generate the next chapter
    const autoGenerateChapters = document.getElementById('auto-chapters').checked;
    if (autoGenerateChapters) {
        generateChapter();
    }
}

document.getElementById('chaptersButton').addEventListener('click', generateChapter);

import React, { useRef, useState } from 'react';

function App() {
  const [recording, setRecording] = useState(false);
  const [recordedChunks, setRecordedChunks] = useState([]);
  const videoRef = useRef();
  const recordedVideoRef = useRef();
  let mediaRecorder = useRef(null);

  const handleStart = async () => {
    const stream = await navigator.mediaDevices.getUserMedia({ video: true });
    videoRef.current.srcObject = stream;

    mediaRecorder.current = new MediaRecorder(stream);
    mediaRecorder.current.ondataavailable = handleDataAvailable;
    mediaRecorder.current.start(100); // collect 100ms of data at a time
    setRecording(true);
  };

  const handleDataAvailable = (event) => {
    if (event.data && event.data.size > 0) {
      setRecordedChunks((prev) => [...prev, event.data]);
    }
  };

  const handleStop = () => {
    mediaRecorder.current.stop();
    videoRef.current.srcObject.getTracks().forEach((track) => track.stop());
    setRecording(false);
  };

  const updateVideoPlayback = () => {
    let blob = new Blob(recordedChunks, { type: 'video/webm' });
    let url = URL.createObjectURL(blob);
    recordedVideoRef.current.src = url;
  };

  return (
    <div className="App">
      <h1>Webcam Recorder</h1>
      <video ref={videoRef} autoPlay muted></video>
      <button onClick={recording ? handleStop : handleStart}>
        {recording ? 'Stop Recording' : 'Start Recording'}
      </button>
      <h2>Playback</h2>
      <video ref={recordedVideoRef} autoPlay controls></video>
      <button onClick={updateVideoPlayback}>Load Recorded Video</button>
    </div>
  );
}

export default App;

import React, { useRef, useState } from 'react';
import { useInterval } from 'usehooks-ts';

function App() {
  const [recording, setRecording] = useState(false);
  const [recordedChunks, setRecordedChunks] = useState([]);
  const [isPlaying, setPlaying] = useState(false);
  const recordedVideoRef = useRef();
  let mediaRecorder = useRef(null);

  const handleStart = async () => {
    const stream = await navigator.mediaDevices.getDisplayMedia({
      video: {
        cursor: 'always'
      },
      audio: false
    });

    mediaRecorder.current = new MediaRecorder(stream);
    mediaRecorder.current.ondataavailable = handleDataAvailable;
    mediaRecorder.current.start(100); // collect 100ms of data at a time
    setRecording(true);
    setPlaying(true);
  };

  const handleDataAvailable = (event) => {
    if (event.data && event.data.size > 0) {
      setRecordedChunks((prev) => [...prev, event.data]);
    }
  };

  const handleStop = () => {
    mediaRecorder.current.stop();
    mediaRecorder.current.stream.getTracks().forEach((track) => track.stop());
    setRecording(false);
    setPlaying(false);
  };

  useInterval(() => {
    let blob = new Blob(recordedChunks, { type: 'video/webm' });
    let url = URL.createObjectURL(blob);
    let currentTime = recordedVideoRef.current.currentTime;
    recordedVideoRef.current.src = url;
    recordedVideoRef.current.currentTime = currentTime;
  }, isPlaying ? 1000 : null);

  return (
    <div className="App">
      <h1>Screen Recorder</h1>
      <button onClick={recording ? handleStop : handleStart}>
        {recording ? 'Stop Recording' : 'Start Recording'}
      </button>
      <h2>Playback</h2>
      <video ref={recordedVideoRef} autoPlay controls></video>
    </div>
  );
}

export default App;

import React, { useRef, useState } from 'react';
import { useInterval } from 'usehooks-ts';

function App() {
  const [recording, setRecording] = useState(false);
  const [recordedChunks, setRecordedChunks] = useState([]);
  const [isPlaying, setPlaying] = useState(false);
  const recordedVideoRef1 = useRef();
  const recordedVideoRef2 = useRef();
  const hiddenVideoRef = useRef();
  let mediaRecorder = useRef(null);

  const handleStart = async () => {
    const stream = await navigator.mediaDevices.getDisplayMedia({
      video: {
        cursor: 'always'
      },
      audio: false
    });

    mediaRecorder.current = new MediaRecorder(stream);
    mediaRecorder.current.ondataavailable = handleDataAvailable;
    mediaRecorder.current.start(100); // collect 100ms of data at a time
    setRecording(true);
    setPlaying(true);
    hiddenVideoRef.current = recordedVideoRef2;
  };

  const handleDataAvailable = (event) => {
    if (event.data && event.data.size > 0) {
      setRecordedChunks((prev) => [...prev, event.data]);
    }
  };

  const handleStop = () => {
    mediaRecorder.current.stop();
    mediaRecorder.current.stream.getTracks().forEach((track) => track.stop());
    setRecording(false);
    setPlaying(false);
  };

  useInterval(() => {
    let blob = new Blob(recordedChunks, { type: 'video/webm' });
    let url = URL.createObjectURL(blob);
    let currentTime = hiddenVideoRef.current.currentTime;
    hiddenVideoRef.current.src = url;
    hiddenVideoRef.current.onloadedmetadata = () => {
      hiddenVideoRef.current.currentTime = currentTime;
      swapVideos();
    };
  }, isPlaying ? 1000 : null);

  const swapVideos = () => {
    let temp = recordedVideoRef1.current.src;
    recordedVideoRef1.current.src = recordedVideoRef2.current.src;
    recordedVideoRef2.current.src = temp;
    hiddenVideoRef.current = (hiddenVideoRef.current === recordedVideoRef1) ? recordedVideoRef2 : recordedVideoRef1;
  };

  return (
    <div className="App">
      <h1>Screen Recorder</h1>
      <button onClick={recording ? handleStop : handleStart}>
        {recording ? 'Stop Recording' : 'Start Recording'}
      </button>
      <h2>Playback</h2>
      <video ref={recordedVideoRef1} autoPlay controls style={{ display: 'none' }}></video>
      <video ref={recordedVideoRef2} autoPlay controls></video>
    </div>
  );
}

export default App;

