function biasedMultiplier() {
    $x = mt_rand(10, 100) / 10;  // Generate a random number between 1 and 10 with one decimal place
    $probability = 1 / $x;       // Calculate the probability inversely proportional to x
    $randomValue = mt_rand() / mt_getrandmax();

    if ($randomValue < $probability) {
        return $x;
    } else {
        return biasedMultiplier();  // Recursively call the function until a value is selected
    }
}

// Example usage
$result = biasedMultiplier();
echo $result;

