const viewer = new Cesium.Viewer("cesiumContainer", {
  shadows: true,
});
viewer.extend(Cesium.viewerCesium3DTilesInspectorMixin);

let totalCost = 0;
const boardCost = 10; // Set cost for a single board
const costOverlayElement = document.createElement('div');
costOverlayElement.style.position = 'absolute';
costOverlayElement.style.top = '10px';
costOverlayElement.style.left = '10px';
costOverlayElement.style.color = 'white';
document.body.appendChild(costOverlayElement);

// Function to add a new board to the scene.
function addBoard(worldPosition) {
  const board = viewer.entities.add({
    position: worldPosition,
    label: {
      text: '| 2x4 |', // Just to represent a board
      font: '20px sans-serif',
      heightReference: Cesium.HeightReference.RELATIVE_TO_GROUND
    }
  });

  // Increase the total cost.
  totalCost += boardCost;

  // Update the cost display.
  updateCostDisplay();
}

// Update the cost display.
function updateCostDisplay() {
  costOverlayElement.textContent = `Total Cost: $${totalCost}`;
}

const handler = new Cesium.ScreenSpaceEventHandler(viewer.canvas);

handler.setInputAction(function(movement) {
  const ray = viewer.camera.getPickRay(movement.position);
  const worldPosition = viewer.scene.globe.pick(ray, viewer.scene);

  if(Cesium.defined(worldPosition)) {
    addBoard(worldPosition);
  }
}, Cesium.ScreenSpaceEventType.LEFT_CLICK);

