import com.android.billingclient.api.*

class PlayBillingManager(private val billingClient: BillingClient) : PurchasesUpdatedListener {

    private lateinit var skuDetailsList: List<SkuDetails>

    fun startConnection() {
        billingClient.startConnection(object : BillingClientStateListener {
            override fun onBillingSetupFinished(result: BillingResult) {
                if (result.responseCode == BillingClient.BillingResponseCode.OK) {
                    // Billing client is ready
                    querySkuDetails()
                    queryPurchases()
                }
            }

            override fun onBillingServiceDisconnected() {
                // Try to restart the connection on the next request to the billing client
                startConnection()
            }
        })
    }

    private fun querySkuDetails() {
        val params = SkuDetailsParams.newBuilder()
            .setSkusList(listOf("product_id1", "product_id2"))
            .setType(BillingClient.SkuType.INAPP)
            .build()

        billingClient.querySkuDetailsAsync(params) { result, skuDetailsList ->
            if (result.responseCode == BillingClient.BillingResponseCode.OK && skuDetailsList != null) {
                this.skuDetailsList = skuDetailsList
            }
        }
    }

    private fun queryPurchases() {
        val purchasesResult = billingClient.queryPurchases(BillingClient.SkuType.INAPP)
        val purchasesList = purchasesResult.purchasesList

        if (purchasesList != null) {
            handlePurchases(purchasesList)
        }
    }

    private fun handlePurchases(purchasesList: List<Purchase>) {
        for (purchase in purchasesList) {
            // Process purchased items
            if (!purchase.isAcknowledged) {
                acknowledgePurchase(purchase)
            }
        }
    }

    private fun acknowledgePurchase(purchase: Purchase) {
        val acknowledgePurchaseParams = AcknowledgePurchaseParams.newBuilder()
            .setPurchaseToken(purchase.purchaseToken)
            .build()

        billingClient.acknowledgePurchase(acknowledgePurchaseParams) { billingResult ->
            if (billingResult.responseCode == BillingClient.BillingResponseCode.OK) {
                // Purchase acknowledged successfully
            }
        }
    }

    override fun onPurchasesUpdated(result: BillingResult, purchases: List<Purchase>?) {
        if (result.responseCode == BillingClient.BillingResponseCode.OK && purchases != null) {
            handlePurchases(purchases)
        }
    }
}

