        billingClient = BillingClient.newBuilder(activity)
            .setListener(this)
            .enablePendingPurchases()
            .build()

        billingClient?.startConnection(object : BillingClientStateListener {
            override fun onBillingSetupFinished(billingResult: BillingResult) {
                if (billingResult.responseCode == BillingClient.BillingResponseCode.OK) {
                    UnityPlayer.UnitySendMessage("PlayBillingManager", "OnBillingSetupSuccess", "")
                    querySkuDetails()
                } else {
                    UnityPlayer.UnitySendMessage(
                        "PlayBillingManager",
                        "OnBillingSetupFailed",
                        billingResult.responseCode.toString()
                    )
                }
            }

            override fun onBillingServiceDisconnected() {
                UnityPlayer.UnitySendMessage("PlayBillingManager", "OnBillingServiceDisconnected", "")
            }
        })
    }

    override fun onPurchasesUpdated(billingResult: BillingResult, purchases: List<Purchase>?) {
        if (billingResult.responseCode == BillingClient.BillingResponseCode.OK && purchases != null) {
            for (purchase in purchases) {
                handlePurchase(purchase)
            }
        } else {
            UnityPlayer.UnitySendMessage("PlayBillingManager", "OnPurchaseFailed", billingResult.responseCode.toString())
        }
    }

    fun purchaseProduct(productId: String, isSubscription: Boolean) {
        if (billingClient?.isReady == true) {
            val skuType = if (isSubscription) BillingClient.SkuType.SUBS else BillingClient.SkuType.INAPP
            val params = SkuDetailsParams.newBuilder()
                .setSkusList(listOf(productId))
                .setType(skuType)
                .build()
            billingClient?.querySkuDetailsAsync(params) { billingResult, skuDetailsList ->
                if (billingResult.responseCode == BillingClient.BillingResponseCode.OK && skuDetailsList != null) {
                    if (skuDetailsList.isNotEmpty()) {
                        val skuDetails = skuDetailsList[0]
                        if (skuDetails.type == skuType) {
                            if (isSubscription) {
                                startSubscription(skuDetails)
                            } else {
                                startPurchase(skuDetails)
                            }
                        } else {
                            UnityPlayer.UnitySendMessage("PlayBillingManager", "OnPurchaseFailed", "Invalid product type")
                        }
                    } else {
                        UnityPlayer.UnitySendMessage("PlayBillingManager", "OnPurchaseFailed", "Product not found")
                    }
                } else {
                    UnityPlayer.UnitySendMessage("PlayBillingManager", "OnPurchaseFailed", billingResult.responseCode.toString())
                }
            }
        }
    }

    private fun startPurchase(skuDetails: SkuDetails) {
        val billingFlowParams = BillingFlowParams.newBuilder()
            .setSkuDetails(skuDetails)
            .build()
        billingClient?.launchBillingFlow(activity, billingFlowParams)
    }

    private fun handlePurchase(purchase: Purchase) {
        if (purchase.purchaseState == Purchase.PurchaseState.PURCHASED) {
