import com.android.billingclient.api.BillingClient;
import com.android.billingclient.api.BillingClientStateListener;
import com.android.billingclient.api.BillingFlowParams;
import com.android.billingclient.api.BillingFlowParams.ProrationMode;
import com.android.billingclient.api.BillingResult;
import com.android.billingclient.api.ConsumeParams;
import com.android.billingclient.api.ConsumeResponseListener;
import com.android.billingclient.api.PriceChangeFlowParams;
import com.android.billingclient.api.PriceChangeFlowParams.Builder;
import com.android.billingclient.api.PriceChangeFlowParams.ProrationMode;
import com.android.billingclient.api.PriceChangeFlowParams.PriceChangeFlowListener;
import com.android.billingclient.api.PriceChangeFlowResult;
import com.android.billingclient.api.PriceChangeFlowResult.Builder;
import com.android.billingclient.api.PriceChangeFlowResult.ProrationMode;
import com.android.billingclient.api.Purchase;
import com.android.billingclient.api.PurchasesUpdatedListener;
import com.android.billingclient.api.SkuDetails;
import com.android.billingclient.api.SkuDetailsParams;
import com.android.billingclient.api.SkuDetailsResponseListener;
import com.unity3d.player.UnityPlayer;
import com.unity3d.player.UnityPlayerActivity;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class PlayBillingPluginForUnity extends UnityPlayerActivity implements PurchasesUpdatedListener {
    private BillingClient billingClient;
    private Activity unityActivity;
    private List<String> productIds;

    public PlayBillingPluginForUnity() {
        productIds = new ArrayList<>();
    }

    public void initializeBilling(String[] productIds) {
        this.productIds.addAll(Arrays.asList(productIds));
        unityActivity = this;

        // Initialize the BillingClient
        billingClient = BillingClient.newBuilder(this)
                .setListener(this)
                .enablePendingPurchases()
                .build();
        billingClient.startConnection(new BillingClientStateListener() {
            @Override
            public void onBillingSetupFinished(BillingResult billingResult) {
                // Check if billing setup was successful
                if (billingResult.getResponseCode() == BillingClient.BillingResponseCode.OK) {
                    // BillingClient is ready, perform any necessary operations
                    UnityPlayer.UnitySendMessage("YourScriptGameObject", "OnBillingSetupFinished", "");
                } else {
                    UnityPlayer.UnitySendMessage("YourScriptGameObject", "OnBillingSetupFailed", "");
                }
            }

            @Override
            public void onBillingServiceDisconnected() {
                UnityPlayer.UnitySendMessage("YourScriptGameObject", "OnBillingServiceDisconnected", "");
            }
        });
    }

    public void queryProductDetails() {
        SkuDetailsParams.Builder paramsBuilder = SkuDetailsParams.newBuilder();
        paramsBuilder.setSkusList(productIds).setType(BillingClient.SkuType.INAPP);

        billingClient.querySkuDetailsAsync(paramsBuilder.build(), new SkuDetailsResponseListener() {
            @Override
            public void onSkuDetailsResponse(BillingResult billingResult, List<SkuDetails> skuDetailsList) {
                if (billingResult.getResponseCode() == BillingClient.BillingResponseCode.OK && skuDetailsList != null) {
                    List<String> skuDetailsJsonList = new ArrayList<>();
                    for (SkuDetails skuDetails : skuDetailsList) {
                        skuDetailsJsonList.add(skuDetails.toJson());
                    }
                    UnityPlayer.UnitySendMessage("YourScriptGameObject", "OnProductDetailsReceived", TextUtils.join(",", skuDetailsJsonList));
                } else {
                    UnityPlayer.UnitySendMessage("YourScriptGameObject", "OnProductDetailsFailed", "");
                }
            }
        });
    }

    public void purchaseProduct(String productId) {
        if (productIds.contains(productId)) {
            BillingFlowParams flowParams = BillingFlowParams.newBuilder()
                    .setSkuDetails(SkuDetails.newBuilder().setSku(productId).setType(BillingClient.SkuType.INAPP).build())
                    .build();
            billingClient.launchBillingFlow(unityActivity, flowParams);
        } else {
            UnityPlayer.UnitySendMessage("YourScriptGameObject", "OnPurchaseProductFailed", "");
        }
    }

    public void acknowledgePurchase(String purchaseToken) {
        AcknowledgePurchaseParams acknowledgeParams = AcknowledgePurchaseParams.newBuilder()
                .setPurchaseToken(purchaseToken)
                .build();

        billingClient.acknowledgePurchase(acknowledgeParams, new AcknowledgePurchaseResponseListener() {
            @Override
            public void onAcknowledgePurchaseResponse(BillingResult billingResult) {
                if (billingResult.getResponseCode() == BillingClient.BillingResponseCode.OK) {
                    UnityPlayer.UnitySendMessage("YourScriptGameObject", "OnAcknowledgeResult", "ACKNOWLEDGE_SUCCESS");
                } else {
                    UnityPlayer.UnitySendMessage("YourScriptGameObject", "OnAcknowledgeResult", "ACKNOWLEDGE_FAILURE");
                }
            }
        });
    }

    public void consumePurchase(String purchaseToken) {
        ConsumeParams consumeParams = ConsumeParams.newBuilder()
                .setPurchaseToken(purchaseToken)
                .build();

        billingClient.consumeAsync(consumeParams, new ConsumeResponseListener() {
            @Override
            public void onConsumeResponse(BillingResult billingResult, String purchaseToken) {
                if (billingResult.getResponseCode() == BillingClient.BillingResponseCode.OK) {
                    UnityPlayer.UnitySendMessage("YourScriptGameObject", "OnConsumeResult", "CONSUME_SUCCESS");
                } else {
                    UnityPlayer.UnitySendMessage("YourScriptGameObject", "OnConsumeResult", "CONSUME_FAILURE");
                }
            }
        });
    }

    public void changeSubscriptionPlan(String oldSku, String newSku) {
        PriceChangeFlowParams priceChangeParams = new PriceChangeFlowParams.Builder()
                .setOldSku(oldSku)
                .setNewSku(newSku)
                .build();

        billingClient.launchPriceChangeConfirmationFlow(unityActivity, priceChangeParams,
                new PriceChangeFlowParams.PriceChangeFlowListener() {
                    @Override
                    public void onPriceChangeConfirmationResult(PriceChangeFlowParams priceChangeParams, BillingResult billingResult) {
                        if (billingResult.getResponseCode() == BillingClient.BillingResponseCode.OK) {
                            UnityPlayer.UnitySendMessage("YourScriptGameObject", "OnChangeSubscriptionPlanResult", "SUCCESS");
                        } else {
                            UnityPlayer.UnitySendMessage("YourScriptGameObject", "OnChangeSubscriptionPlanResult", "FAILURE");
                        }
                    }
                });
    }

    @Override
    public void onPurchasesUpdated(BillingResult billingResult, List<Purchase> purchases) {
        if (billingResult.getResponseCode() == BillingClient.BillingResponseCode.OK && purchases != null) {
            for (Purchase purchase : purchases) {
                String purchaseToken = purchase.getPurchaseToken();
                UnityPlayer.UnitySendMessage("YourScriptGameObject", "OnPurchaseUpdated", purchaseToken);
            }
        } else {
            UnityPlayer.UnitySendMessage("YourScriptGameObject", "OnPurchaseUpdateFailed", "");
        }
    }
}

using UnityEngine;
using System.Runtime.InteropServices;

public class AndroidBridge : MonoBehaviour
{
    public static AndroidBridge Instance { get; private set; }

    // DllImport to link the native methods from the Java class
    [DllImport("PlayBillingPluginForUnity")]
    private static extern void initializeBilling(string[] productIds);

    [DllImport("PlayBillingPluginForUnity")]
    private static extern void queryProductDetails();

    [DllImport("PlayBillingPluginForUnity")]
    private static extern void purchaseProduct(string productId);

    [DllImport("PlayBillingPluginForUnity")]
    private static extern void acknowledgePurchase(string purchaseToken);

    [DllImport("PlayBillingPluginForUnity")]
    private static extern void consumePurchase(string purchaseToken);

    [DllImport("PlayBillingPluginForUnity")]
    private static extern void changeSubscriptionPlan(string oldSku, string newSku);

    // Callback functions that will be called from the native Android code
    public void OnBillingSetupFinished()
    {
        Debug.Log("Billing setup finished.");
    }

    public void OnBillingSetupFailed()
    {
        Debug.Log("Billing setup failed.");
    }

    public void OnBillingServiceDisconnected()
    {
        Debug.Log("Billing service disconnected.");
    }

    public void OnProductDetailsReceived(string skuDetailsJson)
    {
        Debug.Log("Product details received: " + skuDetailsJson);
    }

    public void OnProductDetailsFailed()
    {
        Debug.Log("Failed to retrieve product details.");
    }

    public void OnPurchaseProductFailed()
    {
        Debug.Log("Failed to purchase product.");
    }

    public void OnAcknowledgeResult(string result)
    {
        Debug.Log("Acknowledge result: " + result);
    }

    public void OnConsumeResult(string result)
    {
        Debug.Log("Consume result: " + result);
    }

    public void OnChangeSubscriptionPlanResult(string result)
    {
        Debug.Log("Change subscription plan result: " + result);
    }

    public void OnPurchaseUpdated(string purchaseToken)
    {
        Debug.Log("Purchase updated: " + purchaseToken);
    }

    public void OnPurchaseUpdateFailed()
    {
        Debug.Log("Failed to update purchase.");
    }

    private void Awake()
    {
        // Set the static instance
        if (Instance == null)
        {
            Instance = this;
        }
        else
        {
            Destroy(gameObject);
        }
    }

    // Example usage
    private void Start()
    {
        // Initialize the billing system with product IDs
        string[] productIds = { "your_product_id_1", "your_product_id_2" };
        initializeBilling(productIds);
    }

    public void QueryProductDetails()
    {
        // Query product details
        queryProductDetails();
    }

    public void PurchaseProduct(string productId)
    {
        // Purchase a product
        purchaseProduct(productId);
    }

    public void AcknowledgePurchase(string purchaseToken)
    {
        // Acknowledge a purchase
        acknowledgePurchase(purchaseToken);
    }

    public void ConsumePurchase(string purchaseToken)
    {
        // Consume a purchase
        consumePurchase(purchaseToken);
    }

    public void ChangeSubscriptionPlan(string oldSku, string newSku)
    {
        // Change subscription plan
        changeSubscriptionPlan(oldSku, newSku);
    }
}

