import SwiftUI

struct ContentView: View {
    // SwiftUI does not have an equivalent of `init()` as in UIKit. 
    // However, you can initialize state variables in a SwiftUI struct.
    @State private var text: String = "Hello, world!"

    var body: some View {
        Text(text)
            // `loadView()`, `loadViewIfNeeded()` don't have an equivalent in SwiftUI.
            // `viewDidLoad()` equivalent, perform any setup here.
            .onAppear(perform: {
                print("Same as method viewDidLoad in UIKit")
            })
            // There isn't a direct equivalent for `viewWillAppear(_:)`, 
            // but `.onAppear` can be used to perform actions just as the view is about to appear.
            .onAppear(perform: {
                print("Same as method viewWillAppear(_:) in UIKit")
            })
            // `viewWillLayoutSubviews()`, `viewDidLayoutSubviews()` don't have an equivalent in SwiftUI.
            // SwiftUI handles the layout of views and you don't need to manually layout subviews.

            // `viewDidAppear(_:)` equivalent
            .onAppear(perform: {
                print("Same as method viewDidAppear(_:) in UIKit")
            })
            // `viewWillDisappear(_:)` equivalent
            .onDisappear(perform: {
                print("Same as method viewWillDisappear(_:) in UIKit")
            })
            // `viewDidDisappear(_:)` equivalent
            .onDisappear(perform: {
                print("Same as method viewDidDisappear(_:) in UIKit")
            })
            // `viewDidUnLoad()` doesn't have an equivalent in SwiftUI as SwiftUI handles view unloading.
    }
}

