class PostListViewModel: ObservableObject {
    @Published var posts: [Post] = []
    @Published var state: ViewState = .loading

    private var repository: Repository

    init(repository: ApiRepository = ApiRepository()) {
        self.repository = repository
    }

    func fetchPosts() async {
        do {
            self.state = .loading
            let contents = try await self.repository.fetchPostList()
            if contents.isEmpty {
                self.state = .loading
            } else {
                self.state = .loaded
                self.posts = contents
            }
        } catch {
            self.state = .error
        }
    }
}

protocol Keyable {       
    var keystring: String {get}
    func hashValue(for key: String!, using buckets: Array<T>) -> Int 
}

extension Keyable {
    //compute item hash
    func hashValue<T>(for key: String!, using buckets: Array<T>) -> Int {
        var remainder: Int = 0
        var divisor: Int = 0

        //trivial case
        guard key != nil else {
            return -1
        }        
        for item in key.unicodeScalars {
            divisor += Int(item.value)
        }        
        remainder = divisor % buckets.count        
        return remainder
    }        
}

