// Protocol with an associated type
protocol Networking {
    associatedtype Request: URLRequestConvertible

    func request(_ request: Request) async throws -> Data
}

// Type erasure for the Networking protocol
struct AnyNetworking<R: URLRequestConvertible>: Networking {
    private let _request: (R) async throws -> Data

    init<N: Networking>(_ networking: N) where N.Request == R {
        _request = networking.request
    }

    func request(_ request: R) async throws -> Data {
        return try await _request(request)
    }
}

// The PostApiRepository class using the type erased Networking
class PostApiRepository: PostRepository {
    private let networkService: AnyNetworking<PostRequest>

    init<N: Networking>(networkService: N) where N.Request == PostRequest {
        self.networkService = AnyNetworking(networkService)
    }

    func fetchPosts() async throws -> [Post] {
        let request = PostRequest()
        let data = try await networkService.request(request)
        // Decode your data into [Post] here
        // This is just an example, replace with your actual decoding logic
        return try JSONDecoder().decode([Post].self, from: data)
    }
}

