export interface BaseOptions {
  network: Chain;
  signer?: Signer | string;
}

export type StarOptions = BaseOptions & {
  star: string;
}

export type ConstellationOptions = BaseOptions & {
  constellation: string;
}

export type EitherOptions = StarOptions | ConstellationOptions;

export interface BaseOptions {
  network: Chain;
  signer?: Signer | string;
}

export interface StarOrConstellation {
  star?: string;
  constellation?: string;
}

type AtLeastOne<T, U = { [K in keyof T]: Pick<T, K> }> = Partial<T> & U[keyof U];

export type SDKOptions = BaseOptions & AtLeastOne<StarOrConstellation>;

type AtLeastOne<T, Keys extends keyof T = keyof T> =
  Pick<T, Exclude<Keys, keyof {
    [K in Keys]: (Record<K, T[K]> extends Record<Keys, unknown> ? K : never)
  }[Keys]>> & {
    [K in keyof {
      [K in Keys]: (Record<K, T[K]> extends Record<Keys, unknown> ? never : K)
    }[Keys]]?: T[K]
  }

export interface SDKOptions {
  network: Chain;
  signer?: Signer | string;
}

type StarOrConstellation = AtLeastOne<{
  star: string;
  constellation: string;
}>;

export type CompleteSDKOptions = SDKOptions & StarOrConstellation;

