// Original function that calculates the average of an array.
function computeAverage(numbers) {
  if (!Array.isArray(numbers) || numbers.length === 0) {
    throw new Error('Input must be a non-empty array.');
  }

  const sum = numbers.reduce((a, b) => a + b, 0);
  return sum / numbers.length;
}

// Wrap the function with Mixpanel tracking and Sentry error capturing.
const computeAverageWithTracking = withTrackingAndErrorHandling("Compute Average Event", computeAverage);

// Usage
try {
  const average = computeAverageWithTracking([1, 2, 3, 4, 5]);
  console.log(`The average is ${average}`);
} catch (error) {
  console.error(`An error occurred: ${error.message}`);
}

