class HMTime {
  final int hour;
  final int minute;

  DateTime toDateTime(DateTime? dayBase) => DateTime(0, 1, 1, hour, minute);

  const HMTime(this.hour, this.minute);

  HMTime.withString(String hour, String minute)
      : hour = int.parse(hour),
        minute = int.parse(minute);
}

class HMTime {
  final int hour;
  final int minute;

  DateTime toDateTime(DateTime? dayBase) => DateTime(0, 1, 1, hour, minute);

  const HMTime(this.hour, this.minute);

  HMTime.withString(String hour, String minute)
      : hour = int.parse(hour),
        minute = int.parse(minute);

  HMTime.fromString(String timeString)
      : hour = int.parse(timeString.split(':')[0]),
        minute = int.parse(timeString.split(':')[1]);
}

