const startCountdown = (inputTime: string): void => {
  const [hours, minutes, seconds] = inputTime.split(':').map(Number);
  const totalSeconds: number = hours * 3600 + minutes * 60 + seconds;

  const countdown = setInterval(() => {
    const [h, m, s]: number[] = [Math.floor(totalSeconds / 3600), Math.floor((totalSeconds % 3600) / 60), totalSeconds % 60];
    console.log(`${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`);
    if (totalSeconds-- <= 0) {
      clearInterval(countdown);
      console.log('Countdown finished!');
    }
  }, 1000);
};

// Usage example
startCountdown('01:59:59');

const startCountdown = (inputTime: string): void => {
  let totalSeconds: number = getTimeInSeconds(inputTime);

  const countdown = setInterval(() => {
    const [hours, minutes, seconds] = getTimeComponents(totalSeconds);
    console.log(`${formatTimeComponent(hours)}:${formatTimeComponent(minutes)}:${formatTimeComponent(seconds)}`);
    if (--totalSeconds < 0) {
      clearInterval(countdown);
      console.log('Countdown finished!');
    }
  }, 1000);

  const getTimeInSeconds = (time: string): number => time.split(':').reduce((acc, curr, index) => acc + parseInt(curr) * Math.pow(60, 2 - index), 0);
  const getTimeComponents = (totalSeconds: number): number[] => [Math.floor(totalSeconds / 3600), Math.floor((totalSeconds % 3600) / 60), totalSeconds % 60];
  const formatTimeComponent = (component: number): string => component.toString().padStart(2, '0');
};

// Usage example
startCountdown('01:59:59');

