    });
    std::string statementResult = statement(invoice, playData);
    std::string expectedStatement = "Statement for Customer C\n  Hamlet: $400.00 (20 seats)\n  As You Like It: $620.00 (40 seats)\n  Othello: $400.00 (15 seats)\nAmount owed is $1,420.00\nYou earned 18 credits\n";
    EXPECT_EQ(statementResult, expectedStatement);
}

