import tar from 'tar';
import { promises as fsPromises } from 'fs';

const { rename, readdir, rmdir } = fsPromises;

// ... your existing code ...

pipelineAsync(response, createGunzip(), writeStream)
    .then(async () => {
        // Extract the tar.gz here
        await tar.x({
            file: path.join(dest, 'node.tar.gz'),
            cwd: dest
        });

        // Find the directory that was extracted (should be named something like node-v18.17.1-darwin-arm64)
        const directories = (await readdir(dest)).filter(d => fs.statSync(path.join(dest, d)).isDirectory());
        const extractedDirName = directories[0];  // Assuming only one directory after extraction
        const extractedDirPath = path.join(dest, extractedDirName);

        // Rename the directory to just the version number
        const newDirName = version;
        const newDirPath = path.join(dest, newDirName);
        await rename(extractedDirPath, newDirPath);

        // Move the contents one level up
        const contentFiles = await readdir(newDirPath);
        for (const file of contentFiles) {
            await rename(path.join(newDirPath, file), path.join(dest, file));
        }

        // Remove the now-empty directory
        await rmdir(newDirPath);

        // Set the version as active
        resolve();
    })
    .catch(reject);

