        _Metallic("Metallic", Range(0,1)) = 0.0
        _FresnelPower("Fresnel Power", Range(1,5)) = 2.0
        _FresnelIntensity("Fresnel Intensity", Range(0,1)) = 0.6
        // Gerstner Wave Properties...
        // (same as before)
    }

    SubShader
    {
        Tags { "RenderType" = "Transparent" "Queue" = "Transparent"}
        LOD 200

        CGPROGRAM
        #pragma surface surf Standard fullforwardshadows
        #pragma target 3.0

        sampler2D _MainTex;
        // Variables...
        // (same as before)

        fixed2 GerstnerWave(fixed2 position, fixed2 direction, half amplitude, half frequency, half phase, half speed)
        {
            fixed2 result;
            float wave = _Time.y * speed + frequency * dot(direction, position) + phase + sin(_Time.y);
            result.x = direction.x * amplitude * sin(wave);
            result.y = amplitude * cos(wave);
            return result;
        }

        void surf(Input IN, inout SurfaceOutputStandard o)
        {
            // Adjust the speed and phase over time using the _Time.y component
            half dynamicSpeed1 = _Speed1 + sin(_Time.y) * 0.1;
            half dynamicPhase1 = _Phase1 + cos(_Time.y) * 0.1;

            half dynamicSpeed2 = _Speed2 + sin(_Time.y * 1.1) * 0.1;
            half dynamicPhase2 = _Phase2 + cos(_Time.y * 1.1) * 0.1;

            half dynamicSpeed3 = _Speed3 + sin(_Time.y * 1.2) * 0.1;
            half dynamicPhase3 = _Phase3 + cos(_Time.y * 1.2) * 0.1;

            half dynamicSpeed4 = _Speed4 + sin(_Time.y * 1.3) * 0.1;
            half dynamicPhase4 = _Phase4 + cos(_Time.y * 1.3) * 0.1;

            half dynamicSpeed5 = _Speed5 + sin(_Time.y * 1.4) * 0.1;
            half dynamicPhase5 = _Phase5 + cos(_Time.y * 1.4) * 0.1;

            // Use the dynamic speed and phase in the GerstnerWave calculations
            fixed3 finalWavePosition = IN.worldPos;
            finalWavePosition.xy += GerstnerWave(IN.worldPos.xz, float2(1, 0.5), _Amplitude1, _Frequency1, dynamicPhase1, dynamicSpeed1);
            finalWavePosition.xy += GerstnerWave(IN.worldPos.xz, float2(0.7, 1.3), _Amplitude2, _Frequency2, dynamicPhase2, dynamicSpeed2);
            finalWavePosition.xy += GerstnerWave(IN.worldPos.xz, float2(-0.6, 0.8), _Amplitude3, _Frequency3, dynamicPhase3, dynamicSpeed3);
            finalWavePosition.xy += GerstnerWave(IN.worldPos.xz, float2(0.9, -0.5), _Amplitude4, _Frequency4, dynamicPhase4, dynamicSpeed4);
            finalWavePosition.xy += GerstnerWave(IN.worldPos.xz, float2(-0.8, -0.6), _Amplitude5, _Frequency5, dynamicPhase5, dynamicSpeed5);

            // Rest of the surf function...
            // (same as before)
        }
        ENDCG
    }
    FallBack "Diffuse"
}

Shader "Custom/Water Shader"
{
    Properties
    {
        // ... [All your properties remain the same]

    }
    SubShader
    {
        Tags { "RenderType" = "Transparent" "Queue" = "Transparent"}
        LOD 200

        CGPROGRAM
        #pragma surface surf Standard fullforwardshadows
        #pragma target 3.0

        sampler2D _MainTex;

        struct Input
        {
            float2 uv_MainTex;
            float3 worldPos;
            float3 viewDir;
        };

        // ... [All your wave properties remain the same]

        fixed2 GerstnerWave(fixed2 position, fixed2 direction, half amplitude, half frequency, half phase, half speed)
        {
            fixed2 result;
            float wave = _Time.y * speed + frequency * dot(direction, position) + phase;
            result.x = direction.x * amplitude * sin(wave);
            result.y = amplitude * cos(wave);
            return result;
        }

        fixed2 EnhancedUV(fixed2 uv, fixed3 worldPos)
        {
            fixed2 distortion = float2(0, 0);

            distortion += GerstnerWave(worldPos.xz, float2(1, 0.5) * sin(_Time.y * 0.25), _Amplitude1, _Frequency1, _Phase1, _Speed1);
            distortion += GerstnerWave(worldPos.xz, float2(0.7, 1.3) * sin(_Time.y * 0.35), _Amplitude2, _Frequency2, _Phase2, _Speed2);

            distortion.x += sin(worldPos.x + _Time.y * _WaveSpeed) * 0.02;
            distortion.y += cos(worldPos.z + _Time.y * _WaveSpeed) * 0.02;

            return uv + distortion * 0.01;
        }

        fixed3 ComputeNormal(fixed3 worldPos)
        {
            fixed2 waveOffset1 = GerstnerWave(worldPos.xz, float2(1, 0.5) * sin(_Time.y * 0.2), _Amplitude1, _Frequency1, _Phase1, _Speed1);
            fixed2 waveOffset2 = GerstnerWave(worldPos.xz, float2(0.7, 1.3) * sin(_Time.y * 0.3), _Amplitude2, _Frequency2, _Phase2, _Speed2);
            fixed2 waveOffset3 = GerstnerWave(worldPos.xz, float2(-0.6, 0.8) * sin(_Time.y * 0.4), _Amplitude3, _Frequency3, _Phase3, _Speed3);

            fixed3 normal;
            normal.x = waveOffset1.x + waveOffset2.x + waveOffset3.x;
            normal.y = 1;
            normal.z = waveOffset1.y + waveOffset2.y + waveOffset3.y;

            return normalize(normal);
        }

        void surf (Input IN, inout SurfaceOutputStandard o)
        {
            fixed2 uv = EnhancedUV(IN.uv_MainTex, IN.worldPos);
            fixed4 c = tex2D(_MainTex, uv) * _Color;
            half fresnel = pow(1.0 - dot(normalize(IN.viewDir), ComputeNormal(IN.worldPos)), _FresnelPower);

            o.Albedo = lerp(c.rgb, _Color.rgb * _FresnelIntensity, fresnel);
            o.Metallic = _Metallic;
            o.Smoothness = _Glossiness;
            o.Alpha = c.a;
            o.Normal = ComputeNormal(IN.worldPos);
        }
        ENDCG
    }
    FallBack "Diffuse"
}

fixed3 ComputeNormal(fixed3 worldPos)
{
    fixed2 waveOffset1 = GerstnerWave(worldPos.xz, float2(1, 0.5) * sin(_Time.y * 0.2), _Amplitude1, _Frequency1, _Phase1, _Speed1);
    fixed2 waveOffset2 = GerstnerWave(worldPos.xz, float2(0.7, 1.3) * sin(_Time.y * 0.3), _Amplitude2, _Frequency2, _Phase2, _Speed2);
    fixed2 waveOffset3 = GerstnerWave(worldPos.xz, float2(-0.6, 0.8) * sin(_Time.y * 0.4), _Amplitude3, _Frequency3, _Phase3, _Speed3);
    fixed2 waveOffset4 = GerstnerWave(worldPos.xz, float2(0.9, -0.5) * sin(_Time.y * 0.5), _Amplitude4, _Frequency4, _Phase4, _Speed4);
    fixed2 waveOffset5 = GerstnerWave(worldPos.xz, float2(-0.8, -0.6) * sin(_Time.y * 0.6), _Amplitude5, _Frequency5, _Phase5, _Speed5);

    fixed3 normal;
    normal.x = waveOffset1.x + waveOffset2.x + waveOffset3.x + waveOffset4.x + waveOffset5.x;
    normal.y = 1;
    normal.z = waveOffset1.y + waveOffset2.y + waveOffset3.y + waveOffset4.y + waveOffset5.y;

    return normalize(normal);
}

fixed3 ComputeNormal(fixed3 worldPos)
{
    fixed2 waveOffset1 = GerstnerWave(worldPos.xz, float2(1, 0.5) * sin(_Time.y * 0.2), _Amplitude1, _Frequency1, _Phase1, _Speed1);
    fixed2 waveOffset2 = GerstnerWave(worldPos.xz, float2(0.7, 1.3) * sin(_Time.y * 0.3), _Amplitude2, _Frequency2, _Phase2, _Speed2);
    fixed2 waveOffset3 = GerstnerWave(worldPos.xz, float2(-0.6, 0.8) * sin(_Time.y * 0.4), _Amplitude3, _Frequency3, _Phase3, _Speed3);
    fixed2 waveOffset4 = GerstnerWave(worldPos.xz, float2(0.9, -0.5) * sin(_Time.y * 0.5), _Amplitude4, _Frequency4, _Phase4, _Speed4);
    fixed2 waveOffset5 = GerstnerWave(worldPos.xz, float2(-0.8, -0.6) * sin(_Time.y * 0.6), _Amplitude5, _Frequency5, _Phase5, _Speed5);

    fixed3 normal;
    normal.x = waveOffset1.x + waveOffset2.x + waveOffset3.x + waveOffset4.x + waveOffset5.x;
    normal.y = 1;
    normal.z = waveOffset1.y + waveOffset2.y + waveOffset3.y + waveOffset4.y + waveOffset5.y;

    return normalize(normal);
}

fixed3 RimLighting(float3 viewDir, float3 normal)
{
    half rim = 1.0 - saturate(dot(normalize(viewDir), normal));
    rim = _RimIntensity * pow(rim, _RimPower);
    return rim * _RimColor.rgb;
}

fixed2 AdjustedWave(fixed2 position, fixed2 direction, half amplitude, half frequency, half phase, half speed, fixed2 otherDirections[4], half otherAmplitudes[4])
{
    half totalAmplitude = amplitude;

    for (int i = 0; i < 4; i++)
    {
        half dotResult = dot(normalize(direction), normalize(otherDirections[i]));
        totalAmplitude += (dotResult > 0) ? otherAmplitudes[i] * dotResult : -otherAmplitudes[i] * dotResult;
    }

    return GerstnerWave(position, direction, totalAmplitude, frequency, phase, speed);
}

Shader "Custom/Water Shader"
{
    // Start defining the shader properties
    Properties
    {
        // Basic properties
        _Color ("Color", Color) = (1,1,1,1)                  // Base color of the water
        _MainTex ("Albedo (RGB)", 2D) = "white" {}           // Main texture, e.g. could be a normal map or simple albedo texture
        _Glossiness ("Smoothness", Range(0,1)) = 0.5         // Surface glossiness
        _Metallic ("Metallic", Range(0,1)) = 0.0             // Metallic property of the water
        _WaveHeight("Wave Height", Range(0,1)) = 0.1         // Controls the height of the waves, used for minor wave distortions
        _WaveSpeed("Wave Speed", Range(0,2)) = 1.0           // Controls the speed of the minor wave distortions
        _FresnelPower("Fresnel Power", Range(1,5)) = 2.0     // Power for fresnel effect. Controls how the light refracts based on the angle of view
        _FresnelIntensity("Fresnel Intensity", Range(0,1)) = 0.6 // Intensity of the fresnel effect

        // Rim lighting properties to simulate the edge brightness of the water
        _RimColor("Rim Color", Color) = (1, 1, 1, 1)         // Color of the rim lighting
        _RimIntensity("Rim Intensity", Range(0,1)) = 0.5     // Intensity of the rim lighting
        _RimPower("Rim Power", Range(1,6)) = 3.0             // Power for rim lighting, controlling its falloff

        // Gerstner Wave properties for each of the five waves
        // Here, you define properties like amplitude, frequency, phase, and speed for each wave to control its appearance
        // [for each wave, the properties are defined similarly]

    }

    SubShader
    {
        // Define rendering tags
        Tags { "RenderType" = "Transparent" "Queue" = "Transparent"} // This shader is transparent, which affects rendering order
        LOD 200  // Level of Detail: how detailed the shader should be rendered. Lower numbers mean less detail.

        // Begin Compute Graphics Program (CGPROGRAM)
        CGPROGRAM
        #pragma surface surf Standard fullforwardshadows  // Surface shader with standard lighting and shadows
        #pragma target 3.0  // Target shader model 3.0, which determines the kind of instructions and optimizations the shader compiler uses

        sampler2D _MainTex; // Sampler for the main texture

        struct Input
        {
            float2 uv_MainTex;   // UV coordinates for the main texture
            float3 worldPos;     // World position of the current pixel
            float3 viewDir;      // Direction from the current pixel to the camera
        };

        // Define shader properties
        half _Glossiness;
        half _Metallic;
        fixed4 _Color;
        half _WaveHeight;
        half _WaveSpeed;
        half _FresnelPower;
        half _FresnelIntensity;
        fixed4 _RimColor;
        half _RimIntensity;
        half _RimPower;

        // [similar definitions for Gerstner wave properties...]

        // Define Gerstner Wave Function
        fixed2 GerstnerWave(fixed2 position, fixed2 direction, half amplitude, half frequency, half phase, half speed)
        {
            fixed2 result;
            // Calculate the current position of the wave based on time, direction, and frequency
            float wave = _Time.y * speed + frequency * dot(direction, position) + phase;
            result.x = direction.x * amplitude * sin(wave);  // Calculate the X distortion based on wave calculation
            result.y = amplitude * cos(wave);  // Calculate the Y distortion
            return result;  // Return the combined distortion
        }

        // Function to compute the rim lighting effect
        fixed3 RimLighting(float3 viewDir, float3 normal)
        {
            half rim = 1.0 - saturate(dot(normalize(viewDir), normal));  // Compute the rim value based on the angle between view direction and surface normal
            rim = _RimIntensity * pow(rim, _RimPower);  // Apply the intensity and power to the rim value
            return rim * _RimColor.rgb;  // Return the color of the rim lighting
        }

        // Function to adjust the Gerstner wave based on the interaction between two waves
        fixed2 AdjustedWave(fixed2 position, fixed2 direction1, fixed2 direction2, half amplitude1, half amplitude2, half frequency1, half phase1, half speed1)
        {
            // Compute how much the two wave directions align (between -1 and 1)
            half dotResult = dot(normalize(direction1), normalize(direction2));
            // Adjust the amplitude based on how much the directions align
            amplitude1 += (dotResult > 0) ? amplitude2 * dotResult : -amplitude2 * dotResult;
            return GerstnerWave(position, direction1, amplitude1, frequency1, phase1, speed1); // Return the adjusted wave
        }

        // Function to combine multiple wave effects for the UV coordinates
        fixed2 EnhancedUV(fixed2 uv, fixed3 worldPos)
        {
            fixed2 distortion = float2(0, 0);
            distortion += AdjustedWave(worldPos.xz, ...); // Adjust the UV using the first two waves
            distortion += AdjustedWave(worldPos.xz, ...); // Adjust the UV using the second and first waves
            distortion.x += ...; // Add minor wave distortions
            distortion.y += ...; // Add minor wave distortions
            return uv + distortion * 0.01; // Combine the distortions with the base UV
        }

        // Main surface shader function
        void surf (Input IN, inout SurfaceOutput o)
        {
            fixed3 worldNormal = normalize(IN.worldPos);  // Calculate the world normal based on world position
            fixed2 uv = EnhancedUV(IN.uv_MainTex, IN.worldPos);  // Adjust the UV coordinates using the EnhancedUV function
            fixed4 c = tex2D(_MainTex, uv) * _Color;  // Sample the texture using the adjusted UV coordinates and multiply by base color

            o.Albedo = c.rgb;  // Set the albedo to the sampled color
            o.Metallic = _Metallic;  // Set the metallic property
            o.Smoothness = _Glossiness;  // Set the glossiness

            // Fresnel effect
            float fresnelEffect = _FresnelIntensity * pow(1.0 + dot(worldNormal, normalize(IN.viewDir)), _FresnelPower); // Compute fresnel based on angle between world normal and view direction
            o.Emission += fresnelEffect * _Color.rgb;  // Add fresnel effect to the emission channel

            o.Emission += RimLighting(IN.viewDir, worldNormal);  // Add rim lighting effect to the emission channel
        }

        ENDCG  // End the Compute Graphics Program
    }
    FallBack "Diffuse"  // Fallback to a simple diffuse shader if the custom shader doesn't work
}

Shader "Custom/Water Shader"
{
    Properties
    {
        _Color ("Color", Color) = (1,1,1,1)
        _MainTex ("Albedo (RGB)", 2D) = "white" {}
        _Glossiness ("Smoothness", Range(0,1)) = 0.5
        _Metallic ("Metallic", Range(0,1)) = 0.0
        _WaveHeight("Wave Height", Range(0,1)) = 0.1
        _WaveSpeed("Wave Speed", Range(0,2)) = 1.0
        _FresnelPower("Fresnel Power", Range(1,5)) = 2.0
        _FresnelIntensity("Fresnel Intensity", Range(0,1)) = 0.6
        _RimColor("Rim Color", Color) = (1, 1, 1, 1)
        _RimIntensity("Rim Intensity", Range(0,1)) = 0.5
        _RimPower("Rim Power", Range(1,6)) = 3.0
        _Amplitude1("Wave 1 Amplitude", Range(0, 2)) = 0.5
        _Frequency1("Wave 1 Frequency", Range(0, 5)) = 2.0
        _Phase1("Wave 1 Phase", Range(0, 6.28)) = 1.0
        _Speed1("Wave 1 Speed", Range(0, 2)) = 1.2
        _Amplitude2("Wave 2 Amplitude", Range(0, 2)) = 0.35
        _Frequency2("Wave 2 Frequency", Range(0, 5)) = 2.5
        _Phase2("Wave 2 Phase", Range(0, 6.28)) = 2.0
        _Speed2("Wave 2 Speed", Range(0, 2)) = 1.3
        _Amplitude3("Wave 3 Amplitude", Range(0, 2)) = 0.45
        _Frequency3("Wave 3 Frequency", Range(0, 5)) = 3.0
        _Phase3("Wave 3 Phase", Range(0, 6.28)) = 0.5
        _Speed3("Wave 3 Speed", Range(0, 2)) = 1.5
        _Amplitude4("Wave 4 Amplitude", Range(0, 2)) = 0.3
        _Frequency4("Wave 4 Frequency", Range(0, 5)) = 3.0
        _Phase4("Wave 4 Phase", Range(0, 6.28)) = 0.5
        _Speed4("Wave 4 Speed", Range(0, 2)) = 1.5
        _Amplitude5("Wave 5 Amplitude", Range(0, 2)) = 0.4
        _Frequency5("Wave 5 Frequency", Range(0, 5)) = 2.8
        _Phase5("Wave 5 Phase", Range(0, 6.28)) = 1.8
        _Speed5("Wave 5 Speed", Range(0, 2)) = 1.4
    }

    SubShader
    {
        Tags { "RenderType"="Transparent" "Queue"="Transparent" }
        LOD 200

        CGPROGRAM
        #pragma surface surf Standard fullforwardshadows
        #pragma target 3.0

        sampler2D _MainTex;

        struct Input
        {
            float2 uv_MainTex;
            float3 worldPos;
            float3 viewDir;
        };

        half _Glossiness;
        half _Metallic;
        fixed4 _Color;
        half _WaveHeight;
        half _WaveSpeed;
        half _FresnelPower;
        half _FresnelIntensity;
        fixed4 _RimColor;
        half _RimIntensity;
        half _RimPower;
        half _Amplitude1, _Amplitude2, _Amplitude3, _Amplitude4, _Amplitude5;
        half _Frequency1, _Frequency2, _Frequency3, _Frequency4, _Frequency5;
        half _Phase1, _Phase2, _Phase3, _Phase4, _Phase5;
        half _Speed1, _Speed2, _Speed3, _Speed4, _Speed5;

        fixed2 GerstnerWave(fixed2 position, fixed2 direction, half amplitude, half frequency, half phase, half speed)
        {
            fixed2 result;
            float wave = _Time.y * speed + frequency * dot(direction, position) + phase;
            result.x = direction.x * amplitude * sin(wave);
            result.y = amplitude * cos(wave);
            return result;
        }

        fixed3 RimLighting(float3 viewDir, float3 normal)
        {
            half rim = 1.0 - saturate(dot(normalize(viewDir), normal));
            rim = _RimIntensity * pow(rim, _RimPower);
            return rim * _RimColor.rgb;
        }

        fixed2 EnhancedUV(fixed2 uv, fixed3 worldPos)
        {
            fixed2 distortion = float2(0, 0);
            distortion += GerstnerWave(worldPos.xz, float2(1, 0.5), _Amplitude1, _Frequency1, _Phase1, _Speed1);
            distortion += GerstnerWave(worldPos.xz, float2(0.7, 1.3), _Amplitude2, _Frequency2, _Phase2, _Speed2);
            distortion += GerstnerWave(worldPos.xz, float2(-0.6, 0.8), _Amplitude3, _Frequency3, _Phase3, _Speed3);
            distortion += GerstnerWave(worldPos.xz, float2(0.9, -0.5), _Amplitude4, _Frequency4, _Phase4, _Speed4);
            distortion += GerstnerWave(worldPos.xz, float2(-0.8, -0.6), _Amplitude5, _Frequency5, _Phase5, _Speed5);
            return uv + distortion * 0.01;
        }

        fixed3 ComputeNormal(fixed3 worldPos)
        {
            fixed2 waveOffset1 = GerstnerWave(worldPos.xz, float2(1, 0.5), _Amplitude1, _Frequency1, _Phase1, _Speed1);
            fixed2 waveOffset2 = GerstnerWave(worldPos.xz, float2(0.7, 1.3), _Amplitude2, _Frequency2, _Phase2, _Speed2);
            fixed2 waveOffset3 = GerstnerWave(worldPos.xz, float2(-0.6, 0.8), _Amplitude3, _Frequency3, _Phase3, _Speed3);
            fixed2 waveOffset4 = GerstnerWave(worldPos.xz, float2(0.9, -0.5), _Amplitude4, _Frequency4, _Phase4, _Speed4);
            fixed2 waveOffset5 = GerstnerWave(worldPos.xz, float2(-0.8, -0.6), _Amplitude5, _Frequency5, _Phase5, _Speed5);
            float totalOffsetX = waveOffset1.x + waveOffset2.x + waveOffset3.x + waveOffset4.x + waveOffset5.x;
            float totalOffsetY = waveOffset1.y + waveOffset2.y + waveOffset3.y + waveOffset4.y + waveOffset5.y;

            fixed3 normal = normalize(float3(-totalOffsetX, 1.0, -totalOffsetY));
            return normal;
        }

        void surf (Input IN, inout SurfaceOutput o)
        {
            fixed3 worldNormal = ComputeNormal(IN.worldPos);
            o.Normal = worldNormal;

            fixed4 c = tex2D(_MainTex, EnhancedUV(IN.uv_MainTex, IN.worldPos)) * _Color;
            o.Albedo = c.rgb;
            o.Metallic = _Metallic;
            o.Smoothness = _Glossiness;
            o.Alpha = c.a;

            fixed fresnel = _FresnelIntensity * pow(1.0 + dot(IN.viewDir, worldNormal), _FresnelPower);
            o.Emission = RimLighting(IN.viewDir, worldNormal) + fresnel;
        }

        ENDCG
    }

    Pass
    {
        Name "ForwardBase"
        Tags { "LightMode"="ForwardBase" }
    }

    Pass
    {
        Name "ForwardAdd"
        Tags { "LightMode"="ForwardAdd" }
    }
}

void surf (Input IN, inout SurfaceOutputStandard o)
{
    fixed3 worldNormal = ComputeNormal(IN.worldPos);
    o.Normal = worldNormal;

    fixed4 c = tex2D(_MainTex, EnhancedUV(IN.uv_MainTex, IN.worldPos)) * _Color;
    o.Albedo = c.rgb;
    o.Specular = _Metallic;
    o.Smoothness = _Glossiness;
    o.Alpha = c.a;

    fixed fresnel = _FresnelIntensity * pow(1.0 + dot(IN.viewDir, worldNormal), _FresnelPower);
    o.Emission = RimLighting(IN.viewDir, worldNormal) + fresnel;
}

fixed2 GerstnerWave(fixed2 position, fixed2 direction, half amplitude, half frequency, half phase, half speed)
{
    return float2(0, 0);
}

fixed3 RimLighting(float3 viewDir, float3 normal)
{
    half rim = 1.0 - saturate(dot(normalize(viewDir), normal));
    rim = _RimIntensity * pow(rim, _RimPower);
    return rim * _RimColor.rgb;
}

// Custom shader named "Gerstner Waves Water Shader"
Shader "Custom/Gerstner Waves Water Shader"
{
    // Properties block contains all the editable parameters exposed in the material editor
    Properties
    {
        // Basic properties
        _Color("Color", Color) = (1,1,1,1)   // Base color of the water
        _MainTex("Albedo (RGB)", 2D) = "white" {} // Texture for the water surface
        _Glossiness("Smoothness", Range(0,1)) = 0.5 // Smoothness of the surface reflection
        _Metallic("Metallic", Range(0,1)) = 0.0    // Metallic property for PBR rendering
        _FresnelPower("Fresnel Power", Range(1,5)) = 2.0 // Power for fresnel effect
        _FresnelIntensity("Fresnel Intensity", Range(0,1)) = 0.6 // Intensity of fresnel effect

        // Properties for Gerstner Waves - using five waves
        _Amplitude1("Wave 1 Amplitude", Range(0, 2)) = 0.5
        _Frequency1("Wave 1 Frequency", Range(0, 5)) = 2.0
        _Phase1("Wave 1 Phase", Range(0, 6.28)) = 1.0
        _Speed1("Wave 1 Speed", Range(0, 2)) = 1.2

        _Amplitude2("Wave 2 Amplitude", Range(0, 2)) = 0.35
        _Frequency2("Wave 2 Frequency", Range(0, 5)) = 2.5
        _Phase2("Wave 2 Phase", Range(0, 6.28)) = 2.0
        _Speed2("Wave 2 Speed", Range(0, 2)) = 1.3

        _Amplitude3("Wave 3 Amplitude", Range(0, 2)) = 0.45
        _Frequency3("Wave 3 Frequency", Range(0, 5)) = 3.0
        _Phase3("Wave 3 Phase", Range(0, 6.28)) = 0.5
        _Speed3("Wave 3 Speed", Range(0, 2)) = 1.5

        _Amplitude4("Wave 4 Amplitude", Range(0, 2)) = 0.3
        _Frequency4("Wave 4 Frequency", Range(0, 5)) = 3.0
        _Phase4("Wave 4 Phase", Range(0, 6.28)) = 0.5
        _Speed4("Wave 4 Speed", Range(0, 2)) = 1.5

        _Amplitude5("Wave 5 Amplitude", Range(0, 2)) = 0.4
        _Frequency5("Wave 5 Frequency", Range(0, 5)) = 2.8
        _Phase5("Wave 5 Phase", Range(0, 6.28)) = 1.8
        _Speed5("Wave 5 Speed", Range(0, 2)) = 1.4
    }

    // Subshader block: contains the actual code that renders the material
    SubShader
    {
        // Tags are used to provide additional information about how the shader should be used.
        Tags { "RenderType" = "Transparent" "Queue" = "Transparent"}
        LOD 200  // Level of Detail: specifies the shader's complexity

        // Start of shader program
        CGPROGRAM
        #pragma surface surf Standard fullforwardshadows  // Surface shader pragma directive
        #pragma target 3.0  // Shader target for compatibility

        sampler2D _MainTex; // Texture sampler

        // Input struct: contains input data to the surface shader
        struct Input
        {
            float2 uv_MainTex;  // UV coordinates for main texture
            float3 worldPos;    // World position of the pixel
            float3 viewDir;     // Direction from pixel to camera
        };

        // Variables declared from properties
        half _Glossiness;
        half _Metallic;
        fixed4 _Color;
        half _FresnelPower;
        half _FresnelIntensity;

        // Variables for Gerstner Waves
        half _Amplitude1, _Amplitude2, _Amplitude3, _Amplitude4, _Amplitude5;
        half _Frequency1, _Frequency2, _Frequency3, _Frequency4, _Frequency5;
        half _Phase1, _Phase2, _Phase3, _Phase4, _Phase5;
        half _Speed1, _Speed2, _Speed3, _Speed4, _Speed5;

        // Function for Gerstner Wave calculation
        fixed2 GerstnerWave(fixed2 position, fixed2 direction, half amplitude, half frequency, half phase, half speed)
        {
            fixed2 result;
            float wave = _Time.y * speed + frequency * dot(direction, position) + phase;
            result.x = direction.x * amplitude * sin(wave);
            result.y = amplitude * cos(wave);
            return result;
        }

        // Main surface shader function
        void surf(Input IN, inout SurfaceOutputStandard o)
        {
            // Calculate the Gerstner Waves
            fixed3 finalWavePosition = IN.worldPos;
            finalWavePosition.xy += GerstnerWave(IN.worldPos.xz, float2(1, 0.5) * sin(_Time.y * 0.2), _Amplitude1, _Frequency1, _Phase1, _Speed1);
            finalWavePosition.xy += GerstnerWave(IN.worldPos.xz, float2(0.7, 1.3) * sin(_Time.y * 0.3), _Amplitude2, _Frequency2, _Phase2, _Speed2);
            finalWavePosition.xy += GerstnerWave(IN.worldPos.xz, float2(-0.6, 0.8) * sin(_Time.y * 0.4), _Amplitude3, _Frequency3, _Phase3, _Speed3);
            finalWavePosition.xy += GerstnerWave(IN.worldPos.xz, float2(0.9, -0.5) * sin(_Time.y * 0.5), _Amplitude4, _Frequency4, _Phase4, _Speed4);
            finalWavePosition.xy += GerstnerWave(IN.worldPos.xz, float2(-0.8, -0.6) * sin(_Time.y * 0.6), _Amplitude5, _Frequency5, _Phase5, _Speed5);

            // Apply texture and waves to the surface
            fixed2 uv = IN.uv_MainTex + finalWavePosition.xy * 0.01;
            fixed4 c = tex2D(_MainTex, uv) * _Color;

            // Calculate fresnel effect
            half fresnel = pow(1.0 - dot(normalize(IN.viewDir), o.Normal), _FresnelPower);
            o.Albedo = lerp(c.rgb, _Color.rgb * _FresnelIntensity, fresnel);
            o.Metallic = _Metallic;
            o.Smoothness = _Glossiness;
            o.Alpha = c.a;
            o.Normal = normalize(float3(0, 1, finalWavePosition.y));
        }
        ENDCG  // End of shader program
    }

    // If the shader fails, it will fall back to a basic diffuse shader
    FallBack "Diffuse"
}

// A SubShader is a collection of passes. Unity uses the first SubShader that runs on the user's graphics card.
SubShader
{
    // These tags make the shader render as transparent, ensuring that objects behind it are rendered.
    Tags { "RenderType" = "Transparent" "Queue" = "Transparent"}

    // Level of Detail - If the camera is far from the object, a simpler version of the shader might be used for optimization.
    // A value of 200 suggests a moderately complex shader.
    LOD 200

    // Start of the shader program written in CG/HLSL language.
    CGPROGRAM

    // This tells Unity to use the "surf" function for surface shaders. 
    // "Standard" is the lighting model and "fullforwardshadows" enables shadows on transparent objects.
    #pragma surface surf Standard fullforwardshadows

    // The shader is intended to be run on hardware that supports Shader Model 3.0.
    #pragma target 3.0

    // Texture sampler for the main texture (_MainTex) that the material will use.
    sampler2D _MainTex;

    // Input struct defines the data that will be available in the surf function.
    struct Input
    {
        float2 uv_MainTex;       // UV coordinates for the main texture.
        float3 worldPos;         // World position of the current pixel/vertex.
        float3 viewDir;          // Direction from the camera to the current pixel/vertex.
    };

    // Shader properties - these can be set from Unity's material inspector.
    half _Glossiness;         // Controls the shininess of the surface.
    half _Metallic;           // Defines how "metal-like" the surface appears.
    fixed4 _Color;            // The base color of the material.
    half _FresnelPower;       // Controls the strength of the Fresnel effect (reflectivity at shallow angles).
    half _FresnelIntensity;   // Controls the intensity of the Fresnel effect.

