/* 1. Define appealing and cute colors in index.css */

:root {
  --bg: rgb(61, 13, 123);
  --fg: rgb(8, 1, 14);

  --field-border: rgba(255, 255, 255, 0.29);
  --field-border-focus: rgba(149, 0, 255, 1);
  --field-bg: rgb(31, 31, 31);
}

/* 2. Set box-sizing and background color for all elements in index.css */

* {
  box-sizing: border-box;
  background-color: var(--bg);
}

/* 3. Update background color for .content in src/app.css */

.content {
  background: var(--fg);
}

/* 4. Update border-bottom style in .activity_item class in components/ActivityItem.css */

.activity_item {
  border-bottom: solid 1px rgb(60, 54, 79);
}

/* 5. Change color in section footer links in components/DesktopSidebar.css */

section footer a {
  color: rgba(255, 255, 255, 0.5);
}

/* 6. Update background and border styles for .search_field input[type='text'] in components/JoinSection.css */

.search_field input[type='text'] {
  background: var(--fg);
  border: solid 1px var(--field-border);
}

/* 7. Update border style for focused .search_field input[type='text'] in components/JoinSection.css */

.search_field input[type='text']:focus {
  border: solid 1px var(--field-border-focus);
}

/* 8. Update border and background styles for input fields in signin-article in signinpage.css */

article.signin-article input[type='text'],
article.signin-article input[type='password'] {
  border: solid 1px var(--field-border);
  background: var(--field-bg);
}

/* 9. Update border style for focused input fields in signin-article in signinpage.css */

article.signin-article input[type='text']:focus,
article.signin-article input[type='password']:focus {
  border: solid 1px var(--field-border-focus);
}

/* 10. Update border color for input fields in signup-article in signinpage.css */

article.signup-article input[type='text'],
article.signup-article input[type='password'] {
  border: solid 1px var(--field-border);
}

/* 11. Update border color for focused input fields in signup-article in signinpage.css */

article.signup-article input[type='text']:focus,
article.signup-article input[type='password']:focus {
  border: solid 1px var(--field-border-focus);
}

