import { ItemView, WorkspaceLeaf } from 'obsidian';

export default class HelloWorldView extends ItemView {
    constructor(leaf: WorkspaceLeaf) {
        super(leaf);
    }

    getViewType(): string {
        return 'hello-world-view';
    }

    getDisplayText(): string {
        return 'Hello World View';
    }

    getIcon(): string {
        return 'dot-network';  // This can be any valid icon string from Obsidian's icon set.
    }

    async onOpen() {
        const div = this.contentEl.createDiv('hello-world-div');
        div.setText('Hello World');
    }
}

import { h, render } from 'preact';

export async function InitPostProcessor(wt: WTPlugin) {
    wt.registerMarkdownPostProcessor((el, ctx) => {
        console.log("Markdown Post Processing:", el, ctx)
        const wtFile = ctx.frontmatter?.hasOwnProperty("web-tester-plugin");
        if (wtFile) {
            // Clear the existing content
            el.innerHTML = '';

            // Render the custom Preact content into the element
            const content = <div>Hello World from TSX!</div>;
            render(content, el);

            return;
        }
    });
}

