// 1. Initialize variables
let sections = document.querySelectorAll('section');
let observer;
let sectionRatios = new Map(); // 2. Store intersection ratios

// 3. Observer options
const options = {
  root: null,
  rootMargin: '0px',
  threshold: 0.1 // 4. Lower threshold
};

// 5. Observer callback
const handleIntersection = (entries) => {
  entries.forEach((entry) => {
    sectionRatios.set(entry.target, entry.intersectionRatio); // 6. Update ratios
  });

  // 7. Find the most visible section
  let mostVisible = [...sectionRatios.entries()].reduce((max, [section, ratio]) => {
    return ratio > max[1] ? [section, ratio] : max;
  }, [null, 0])[0];

  // 8. Update CSS class
  sections.forEach((section) => {
    section.classList.remove('main');
  });

  if (mostVisible) {
    mostVisible.classList.add('main');
  }
};

// 9. Create and observe
observer = new IntersectionObserver(handleIntersection, options);
sections.forEach((section) => observer.observe(section));

// 1. Initialize variables
let sections = document.querySelectorAll('section');
let observer;
let sectionRatios = new Map();
let debounceTimer; // 2. Debounce timer

// 3. Observer options
const options = {
  root: null,
  rootMargin: '0px',
  threshold: 0.1
};

// 4. Debounce function
const debounce = (func, delay) => {
  clearTimeout(debounceTimer);
  debounceTimer = setTimeout(() => {
    func();
  }, delay);
};

// 5. Update CSS class
const updateClass = () => {
  let mostVisible = [...sectionRatios.entries()].reduce((max, [section, ratio]) => {
    return ratio > max[1] ? [section, ratio] : max;
  }, [null, 0])[0];

  sections.forEach((section) => {
    section.classList.remove('main');
  });

  if (mostVisible) {
    mostVisible.classList.add('main');
  }
};

// 6. Observer callback
const handleIntersection = (entries) => {
  entries.forEach((entry) => {
    sectionRatios.set(entry.target, entry.intersectionRatio);
  });

  debounce(updateClass, 100); // 7. Debounce the update
};

// 8. Create and observe
observer = new IntersectionObserver(handleIntersection, options);
sections.forEach((section) => observer.observe(section));

