// 1. Select all elements with [contenteditable] attribute
const $foos = Array.from(document.querySelectorAll("[contenteditable]")) as HTMLElement[];

$foos.forEach(($el) => {
  $el.addEventListener("paste", async (event: ClipboardEvent) => {
    event.preventDefault();

    // 2. Type guard for event.target
    if (event.target instanceof HTMLElement) {
      // 3. Use Clipboard API to read the clipboard data
      const text = await navigator.clipboard.readText();

      // 4. Insert the text at the cursor position
      document.execCommand("insertText", false, text);
    }
  });
});

// 1. Select all elements with [contenteditable] attribute
const $foos = Array.from(document.querySelectorAll("[contenteditable]")) as HTMLElement[];

$foos.forEach(($el) => {
  $el.addEventListener("paste", async (event: ClipboardEvent) => {
    event.preventDefault();

    // 2. Type guard for event.target
    if (event.target instanceof HTMLElement) {
      // 3. Use Clipboard API to read the clipboard data
      const text = await navigator.clipboard.readText();

      // 4. Use Selection and Range APIs to insert text
      const selection = window.getSelection();
      if (selection && selection.rangeCount > 0) {
        const range = selection.getRangeAt(0);
        range.deleteContents();
        const textNode = document.createTextNode(text);
        range.insertNode(textNode);
        range.setStartAfter(textNode);
        selection.removeAllRanges();
        selection.addRange(range);
      }
    }
  });
});

function formatTime(seconds) {
  // 1. Calculate the hours, minutes, and remaining seconds
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const remainingSeconds = seconds % 60;

  // 2. Convert the hours, minutes, and seconds to strings, padding with zeros if necessary
  const hoursStr = hours.toString().padStart(2, '0');
  const minutesStr = minutes.toString().padStart(2, '0');
  const secondsStr = remainingSeconds.toString().padStart(2, '0');

  // 3. Construct the formatted time string, omitting the hours if they are zero
  return hours === 0 ? `${minutesStr}:${secondsStr}` : `${hoursStr}:${minutesStr}:${secondsStr}`;
}

console.log(formatTime(108)); // "01:48"
console.log(formatTime(5538)); // "01:32:38"

function formatTime(seconds) {
  const h = Math.floor(seconds / 3600).toString().padStart(2, '0');
  const m = Math.floor((seconds % 3600) / 60).toString().padStart(2, '0');
  const s = (seconds % 60).toString().padStart(2, '0');
  return h === '00' ? `${m}:${s}` : `${h}:${m}:${s}`;
}

console.log(formatTime(108)); // "01:48"
console.log(formatTime(5538)); // "01:32:38"

