import { spawn } from 'child_process';

function executeAndForwardOutput(code, next) {
  const child = spawn(code, { shell: true });
  let commandOutput = '';

  child.stdout.on('data', (data) => {
    console.log(`${data}`);
    commandOutput += data;
  });

  child.stderr.on('data', (data) => {
    console.error(`${data}`);
    commandOutput += data;
  });

  child.on('close', (code) => {
    next(code, commandOutput);
  });
}

export { executeAndForwardOutput };
EOF

# Step 2 and 3: Updating executeAndForwardOutput function to validate shebang and write code to file
cat << 'EOF' > ./src/execute/executeAndForwardOutput.js
import { spawn, writeFile } from 'fs/promises';
import { spawn as spawnSync } from 'child_process';

function executeAndForwardOutput(code, next) {
  // Check if the code starts with a shebang
  if (!code.startsWith('#!')) {
    throw new Error('Code does not start with a shebang');
  }

  // Write code to change.sh
  writeFile('./change.sh', code)
    .then(() => {
      const child = spawnSync('./change.sh', { shell: true });
      let commandOutput = '';

      child.stdout.on('data', (data) => {
        console.log(`${data}`);
        commandOutput += data;
      });

      child.stderr.on('data', (data) => {
        console.error(`${data}`);
        commandOutput += data;
      });

      child.on('close', (code) => {
        next(code, commandOutput);
      });
    })
    .catch((err) => {
      console.error(err);
    });
}

export { executeAndForwardOutput };
EOF

