#!/bin/sh
# Goal: Reprint prompt descriptor on changes
# Plan:
# 1. We are going to use the Node.js 'fs' module's 'watch' function to monitor changes to the prompt descriptor file.
# 2. For this, we will create a new file "watchPromptDescriptor.js" in the "prompt" directory.
# 3. This file will export a function 'watchPromptDescriptor' which takes 'rawPrinter' as an argument, similar to 'loadPromptDescriptor'.
# 4. Inside this function, we will set up a watcher for the prompt descriptor file, and on any changes, we will invoke 'loadPromptDescriptor' to reprint the content.
# 5. Finally, in 'startInteractiveSession', we will invoke 'watchPromptDescriptor' to begin monitoring changes to the prompt descriptor file.

cat > ./src/prompt/watchPromptDescriptor.js << 'EOF'
import fs from 'fs';
import { loadPromptDescriptor } from './loadPromptDescriptor.js';

const descriptorFileName = "prompt.yaml";

const watchPromptDescriptor = (rawPrinter) => {
  fs.watch(descriptorFileName, async (event, filename) => {
    if (event === 'change' && filename === descriptorFileName) {
      await loadPromptDescriptor(rawPrinter);
    }
  });
};

export default watchPromptDescriptor;
EOF

# Modify the startInteractiveSession.js file to import and use watchPromptDescriptor function
sed -i -e $'s/import { loadPromptDescriptor } from \'..\/prompt\/loadPromptDescriptor.js\';/import { loadPromptDescriptor } from \'..\/prompt\/loadPromptDescriptor.js\';\nimport watchPromptDescriptor from \'..\/prompt\/watchPromptDescriptor.js\';/g' ./src/interactiveSession/startInteractiveSession.js

sed -i -e $'s/await loadPromptDescriptor(console.log);/await loadPromptDescriptor(console.log);\n  watchPromptDescriptor(console.log);/g' ./src/interactiveSession/startInteractiveSession.js

EOF

