echo "Done."

import { fileURLToPath } from 'url';
import { dirname } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

import { createSignal } from 'solid-js';
import { marked } from 'marked';
import copy from 'clipboard-copy';
import { generatePrompt } from './generatePrompt';

const App = () => {
  const [notes, setNotes] = createSignal('');
  const [prompt, setPrompt] = createSignal('');

  const handleGeneratePrompt = async () => {
    const response = await generatePrompt(notes());

    // Copy original markdown to clipboard
    copy(response.prompt)
      .then(() => {
        console.log('Prompt copied to clipboard!');
      })
      .catch(err => {
        console.error('Failed to copy prompt: ', err);
      });

    // Convert markdown to HTML for display
    const htmlPrompt = marked(response.prompt);

    setPrompt(htmlPrompt);
  };

  return (
    <>
      <input type="text" value={notes()} onInput={e => setNotes(e.target.value)} />
      <button onClick={handleGeneratePrompt}>Start</button>
      <div innerHTML={prompt()}></div>
    </>
  );
};

export default App;

export default {
  esbuild: {
    jsxFactory: 'Solid.h',
    jsxFragment: 'Solid.Fragment'
  },
  plugins: [],
  build: {
    target: 'es2015'
  }
};

import express from 'express';
import cors from 'cors';
import { createPrompt } from './prompt/createPrompt.js';
import { saveAndSendPrompt } from './interactiveSession/saveAndSendPrompt.js';
import { api } from './config.js'; // Import your api object

const app = express();

// Enable CORS for all routes
app.use(cors());

app.use(express.json());

app.post('/generate', async (req, res) => {
  const { notes } = req.body;
  const { prompt, saveto } = await createPrompt(notes);
  const result = await saveAndSendPrompt(prompt, saveto, null, api); // pass the api object here
  res.json({ prompt: result });
});

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});

/// Unescape and push json strings
static int ndb_builder_push_json_str(struct ndb_builder *builder,
				     const char *str, int len,
				     union packed_str *pstr)
{
	// let's not care about de-duping these. we should just unescape
	// in-place directly into the strings table. 

	// TODO: we still want single-char packed strings

	const char *p, *end, *start;

	end = str + len;
	start = str; // Initialize start to the beginning of the string

	*pstr = ndb_offset_str(builder->strings.p - builder->strings.start);

	for (p = str; p < end; p++) {
		if (*p == '\\' && p+1 < end) {
			// Push the chunk of unescaped characters before this escape sequence
			if (start < p && !cursor_push(&builder->strings, start, p - start))
				return 0;

			switch (*(p+1)) {
			case 't':
				if (!cursor_push_byte(&builder->strings, '\t'))
					return 0;
				break;
			case 'n':
				if (!cursor_push_byte(&builder->strings, '\n'))
					return 0;
				break;
			case 'r':
				if (!cursor_push_byte(&builder->strings, '\r'))
					return 0;
				break;
			case 'b':
				if (!cursor_push_byte(&builder->strings, '\b'))
					return 0;
				break;
			case 'f':
				if (!cursor_push_byte(&builder->strings, '\f'))
					return 0;
				break;
			case '\\':
				if (!cursor_push_byte(&builder->strings, '\\'))
					return 0;
				break;
			case '"':
				if (!cursor_push_byte(&builder->strings, '"'))
					return 0;
				break;
			case 'u':
				// these aren't handled yet
				return 0;
			default:
				if (!cursor_push_byte(&builder->strings, *p) ||
				    !cursor_push_byte(&builder->strings, *(p+1)))
					return 0;
				break;
			}

			p++; // Skip the character following the backslash
			start = p + 1; // Update the start pointer to the next character
		}
	}

	// Handle the last chunk after the last escape sequence (or if there are no escape sequences at all)
	if (start < p && !cursor_push(&builder->strings, start, p - start))
		return 0;

	return cursor_push_byte(&builder->strings, '\0');
}

