#!/bin/sh
# Goal: Improve code execution and output forwarding
# Plan:
# 1. Create a new function writeToFile that writes the command to be executed into a file called 'change.sh'
# 2. Create a new function forwardOutput that handles the forwarding of output to the terminal
# 3. Modify the executeCode function to use the new functions and remove the redundant parts

# Step 1: Create writeToFile.js
cat << 'EOF' > src/execute/writeToFile.js
import { writeFile } from 'fs';

function writeToFile(code) {
  return new Promise((resolve, reject) => {
    writeFile('./change.sh', code, (err) => {
      if (err) {
        reject(err);
      } else {
        resolve();
      }
    });
  });
}

export { writeToFile };
EOF

# Step 2: Create forwardOutput.js
cat << 'EOF' > src/execute/forwardOutput.js
function forwardOutput(stdout, stderr) {
  let output = "";
  if (stdout.length > 0) {
    console.log(stdout);
    output += stdout;
  }
  if (stderr.length > 0) {
    console.log(stderr);
    output += stderr;
  }
  return output;
}

export { forwardOutput };
EOF

# Step 3: Modify executeCode.js
cat << 'EOF' > src/execute/executeCode.js
#!/usr/bin/env node

import { startInteractiveSession } from "../interactiveSession/startInteractiveSession.js";
import { exec } from 'child_process';
import { writeToFile } from './writeToFile.js';
import { forwardOutput } from './forwardOutput.js';

const executeCode = async (code, last_command_result, parent_message_id, rl) => {
  rl.question('\x1b[1mEXECUTE? [y/n]\x1b[0m ', async (answer) => {
    console.log("");
    if (answer.toLowerCase() === 'y' || answer === "") {
      await writeToFile(code);
      exec(code, (error, stdout, stderr) => {
        if (error) {
          console.error(error.message);
          last_command_result = "Command failed. Output:\n" + error.message + "\n";
        } else {
          let output = forwardOutput(stdout, stderr);
          last_command_result = "Command executed. Output:\n" + output + "\n";
        }
        startInteractiveSession(last_command_result, parent_message_id, rl)
      });
    } else {
      last_command_result = "Command skipped.\n";
      startInteractiveSession(last_command_result, parent_message_id, rl);
    }
  });
}

export { executeCode };
EOF

