#!/bin/sh
# Goal: Make the app mobile friendly and add necessary headers to the HTML.
# Plan:
# 1. Configure Tailwind CSS to optimize for mobile by setting up "mobile-first" breakpoints.
# 2. Modify the CSS classes in App.jsx for responsive design.
# 3. Add necessary meta tags in the index.html for viewport control and mobile browser optimizations.

# Step 1: Configure Tailwind CSS for mobile optimization
# Since Tailwind CSS is a mobile-first framework, it's designed to build responsive designs from the smallest device first and then layer on styles for larger screens.
# This allows us to write mobile-optimized styles by default and then add any necessary modifications for larger screens as required.
# In the tailwind.config.js file, we'll add a 'xs' breakpoint to optimize for smaller mobile screens.

cat > tailwind.config.js << 'EOF'
module.exports = {
  content: ['./src/**/*.html', './src/**/*.js', './src/**/*.jsx', './src/**/*.tsx', './src/**/*.ts'],
  theme: {
    screens: {
      'xs': '320px',
      'sm': '640px',
      'md': '768px',
      'lg': '1024px',
      'xl': '1280px',
      '2xl': '1536px',
    },
    extend: {
      // Extend the spacing for larger gaps
      spacing: {
        '72': '18rem',
        '84': '21rem',
        '96': '24rem',
        '128': '32rem',
      },
      // Extend the button styles for larger buttons
      fontSize: {
        'btn': '1.5rem',
      },
      padding: {
        'btn': '1.5rem',
      },
      // Extend the maxWidth for desktop container
      maxWidth: {
        'desktop': '640px',
      },
    },
  },
  variants: {
    extend: {},
  },
  plugins: [],
}
EOF

# Step 2: Modify CSS classes in App.jsx for responsive design
# We'll add responsive design CSS classes in App.jsx file so that the components respond well to different screen sizes.

cat > src/frontend/App.jsx << 'EOF'
import NotesInput from './components/NotesInput';
import StartButton from './components/StartButton';
import PromptDisplay from './components/PromptDisplay';
import TasksList from './components/TasksList';
import PromptDescriptor from './components/PromptDescriptor';
import NavBar from './components/NavBar';
import { notes, setNotes } from './stores/notes';
import { setPrompt } from './stores/prompt';

const App = () => {
  return (
    <div class="max-w-desktop lg:max-w-desktop md:max-w-full sm:max-w-full xs:max-w-full mx-auto flex flex-col items-center space-y-8 sm:p-0">
      <NavBar />
      <TasksList />
      <PromptDescriptor />
      <NotesInput notes={notes} setNotes={setNotes} />
      <StartButton notes={notes} setPrompt={setPrompt} />
      <PromptDisplay />
    </div>
  );
};

export default App;
EOF

# Step 3: Add necessary meta tags in index.html
# We'll add the viewport meta tag to control the layout on mobile browsers and make the app more mobile-friendly.
# The initial-scale property controls the zoom level when the page is first loaded. The maximum-scale, minimum-scale, and user-scalable properties control how users are allowed to zoom the page in or out.

cat > src/index.html << 'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no">
  <title>Junior</title>
</head>
<body>
  <div id="app"></div>
  <script type="module" src="/frontend/index.jsx"></script>
</body>
</html>
EOF

#!/bin/sh
# Goal: Exclude "change.sh" in writeAttention function
# Plan:
# 1. Modify the existing writeAttention function in writeAttention.ts.
# 2. Add the "change.sh" to the filtering conditions to exclude it.

cat > integrations/vscode/src/writeAttention.ts <<'EOF'
import * as vscode from 'vscode';
import * as fs from 'fs';
import * as path from 'path';
import * as yaml from 'js-yaml';
import * as glob from 'glob';

export const writeAttention = async () => {
    const workspaceFolders = vscode.workspace.workspaceFolders;
    if (workspaceFolders === undefined) {
        return;
    }

    const rootFolder = workspaceFolders[0].uri.fsPath;
    const promptFilePath = path.join(rootFolder, 'prompt.yaml');
    const excludeList = vscode.workspace.getConfiguration('junior').get('attentionExcludeList', []);
    try {
        if (fs.existsSync(promptFilePath)) {
            const currentWindows = vscode.workspace.textDocuments.map(doc => path.relative(rootFolder, doc.fileName));
            const filteredWindows = currentWindows.filter(windowPath => {
                return !windowPath.endsWith('.git') && windowPath !== 'prompt.yaml' && windowPath !== 'prompt.md' && windowPath !== 'change.sh' && !excludeList.some((pattern: string) => glob.sync(pattern, { cwd: rootFolder }).includes(windowPath)) && fs.existsSync(path.join(rootFolder, windowPath));
            });
            const promptFile = yaml.load(fs.readFileSync(promptFilePath, 'utf8'));
            promptFile.attention = filteredWindows;
            fs.writeFileSync(promptFilePath, yaml.dump(promptFile), 'utf8');
            vscode.window.showInformationMessage('Prompt file updated successfully!');
        } else {
            vscode.window.showErrorMessage('No prompt.yaml file found in the project root!');
        }
    } catch (error) {
        vscode.window.showErrorMessage('Error updating the prompt.yaml file!');
    }
};
EOF

#!/bin/sh
# Goal: Factor out the exclude handling and fix missing type for promptFile
# Plan:
# 1. Create a new file "filterAttentionExcludes.ts" that contains the filtering logic.
# 2. In the new file, export a function that takes an array of window paths, an exclude list, and the root folder path as parameters, and returns a filtered array of window paths.
# 3. In "writeAttention.ts", import the function from "filterAttentionExcludes.ts" and use it in place of the inline filtering logic.
# 4. Declare a type for the promptFile to avoid missing type errors.

# Create filterAttentionExcludes.ts with the new filtering function
cat > integrations/vscode/src/filterAttentionExcludes.ts <<'EOF'
import * as glob from 'glob';
import * as path from 'path';
import * as fs from 'fs';

export const filterAttentionExcludes = (windowPaths, excludeList, rootFolder) => {
    return windowPaths.filter(windowPath => {
        return !windowPath.endsWith('.git') && windowPath !== 'prompt.yaml' && windowPath !== 'prompt.md' && windowPath !== 'change.sh' && !excludeList.some((pattern) => glob.sync(pattern, { cwd: rootFolder }).includes(windowPath)) && fs.existsSync(path.join(rootFolder, windowPath));
    });
}
EOF

# Modify writeAttention.ts to use the new function and declare a type for promptFile
cat > integrations/vscode/src/writeAttention.ts <<'EOF'
import * as vscode from 'vscode';
import * as fs from 'fs';
import * as path from 'path';
import * as yaml from 'js-yaml';
import { filterAttentionExcludes } from './filterAttentionExcludes';

export const writeAttention = async () => {
    const workspaceFolders = vscode.workspace.workspaceFolders;
    if (workspaceFolders === undefined) {
        return;
    }

    const rootFolder = workspaceFolders[0].uri.fsPath;
    const promptFilePath = path.join(rootFolder, 'prompt.yaml');
    const excludeList = vscode.workspace.getConfiguration('junior').get('attentionExcludeList', []);
    try {
        if (fs.existsSync(promptFilePath)) {
            const currentWindows = vscode.workspace.textDocuments.map(doc => path.relative(rootFolder, doc.fileName));
            const filteredWindows = filterAttentionExcludes(currentWindows, excludeList, rootFolder);
            const promptFile: any = yaml.load(fs.readFileSync(promptFilePath, 'utf8'));
            promptFile.attention = filteredWindows;
            fs.writeFileSync(promptFilePath, yaml.dump(promptFile), 'utf8');
            vscode.window.showInformationMessage('Prompt file updated successfully!');
        } else {
            vscode.window.showErrorMessage('No prompt.yaml file found in the project root!');
        }
    } catch (error) {
        vscode.window.showErrorMessage('Error updating the prompt.yaml file!');
    }
};
EOF

#!/bin/sh
# Goal: Load task file relative to current or project root directory
# Plan:
# 1. Extract existing `createPrompt` function from `createPrompt.js` file to a new `loadTaskTemplate.js` file
# 2. Update the `createPrompt` function in `createPrompt.js` to import the new `loadTaskTemplate` function
# 3. Update `loadTaskTemplate` function to first try loading the file relative to the current directory, if not found, load it from the project root directory

# Step 1: Extract existing `createPrompt` function to a new `loadTaskTemplate.js` file
cat << 'EOF' > ./src/prompt/loadTaskTemplate.js
import util from 'util';
import fs from 'fs';
import path from 'path';
import ejs from 'ejs';

const readFile = util.promisify(fs.readFile);

const loadTaskTemplate = async (taskTemplatePath, templateVars) => {
  try {
    // Try to read the file relative to the current directory
    return await ejs.renderFile(taskTemplatePath, templateVars, {async: true});
  } catch (err) {
    // If the file doesn't exist, try reading it from the project root directory
    const rootPath = path.resolve(__dirname, '../../', taskTemplatePath);
    return await ejs.renderFile(rootPath, templateVars, {async: true});
  }
};

export { loadTaskTemplate };

EOF

# Step 2: Update `createPrompt` function in `createPrompt.js` to import the new `loadTaskTemplate` function
cat << 'EOF' > ./src/prompt/createPrompt.js
import { readAttention } from "../attention/readAttention.js"
import util from 'util';
import fs from 'fs';
import yaml from 'js-yaml';
import ejs from 'ejs';
import { getPromptFlag } from './getPromptFlag.js';
import { getSystemPromptIfNeeded } from './getSystemPromptIfNeeded.js';
import { resolveTemplateVariables } from './resolveTemplateVariables.js';
import { extractTemplateVars } from './extractTemplateVars.js';
import { loadPromptDescriptor } from './loadPromptDescriptor.js';
import { loadTaskTemplate } from './loadTaskTemplate.js';
const readFile = util.promisify(fs.readFile);

const createPrompt = async (userInput) => {
  const promptDescriptor = yaml.load(await loadPromptDescriptor());
  let templateVars = extractTemplateVars(promptDescriptor);

  templateVars = await resolveTemplateVariables(templateVars);

  const attention = await readAttention(promptDescriptor.attention);
  const task = await loadTaskTemplate(promptDescriptor.task, templateVars);
  const format = await ejs.renderFile(promptDescriptor.format, templateVars, {async: true});
  const system = await getSystemPromptIfNeeded();
  const saveto = promptDescriptor.saveto;
  return {
    prompt: `# Working set\n\n${attention.join("\n")}\n\n# Task\n\n${task}\n\n# Output Format\n\n${format}\n\n${userInput ? userInput : ""}`,
    saveto
  };
}

export { createPrompt };

EOF

#!/bin/bash

# Create the promptProcessing.js file
cat <<EOF > ./src/promptProcessing.js
import { createPrompt } from './prompt/createPrompt.js';
import fs from 'fs/promises';

const processPrompt = async (task, last_command_result, saveto = 'current_prompt.md', parent_message_id = null) => {
  const { prompt, saveto: newSaveto } = await createPrompt(task, last_command_result);
  await fs.writeFile(newSaveto || saveto, prompt);
  return { prompt, parent_message_id };
}

export default processPrompt;
EOF

# Modify the startInteractiveSession.js file
cat <<EOF > ./src/interactiveSession/startInteractiveSession.js
import processPrompt from '../promptProcessing.js';
import { saveAndSendPrompt } from './saveAndSendPrompt.js';

const startInteractiveSession = async (last_command_result = "", parent_message_id = null, rl, api) => {
  rl.question('$ ', async (task) => {
    const { prompt, parent_message_id: newParentMessageId } = await processPrompt(task, last_command_result);
    await saveAndSendPrompt(prompt, newParentMessageId, api, rl, last_command_result, startInteractiveSession);
  });
};

export { startInteractiveSession };
EOF

# Modify the server.js file
cat <<EOF > ./src/server.js
import express from 'express';
import cors from 'cors';
import processPrompt from './promptProcessing.js';

const app = express();

app.use(cors());
app.use(express.json());

app.post('/generate', async (req, res) => {
  const { notes } = req.body;
  const { prompt } = await processPrompt(notes);
  res.json({ prompt });
});

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
EOF

