uses
  WinInet, System.SysUtils;

function GetWebContent(URL: String): String;
var
  hInternet, hConnect: HINTERNET;
  Buffer: array[0..4096] of Char;
  BytesRead: DWORD;
begin
  Result := '';
  hInternet := InternetOpen('Delphi App', INTERNET_OPEN_TYPE_DIRECT, nil, nil, 0);
  try
    hConnect := InternetOpenUrl(hInternet, PChar(URL), nil, 0, INTERNET_FLAG_RELOAD, 0);
    try
      repeat
        InternetReadFile(hConnect, @Buffer, SizeOf(Buffer), BytesRead);
        Result := Result + Copy(Buffer, 1, BytesRead);
      until BytesRead = 0;
    finally
      InternetCloseHandle(hConnect);
    end;
  finally
    InternetCloseHandle(hInternet);
  end;
end;

