#!/bin/sh
set -e
goal="Save content and execute change on paste"
echo "Plan:"
echo "1. Modify ExecuteButton.jsx to handle the textarea change and execute it."
echo "2. The modifications include saving the change content and triggering the execution immediately."

cat > src/frontend/components/ExecuteButton.jsx << 'EOF'
import { createEffect, createSignal } from 'solid-js';
import { executeChange } from '../service/executeChange';
import { setExecutionResult } from '../model/executionResult';
import { setChange } from '../model/change';

const ExecuteButton = () => {
  const [inputAvailable, setInputAvailable] = createSignal(true);
  const [changeInput, setChangeInput] = createSignal('');

  const handleExecuteChange = async (input = null) => {
    let change = input || changeInput();
    if (inputAvailable() && navigator.clipboard && !input) {
      change = await navigator.clipboard.readText();
    }
    const response = await executeChange(change);
    setChange(change);
    setExecutionResult(response.output);
    console.log(response.output);
  };

  // Execute the change immediately when pasting in textarea
  const handleTextareaChange = (e) => {
    const change = e.currentTarget.value;
    setChangeInput(change);
    handleExecuteChange(change);
  };

  // Check if clipboard reading is available
  createEffect(() => {
    if (!navigator.clipboard || !navigator.clipboard.readText) {
      setInputAvailable(false);
    }
  });

  return (
    <button class="w-64 px-4 py-4 bg-orange-300 text-white rounded" onClick={() => handleExecuteChange()}>
      {inputAvailable() ? (
        'Paste & Execute Change'
      ) : (
        <textarea
          rows="1"
          class="w-full px-2 py-2 bg-white text-black resize-none"
          placeholder="Paste the change here to execute"
          value={changeInput()}
          onInput={handleTextareaChange}
        />
      )}
    </button>
  );
};

export default ExecuteButton;
EOF

echo "\033[32mDone: $goal\033[0m\n"

