import { createEffect } from 'solid-js';

const useKeyBindings = (bindings) => {
  createEffect(() => {
    const handler = (e) => {
      const action = bindings[e.key.toUpperCase()];
      if (action) {
        action(e);
      }
    };

    window.addEventListener('keydown', handler);

    return () => {
      window.removeEventListener('keydown', handler);
    };
  });
};

