from functools import reduce
from operator import or_, and_
from django.db.models import Q
from django.views.generic import ListView
from .models import LinnaeanDissertation

class LinnaeanDissertationAdvancedSearchView(ListView):
    model = LinnaeanDissertation
    context_object_name = "dissertation_list"
    template_name = "linnaean_dissertations/dissertation_advanced_search.html"
    ordering = ["liden_number_int", "liden_number"]

    def build_query(self, filter_type, field, query):
        filter_mapping = {
            "less_than": "__lt",
            "greater_than": "__gt",
            "contains": "__icontains",
        }
        query_modifier = filter_mapping.get(filter_type, "")
        if query_modifier:
            new_query = f"{field}{query_modifier}"
            if filter_type == "contains_any":
                query_list = query.split(" ")
                query_filter = reduce(or_, (Q(**{new_query: q}) for q in query_list))
            elif filter_type == "contains_all":
                query_list = query.split(" ")
                query_filter = reduce(and_, (Q(**{new_query: q}) for q in query_list))
            elif filter_type == "contains_not":
                query_filter = ~Q(**{new_query: query})
            else:
                query_filter = Q(**{new_query: query})
            return query_filter
        return Q()

    def get_queryset(self):
        query = Q()
        filter_params = [
            ("liden_number", "liden_number_filter", "liden_number_int"),
            ("respondent", "respondent_filter", "respondent_full"),
            ("title", "title_filter", "title"),
            ("real_date", "real_date_filter", "real_date"),
        ]
        for param, filter_param, field in filter_params:
            value = self.request.GET.get(param)
            if value:
                filter_type = self.request.GET.get(filter_param)
                query &= self.build_query(filter_type, field, value)
        return LinnaeanDissertation.objects.filter(query).order_by(*self.ordering)

function drawGrid() {
   clearGrid();

   for(let i = 0; i < (squareSideSize ** 2); i++) {
      const singleSquareDiv = document.createElement('div');
      singleSquareDiv.classList.add('single-square-div');
      singleSquareDiv.style.flexBasis = `calc(100% / ${squareSideSize})`;
      theGridItself.appendChild(singleSquareDiv);
   }
}

#!/bin/sh
set -e
goal="Fix onInput binding for AutoGrowingTextarea"
echo "Plan:"
echo "1. Update the AutoGrowingTextarea.jsx to bind the onInput event to the resize function."

cat > src/frontend/components/AutoGrowingTextarea.jsx << 'EOF'
import { onCleanup, onMount } from 'solid-js';

const AutoGrowingTextarea = (props) => {
  let textRef;

  const resize = () => {
    textRef.style.height = 'auto';
    textRef.style.height = textRef.scrollHeight + 'px';
  }

  // Use the onMount lifecycle hook to ensure the ref is available
  onMount(() => {
    textRef.addEventListener('input', resize, false);
    resize();  // To resize on initialization
  });

  // When the component unmounts, cleanup the event listener
  onCleanup(() => {
    textRef.removeEventListener('input', resize, false);
  });

  return (
    <textarea
      {...props}
      ref={textRef}
      onInput={resize} // Bind onInput event to the resize function
      rows="1" // Start with one row
      style="overflow:hidden" // Hide the scrollbar
    />
  );
};

export default AutoGrowingTextarea;
EOF

